/* Słowa kluczowe (kw) i pułapki egzaminacyjne do kafelków schematu COBIT 5. Przykład KG PSP w ramkach „Przykładowy proces”: przyklad-kg-psp.js. */
window.OPISY={"a1":{"kw":["struktury ramowe","zasady, polityki","polityk"],"pulapka":"Na egzaminie „Zasady, Polityki i Struktury ramowe” (podręcznik: Zasady, polityki i metodyki); polityki realizuje się przede wszystkim przez praktyki i działania procesów."},"a2":{"kw":["procesy","37 procesów"],"pulapka":"Procesy to tylko jeden z 7 aktywatorów, choć COBIT 5 opisuje ich 37 (5 Ładu i 32 Zarządzania); „37” nie jest odpowiedzią na pytanie o liczbę aktywatorów."},"a3":{"kw":["struktury organizacyjne","decyzj","eskalacj"],"pulapka":"Struktury organizacyjne to kluczowe jednostki decyzyjne; ich produktem pracy są decyzje, a dobre praktyki to m.in. zasady operacyjne, zakres kontroli i procedury eskalacji."},"a4":{"kw":["kultura, etyka","zachowani","obwiniania"],"pulapka":"Kultura, Etyka i Zachowanie są często niedoceniane. Zachowania i zachęty mogą wspierać albo osłabiać stosowanie polityk oraz procesów bezpieczeństwa."},"a5":{"kw":["informacj","zasob"],"pulapka":"Informacja to aktywator i jednocześnie zasób (Rysunek 12); polityki też są informacją, więc dobre praktyki dotyczące informacji obejmują również polityki."},"a6":{"kw":["usługi, infrastruktura i aplikacje","zdolności usługow","poziomy usług"],"pulapka":"Usługi, Infrastruktura i Aplikacje zapewniają zdolności usługowe. Dobre praktyki obejmują zasady i modele architektury, punkty widzenia oraz repozytorium. Zasady operacyjne są osobno omówione jako praktyka struktur organizacyjnych."},"a7":{"kw":["ludzie, umiejętności","kategorie umiejętności","rotacj"],"pulapka":"Ludzie, Umiejętności i Kompetencje to zasób; jego praktyką są kategorie umiejętności (Rysunek 39), a rotacja i dostępność personelu to cele jakości kontekstowej."},"akt":{"kw":["siedem kategorii","aktywator","rysunek 12"],"pulapka":"Kategorii aktywatorów jest 7 (5 to zasady, 4 to wymiary, 37 to procesy); trzy z nich są też zasobami: Informacja; Usługi, Infrastruktura i Aplikacje; Ludzie, Umiejętności i Kompetencje."},"bk_3pytania":{"kw":["kto odnosi korzyści","kto ponosi ryzyko","jakie zasoby"],"pulapka":"Trzy pytania to: kto odnosi korzyści, kto ponosi ryzyko, jakie zasoby są wymagane; pytanie „kto jest rozliczany” pochodzi z RACI, nie z tej listy."},"bk_a1_cykl":{"kw":["cykl życia polityki","aktualn","polityk"],"pulapka":"Kluczowy aspekt cyklu życia polityk to aktualność: czy i kiedy się je aktualizuje, jak informuje się pracowników o zmianach, dostęp do najnowszej wersji i archiwizacja starych."},"bk_a1_def":{"kw":["zasady, polityki","polityk","metodyk"],"pulapka":"Zasady, polityki i metodyki przekładają pożądane zachowania na praktyczne wytyczne codziennego zarządzania; nie myl ich z aktywatorem Kultura, etyka i zachowanie."},"bk_a1_dp_4el":{"kw":["zakres i ważność","obsługa wyjątków","konsekwencje nieprzestrzegania"],"pulapka":"Struktura polityk opisuje 4 elementy: zakres i ważność, konsekwencje nieprzestrzegania, obsługę wyjątków oraz kontrolę zgodności; cel biznesowy nie jest jednym z nich."},"bk_a1_dp_hier":{"kw":["hierarch","struktura ramowa polityk","polityk"],"pulapka":"Dobra praktyka: polityki są częścią hierarchicznej struktury ramowej Ładu i Zarządzania, każda ma swoje miejsce i wyraźnie odnosi się do podstawowych zasad."},"bk_a1_dp_ryzyko":{"kw":["apetyt na ryzyko","restrykcyjn"],"pulapka":"Organizacja niechętna ryzyku ma bardziej restrykcyjne polityki niż skłonna do ryzyka; polityki odzwierciedlają apetyt na ryzyko i trzeba je regularnie aktualizować."},"bk_a1_inter":{"kw":["interesariusze","polityk"],"pulapka":"Interesariusze polityk mają dwojakie interesy: jedni polityki definiują, inni muszą zapewnić zgodność z nimi; są wśród nich też zewnętrzni, np. dostawcy, klienci i regulatorzy."},"bk_a1_kom":{"kw":["zasady, polityki","polityk","komunik"],"pulapka":"Zasady i polityki komunikują wytyczne organu Ładu oraz kierownictwa, a praktyki i działania procesów przekładają je na wykonanie. Procesy także mogą obejmować czynności komunikowania; nie jest to wyłączny kanał jednej kategorii aktywatora."},"bk_a1_rel":{"kw":["polityk","relacj","aktywator"],"pulapka":"Najważniejszym środkiem realizacji polityk są praktyki i działania procesów; struktury definiują i wdrażają polityki, a polityki jako informacja podlegają dobrym praktykom aktywatora Informacja."},"bk_a2_cykl":{"kw":["cykl życia procesu","cykl życia"],"pulapka":"Cykl życia procesu: definiowanie, tworzenie, obsługa, monitorowanie i dostosowanie/aktualizacja lub wycofanie; typowe praktyki ISO/IEC 15504 pomagają go optymalizować."},"bk_a2_def":{"kw":["proces","praktyk i działań","uporządkowan"],"pulapka":"Proces obejmuje praktyki i działania, które przetwarzają wejścia w wyniki wspierające cele związane z IT. Sama nazwa pojedynczej czynności nie opisuje jeszcze przeznaczenia, wejść, praktyk i wyników całego procesu."},"bk_a2_inter":{"kw":["raci","wolontariusz","interesariusze"],"pulapka":"Interesariuszy procesów i ich odpowiedzialność ujmuje diagram RACI; wolontariusze to interesariusze wewnętrzni, a regulatorzy, partnerzy i udziałowcy – zewnętrzni."},"bk_a2_potencjal":{"kw":["poziom zdolności","zdolności procesu","15504"],"pulapka":"Poziom zdolności procesu (podręcznik: potencjał) mierzy zarówno osiąganie celów, jak i stosowanie dobrych praktyk; opiera się na ISO/IEC 15504, nie na modelu dojrzałości COBIT 4.1."},"bk_a2_poziomy":{"kw":["szczegółowe działania","praktyki","działania"],"pulapka":"Szczegółowość rośnie: praktyki → działania → szczegółowe działania; praktyki są najogólniejsze, a szczegółowe działania pochodzą z innych standardów lub produktów COBIT."},"bk_a2_rel":{"kw":["raci","relacj","kultur"],"pulapka":"Kultura i zachowanie decydują o skuteczności procesów; procesy wymagają informacji i ją dostarczają, a struktury i role przypisuje się przez diagram RACI."},"bk_a3_cele":{"kw":["umocowani","zasady operacyjne","decyzj"],"pulapka":"Cele struktury to właściwe umocowanie, dobrze zdefiniowane zasady operacyjne i inne dobre praktyki; wynikiem struktury są działania i decyzje, czyli jej produkty pracy."},"bk_a3_def":{"kw":["struktury organizacyjne","decyzj"],"pulapka":"Struktury organizacyjne to kluczowe jednostki decyzyjne; nie myl ich z aktywatorem Ludzie, umiejętności i kompetencje, który dotyczy osób i ich kompetencji."},"bk_a3_inter":{"kw":["struktury organizacyjne","interesariusz","decyzj"],"pulapka":"Interesariusze struktur to członkowie, inne struktury, organizacje, klienci, dostawcy i regulatorzy; ich role to podejmowanie decyzji, wywieranie wpływu i doradztwo, nie tylko głosowanie."},"bk_a3_mandat":{"kw":["mandat","cykl życia struktury organizacyjnej"],"pulapka":"Mandat (powód i cel istnienia struktury) trzeba zdefiniować w chwili jej utworzenia, na początku cyklu życia; zasady operacyjne to osobna dobra praktyka."},"bk_a3_rel":{"kw":["raci","mandat","zasady operacyjne"],"pulapka":"Mandat i zasady operacyjne struktur określa struktura polityk, skład odzwierciedla umiejętności, kultura decyduje o skuteczności, a RACI łączy struktury z praktykami procesów."},"bk_a3_sklad":{"kw":["skład","zakres kontroli","poziom uprawnień"],"pulapka":"Skład to dobra praktyka struktur: członkowie będący interesariuszami wewnętrznymi lub zewnętrznymi; nie myl go z zakresem kontroli (granice uprawnień) ani poziomem uprawnień."},"bk_a3_wewy":{"kw":["decyzj","struktury organizacyjne"],"pulapka":"Wejściem struktury są zwykle informacje, a wyjściem decyzje, inne informacje lub żądania dodatkowych danych; decyzje to typowy produkt pracy struktur organizacyjnych."},"bk_a4_cykl":{"kw":["kultur","czempion","zachęt"],"pulapka":"Cykl życia kultury zaczyna się od istniejącej kultury: organizacja identyfikuje wymagane zmiany i wdraża je narzędziami z dobrych praktyk, np. komunikowaniem, czempionami, zachętami."},"bk_a4_def":{"kw":["kultura, etyka","zachowani","niedocenian"],"pulapka":"Kultura, etyka i zachowanie to często niedoceniany czynnik sukcesu nadzoru i zarządzania; nie jest aktywatorem-zasobem."},"bk_a4_def2":{"kw":["kultura, etyka","zachowa"],"pulapka":"Kultura, etyka i zachowanie dotyczą indywidualnych oraz zbiorowych wzorców zachowania. Zasady i polityki opisują oraz komunikują oczekiwane wytyczne, lecz ich samo istnienie nie dowodzi określonej kultury."},"bk_a4_inter":{"kw":["interesariusz","kultura, etyka","hr"],"pulapka":"Wśród interesariuszy kultury jedni definiują i egzekwują wzorce zachowań (np. dział prawny, ryzyko, HR, rady wynagrodzeń), inni muszą ich przestrzegać; regulatorzy i audytorzy zewnętrzni są interesariuszami zewnętrznymi."},"bk_a4_rel":{"kw":["kultur","zachowa","polityk"],"pulapka":"Skuteczność procesów i struktur silnie zależy od zachowania ludzi i kultury. Zasady oraz polityki pomagają komunikować wartości i pożądane zachowania, ale potrzebne jest ich rzeczywiste stosowanie."},"bk_a4_zachety":{"kw":["zachęty i nagrody","zachęt","wynagradzan"],"pulapka":"Zachęty i nagrody to dobra praktyka aktywatora Kultura; istnieje wyraźny związek między zachowaniem pracowników a systemem wynagradzania działu HR, co pokazuje Przykład 11."},"bk_a5_def":{"kw":["informacj","produkt"],"pulapka":"Informacja obejmuje wszystkie informacje wytwarzane i używane w przedsiębiorstwie; na poziomie operacyjnym często jest jego kluczowym produktem."},"bk_a5_zakres":{"kw":["nieustrukturyzowan","zautomatyzowan","informacj"],"pulapka":"Aktywator Informacja obejmuje wszystkie istotne informacje, nie tylko zautomatyzowane: ustrukturyzowane lub nie, sformalizowane lub nie; dotyczy głównie fazy informacji, ale ujmuje też dane i wiedzę."},"bk_a6_cele":{"kw":["poziomy usług","ekonomiczn"],"pulapka":"Cele zdolności usługowej to usługi i poziomy usług najbardziej ekonomiczne dla organizacji oraz ich wkład w skutecznie wspierane procesy biznesowe, a nie najwyższe możliwe parametry."},"bk_a6_def":{"kw":["usługi, infrastruktura","infrastruktur","aplikacj"],"pulapka":"Usługi, infrastruktura i aplikacje dają możliwości przetwarzania oraz usługi IT; to aktywator-zasób, a nie wyłącznie „sprzęt”."},"bk_a6_inter":{"kw":["outsourc","dostawc","użytkowni"],"pulapka":"Dostawcami usług mogą być wewnętrzne działy IT, kierownicy operacji i dostawcy z outsourcingu, a użytkownikami wewnętrzni (biznes) i zewnętrzni (partnerzy, klienci, dostawcy)."},"bk_a6_rel":{"kw":["zdolności usługow","kultur"],"pulapka":"Informacja sama jest jedną ze zdolności usługowych, kultura ukierunkowana na usługi wymaga aktywatora Kultura, a zdolności usługowe bywają wejściami lub wyjściami praktyk zarządzania."},"bk_a6_zewn":{"kw":["togaf","itil","model referencyjny"],"pulapka":"Zewnętrzne praktyki zdolności usługowej: TOGAF daje modele referencyjne (techniczny i zintegrowanej infrastruktury), a ITIL wytyczne projektowania i świadczenia usług; nie odwrotnie."},"bk_a7_cele":{"kw":["wykształcenie i kwalifikacje","rotacj","umiejętności behawioralne"],"pulapka":"Cele ludzi to wykształcenie i kwalifikacje, umiejętności techniczne, doświadczenie, wiedza, umiejętności behawioralne oraz dostępność personelu i wskaźnik rotacji; rotacja też jest celem."},"bk_a7_cykl":{"kw":["cykl życia umiejętności","rekrutac","outsourc"],"pulapka":"Cykl życia umiejętności: planowanie, rozwój (szkolenia) lub pozyskanie (rekrutacja), wdrożenie w rolach i pozbycie się, np. po automatyzacji lub outsourcingu; bazę umiejętności ocenia się okresowo."},"bk_a7_def":{"kw":["umiejętnoś","kompetencj","ludzie"],"pulapka":"Ludzie, umiejętności i kompetencje są potrzebne do realizacji działań, właściwych decyzji i działań naprawczych; nie myl ich ze strukturami organizacyjnymi."},"bk_a7_inter":{"kw":["umiejętnoś","interesariusz","rekrutac"],"pulapka":"Każda rola interesariusza (kierownicy, kierownicy projektów, partnerzy, konkurenci, rekruterzy, szkoleniowcy, programiści, specjaliści IT) wymaga osobnego zestawu umiejętności; konkurenci też są na tej liście."},"bk_a7_rel":{"kw":["umiejętności behawioralne","definicje umiejętności","umiejętnoś"],"pulapka":"Procesy i decyzje struktur wymagają umiejętności, umiejętności behawioralne łączą się z kulturą i etyką, a definicje umiejętności to informacje podlegające dobrym praktykom aktywatora Informacja."},"bk_akt_def_ogol":{"kw":["indywidualn","zbiorow","aktywator"],"pulapka":"Aktywatory decydują o działaniu Ładu i Zarządzania indywidualnie i zbiorowo; zaniedbanie jednego może zepsuć całość."},"bk_akt_system":{"kw":["wzajemnie powiązan","systemow","aktywator"],"pulapka":"Przedsiębiorstwo zawsze rozważa wzajemnie powiązany zbiór aktywatorów; takie nastawienie wymaga wsparcia kierownictwa najwyższego szczebla."},"bk_akt_system_decyzje":{"kw":["całościow","wszystkich","aktywator"],"pulapka":"Dobre decyzje wymagają analizy wszystkich wzajemnie powiązanych aktywatorów; skupienie się na jednym, np. tylko na procesach, przeczy podejściu całościowemu."},"bk_akt_wejscie":{"kw":["dane wejściow","wejści","aktywator"],"pulapka":"Aktywator jest w pełni efektywny tylko z wejściami od innych: procesy wymagają informacji, a struktury organizacyjne umiejętności i zachowania."},"bk_akt_wynik":{"kw":["wynik","aktywator"],"pulapka":"Aktywator dostarcza wyniki innym: procesy dają informacje, a umiejętności i zachowanie zwiększają efektywność procesów; kierunek tej zależności bywa odwracany."},"bk_akt_z_kaskady":{"kw":["kaskad","cele związane z it","aktywator"],"pulapka":"Aktywatory opierają się na kaskadzie celów: to cele związane z IT określają, co mają realizować aktywatory, a nie odwrotnie."},"bk_akt_zasoby":{"kw":["zasob","informacj","ludzie"],"pulapka":"Na Rysunku 12 jako zasoby wyróżniono trzy kategorie: Informacja (5); Usługi, infrastruktura i aplikacje (6); Ludzie, umiejętności i kompetencje (7). To klasyfikacja tego rysunku, a nie ogólne twierdzenie, że organizacja nie może traktować innych rzeczy jako zasobów."},"bk_aktyw_brak":{"kw":["tworzenia wartości","aktywator","brak"],"pulapka":"Brak zasobów lub aktywatorów może ograniczyć zdolność tworzenia wartości; to element opisu aktywatorów nadzoru, a nie osobna zasada COBIT 5."},"bk_aktyw_def":{"kw":["aktywator","siedem kategorii","czynnik umożliwiając"],"pulapka":"Aktywator to wszystko, co pomaga osiągnąć cele przedsiębiorstwa, a nie tylko procesy czy narzędzia IT; kategorii jest siedem (Rysunek 12)."},"bk_aktyw_nadzoru":{"kw":["aktywatory ładu","zasoby organizacyjne","czynniki umożliwiające"],"pulapka":"Aktywatory nadzoru to zasoby organizacyjne (metodyki, zasady, struktury, procesy, praktyki) oraz zasoby przedsiębiorstwa (usługi, ludzie, informacja)."},"bk_arch_3":{"kw":["architektura referencyjna","architektura docelowa","architektura przejściowa"],"pulapka":"Architektura referencyjna (bazowa) opisuje stan obecny, docelowa – przyszły, a przejściowa – etapy dochodzenia; „referencyjna” nie znaczy tu wzorcowa ani docelowa."},"bk_arch_repo":{"kw":["repozytorium","model referencyjny"],"pulapka":"Repozytorium architektury przechowuje wyniki prac architektury (pryncypia, normy, modele referencyjne) i definiuje elementy usług: aplikacje, infrastrukturę techniczną i fizyczną."},"bk_arch_widoki":{"kw":["punkty widzenia","katalog","macierz"],"pulapka":"Punkty widzenia architektury to modele, katalogi i macierze opisujące architekturę bazową, docelową lub przejściową dla różnych interesariuszy; to nie pryncypia architektury."},"bk_architektura_zywa":{"kw":["architektur","baza wiedzy","produkt"],"pulapka":"Architektura produktów COBIT 5 to żywy dokument: nowe produkty powstają z bazy wiedzy COBIT 5; nie jest zamkniętym, stałym zestawem publikacji."},"bk_baza_wiedzy":{"kw":["baza wiedzy","filtr"],"pulapka":"Baza wiedzy zawiera obecne wytyczne i strukturę dla przyszłych treści; aktywatory działają jako filtr zawartości bazy wiedzy (Rysunek 10)."},"bk_bsc":{"kw":["bsc","zrównoważon","karta wyników"],"pulapka":"Wymiary BSC to Finanse, Klient, Obszar wewnętrzny oraz Szkolenie i rozwój; „Ryzyko” czy „Zgodność” nie są wymiarami BSC."},"bk_cap":{"kw":["assessment","potencjał","15504"],"pulapka":"Model potencjału procesu COBIT 5 działa w ramach COBIT Assessment Programme i opiera się na ISO/IEC 15504, a nie na modelu dojrzałości COBIT 4.1."},"bk_cel_proc_def":{"kw":["cel procesu","artefakt","zmiana stanu"],"pulapka":"Cel procesu to deklaracja pożądanego rezultatu: artefaktu, istotnej zmiany stanu lub istotnej poprawy zdolności innych procesów; nie jest nim miernik ani praktyka."},"bk_cel_proc_kask":{"kw":["kaskad","cele związane z it","cel procesu"],"pulapka":"Cele procesu wspierają cele związane z IT, a te cele organizacji; kaskada idzie od potrzeb interesariuszy przez cele organizacji i cele IT do celów aktywatorów."},"bk_cel_proc_kat":{"kw":["cele wewnętrzne","cele kontekstowe","jakość wewnętrzna"],"pulapka":"Kategorie celów procesu to cele wewnętrzne (jakość wewnętrzna), kontekstowe oraz dostępności i bezpieczeństwa; „wydajność” nie jest osobną kategorią."},"bk_cele_odgornie":{"kw":["odgórn","mierni","kaskad"],"pulapka":"Skuteczny Ład: cele ustala się odgórnie i dopasowuje do zatwierdzonych celów biznesowych, a mierniki – oddolnie, by każdy poziom kierownictwa mógł monitorować postęp; nie odwrotnie."},"bk_cele_procesu":{"kw":["cele procesu","cel procesu","załącznik c"],"pulapka":"Cele procesu to cele jednego z siedmiu aktywatorów (procesów); mapowanie celów IT na procesy znajduje się w Załączniku C, nie B."},"bk_certyf":{"kw":["isaca","certyfikat"],"pulapka":"Podręcznik COBIT 5 z 2012 r. wymienia cztery certyfikaty ISACA: CGEIT (Ład IT), CISA (audyt), CISM (bezpieczeństwo informacji) i CRISC (ryzyko i kontrola). To historyczny wykaz w tym źródle, nie aktualny katalog wszystkich certyfikacji ISACA."},"bk_cobit5_rozwoj":{"kw":["wyznaczni","ponad 15","rozwoju cobit"],"pulapka":"Wyznaczniki rozwoju COBIT 5 to potrzeby rynku i zmiany otoczenia, poparte ponad 15 latami doświadczeń użytkowników, a nie np. przepis nakazujący stosowanie COBIT."},"bk_cobit_istota":{"kw":["optymaln","równowag","korzyści"],"pulapka":"COBIT 5 równoważy realizację korzyści z optymalizacją ryzyka i zasobów. Sama maksymalizacja korzyści lub minimalizacja kosztów nie opisuje całej tej równowagi; redukcja kosztów może jednak być uzasadnionym celem konkretnej inicjatywy."},"bk_cobit_metodyka":{"kw":["struktura ramowa","zasady, polityki"],"pulapka":"COBIT 5 jest przykładem struktury ramowej, czyli należy do aktywatora Zasady, polityki i struktury ramowe; nie do Informacji ani Procesów."},"bk_cobit_nienorm":{"kw":["normatywn","nie jest normatywny"],"pulapka":"COBIT 5 nie narzuca identycznego układu procesów każdej firmie. Organizacja definiuje własny zbiór procesów obejmujący wszystkie potrzebne jej cele Ładu i Zarządzania; nie musi mechanicznie tworzyć 37 osobnych jednostek organizacyjnych."},"bk_cobit_ogolny":{"kw":["not-for-profit","wielkości","sektor"],"pulapka":"COBIT 5 jest ogólny: dla firm każdej wielkości, komercyjnych, not-for-profit i publicznych; odpowiedzi „tylko dla dużych korporacji” lub „tylko dla firm IT” są błędne."},"bk_cykl_info":{"kw":["przechowywanie","udostępnianie","pozbywania się"],"pulapka":"Faza użytkowania/obsługi informacji dzieli się na przechowywanie, udostępnianie i wykorzystanie; archiwizacja i niszczenie należą do fazy aktualizacji/pozbywania się."},"bk_cz_3komp":{"kw":["cykl życia","ciągłe doskonaleni","zarządzanie programem"],"pulapka":"Trzy komponenty cyklu życia to ciągłe doskonalenie (nie projekt jednorazowy), umożliwienie zmian (zachowanie, kultura) i zarządzanie programem."},"bk_daz1":{"kw":["jakość informacji","decyzj"],"pulapka":"Chodzi o jakość informacji wspierającej decyzje biznesowe, a nie o jakość samego sprzętu czy oprogramowania."},"bk_daz2":{"kw":["wartość","inwestycj","korzyści biznesow"],"pulapka":"Wartość z inwestycji IT to osiąganie celów strategicznych i korzyści biznesowych, a nie samo wdrożenie technologii czy zakończenie projektu."},"bk_daz3":{"kw":["sprawnoś","operacyjn"],"pulapka":"Sprawność operacyjna wynika z niezawodnego i efektywnego użycia technologii; nie myl jej z optymalizacją kosztów, która jest osobnym dążeniem."},"bk_daz4":{"kw":["ryzyk","akceptowaln","apetyt na ryzyko"],"pulapka":"Celem jest utrzymanie ryzyka na akceptowalnym poziomie, a nie jego całkowite wyeliminowanie; COBIT mówi o optymalizacji ryzyka, nie o ryzyku zerowym."},"bk_daz5":{"kw":["koszt","optymalizacj"],"pulapka":"Optymalizacja kosztu to nie minimalizacja; chodzi o koszt właściwy do uzyskiwanej wartości, nie o najtańsze usługi IT."},"bk_daz6":{"kw":["zgodnoś","przepis","regulacj"],"pulapka":"Zgodność obejmuje wymogi zewnętrzne (przepisy, regulacje, umowy) i wewnętrzne polityki; nie zawężaj jej tylko do prawa."},"bk_dazenia":{"kw":["dąż","jakość informacji","streszczeni"],"pulapka":"Dążeń jest sześć i dotyczą przedsiębiorstw oraz zarządów; nie myl ich z pięcioma zasadami COBIT 5 ani z trzema celami Ładu (korzyści, ryzyko, zasoby)."},"bk_dom_2":{"kw":["edm","apo","dss","domen"],"pulapka":"Ład ma jedną domenę EDM z 5 procesami, a Zarządzanie cztery domeny (APO, BAI, DSS, MEA); razem jest 37 procesów."},"bk_dom_wlasciwa":{"kw":["domen","przypis","proces"],"pulapka":"Choć proces może mieć działania planowania, budowy, uruchamiania i monitorowania, przypisuje się go do jednej domeny, najwłaściwszej dla jego głównego obszaru."},"bk_dost_bezp_def":{"kw":["dostęp","bezpieczeństw","uprawnion"],"pulapka":"Dostęp i bezpieczeństwo ma dwie strony: aktywator dostępny w razie potrzeby i wyniki dostępne tylko dla uprawnionych; to kategoria celów, nie osobny wymiar."},"bk_dzialania_def":{"kw":["działani","konieczn","normatywn"],"pulapka":"Działania to kroki konieczne i wystarczające do realizacji praktyki (GP/MP); nie są normatywne i trzeba je dostosować, tworząc konkretne procedury organizacji."},"bk_dzialania_odb":{"kw":["audytor","działani"],"pulapka":"Opis działań przydaje się kierownictwu, dostawcom usług, użytkownikom końcowym, specjalistom IT i audytorom; nie jest przeznaczony wyłącznie dla działu IT."},"bk_edm_rola":{"kw":["edm","interakcj","kierowani"],"pulapka":"Rola Ładu to ocena, kierowanie i monitorowanie (EDM); wymaga zbioru interakcji z Zarządzaniem, a nie całkowitej izolacji obu dziedzin."},"bk_etyka_ind":{"kw":["etyka indywidualna","etyki indywidualnej"],"pulapka":"Etyka indywidualna zależy w dużym stopniu od czynników zewnętrznych: religii, pochodzenia, statusu społeczno-ekonomicznego, geografii i doświadczeń; nie wyznacza jej polityka organizacji."},"bk_etyka_org":{"kw":["etyka organizacyjna","etyki organizac"],"pulapka":"Etyka organizacyjna wynika z wartości, na których ma opierać się organizacja, a etyka indywidualna z osobistych wartości pracownika; pytania o definicje lubią je zamieniać."},"bk_f2_6mies":{"kw":["sześć miesięcy","6 miesięcy","iteracj"],"pulapka":"Inicjatywa trwająca ponad sześć miesięcy grozi utratą dynamiki, koncentracji i akceptacji; duże inicjatywy dzieli się na wiele iteracji cyklu życia."},"bk_f2_ryzyko":{"kw":["faza 2","scenariusz","zakres"],"pulapka":"Zakres w fazie 2 ustala się mapowaniem celów przedsiębiorstwa na cele IT i procesy, wspartym scenariuszami ryzyka i ogólną diagnostyką; potem ocenia się stan obecny."},"bk_f3_prior":{"kw":["faza 3","luk","szybkie korzyści"],"pulapka":"W fazie 3 określa się cel doskonalenia oraz luki i możliwe rozwiązania; priorytet mają inicjatywy prostsze i najbardziej korzystne, a nie najambitniejsze."},"bk_f4_uzas":{"kw":["faza 4","uzasadnieni","plan"],"pulapka":"W fazie 4 planuje się praktyczne rozwiązania: projekty wsparte uzasadnieniami biznesowymi i plan zmian; wdrażanie w praktyce to dopiero faza 5."},"bk_f5_miary":{"kw":["faza 5","mierni","monitorowani"],"pulapka":"W fazie 5 rozwiązania wdraża się w praktyce, a miary i monitorowanie oparte są na celach i miernikach COBIT; potrzebne są zaangażowanie kierownictwa i własność biznesu oraz IT."},"bk_f6_zrown":{"kw":["faza 6","korzyści","zrównoważon"],"pulapka":"Faza 6 skupia się na trwałym użyciu nowych lub udoskonalonych aktywatorów i monitorowaniu korzyści. Faza 7 obejmuje przegląd ogólnego sukcesu i dalszych wymagań; ocena i monitorowanie nie są zakazane we wcześniejszych fazach."},"bk_f7_iter":{"kw":["faza 7","iteracyj","ciągłego doskonalenia"],"pulapka":"W fazie 7 ocenia się ogólny sukces, wskazuje dalsze wymagania i wzmacnia ciągłe doskonalenie. Inicjatywa lub program mogą zostać zamknięte; podejście do Ładu i Zarządzania jest rozwijane iteracyjnie."},"bk_f_wniosek":{"kw":["kryteri","cobit 4.1","integralność"],"pulapka":"Wszystkie 7 kryteriów informacji COBIT 4.1 ma odpowiedniki w celach jakości informacji COBIT 5, a model informacji pozwala zdefiniować dodatkowe; żadnego kryterium nie usunięto."},"bk_f_zgodnosc":{"kw":["zgodnoś","specyfikac","kryteri"],"pulapka":"Zgodność z regulacjami to raczej cel związany ze sposobem wykorzystania informacji niż jej cecha wewnętrzna; zgodność ze specyfikacją ujęto w każdym celu jakości informacji."},"bk_g_uklad":{"kw":["cztery wymiary","wymiar","zarządzanie wydajnością aktywatora"],"pulapka":"Każdy aktywator w Załączniku G ma rysunek, 4 wymiary (interesariusze, cele, cykl życia, dobre praktyki), relacje z innymi i przykłady; zarządzanie wydajnością aktywatora to nie piąty wymiar."},"bk_h_akt_nadzoru":{"kw":["aktywatory ładu","aktywator"],"pulapka":"Aktywator Ładu to coś materialnego lub niematerialnego, co wspiera skuteczny Ład; aktywatorem jest więc też kultura, nie tylko narzędzia i dokumenty."},"bk_h_arch_ref":{"kw":["architektura referencyjna","architektura docelowa"],"pulapka":"Architektura referencyjna (bazowa) to istniejący opis przed cyklem przeprojektowania, czyli stan obecny; przyszły stan opisuje architektura docelowa."},"bk_h_atr_proc":{"kw":["atrybut","pa 1.1"],"pulapka":"Atrybut procesu to mierzalna cecha zdolności odnosząca się do każdego procesu; jest ich 9 (PA 1.1–5.2) i każdy ocenia się skalą N, C, W, P."},"bk_h_cel":{"kw":["cele i mierniki","deklaracja","miernik"],"pulapka":"Cel to deklaracja pożądanego wyniku, a miernik – jednostka pomiaru jego osiągnięcia; nie myl celu z miernikiem ani z praktyką."},"bk_h_cel_bizn":{"kw":["cele organizacji","bsc"],"pulapka":"Cel biznesowy (cel organizacji) przekłada misję z deklaracji zamiaru na cele działania i wyniki; 17 typowych celów organizacji ułożono według wymiarów BSC, a nie IT BSC."},"bk_h_cel_it":{"kw":["cele związane z it","it bsc","cel it"],"pulapka":"Cel związany z IT to deklaracja pożądanego wyniku IT wspierającego cele organizacji; 17 celów IT ułożono według IT BSC i to one wspierają cele organizacji, nie odwrotnie."},"bk_h_cel_procesu":{"kw":["cel procesu","cele procesu"],"pulapka":"Cel procesu to deklaracja pożądanego wyniku procesu: artefaktu, istotnej zmiany stanu lub poprawy zdolności innych procesów; nie myl go z miernikiem ani z opisem procesu."},"bk_h_ciaglosc":{"kw":["ciągłoś","dss04"],"pulapka":"Ciągłość działalności to zapobieganie zakłóceniom, łagodzenie skutków i odtwarzanie; plany odtworzenia po katastrofie skupiają się na odtwarzaniu, więc trzeba uwzględnić też odporność."},"bk_h_cobit41":{"kw":["cobit 4.1","cele kontrolne","model dojrzałości"],"pulapka":"COBIT 4.1 opisywał procesy IT, cele kontrolne, wytyczne zarządzania i modele dojrzałości; aktywatory i oddzielenie Ładu od Zarządzania wprowadził COBIT 5."},"bk_h_cobit5":{"kw":["control objectives","akronim","siedem kategorii"],"pulapka":"COBIT 5 używa już tylko akronimu; pełna nazwa Control Objectives for Information and related Technology dotyczy wcześniejszych wersji. COBIT 5 opisuje 5 zasad i 7 aktywatorów."},"bk_h_cykl_ekon":{"kw":["cyklu życia ekonomiczn","uzasadnienie biznesowe"],"pulapka":"Pełny cykl życia ekonomicznego to okres istotnych korzyści i wydatków programu inwestycyjnego, łącznie z eksploatacją i wycofaniem, a nie tylko faza budowy."},"bk_h_dobra_prakt":{"kw":["dobra praktyka","dobre praktyki"],"pulapka":"Dobra praktyka to sprawdzone działanie lub proces, z powodzeniem stosowane w wielu organizacjach i dające wiarygodne wyniki; to także jeden z czterech wymiarów aktywatora."},"bk_h_dopasowanie":{"kw":["dopasowan","strategi"],"pulapka":"Dopasowanie to stan, w którym aktywatory Ładu i Zarządzania IT wspierają cele i strategię organizacji; to nie to samo co zgodność z przepisami."},"bk_h_dzialanie":{"kw":["działanie","konieczn"],"pulapka":"Działanie to podstawowa czynność procesu. Dopiero zbiór działań opisuje konieczne i wystarczające kroki realizacji praktyki; pojedynczy krok nie musi sam wystarczać. Ogólne działania dostosowuje się do procedur organizacji."},"bk_h_geit":{"kw":["ład it","ład nad informatyką"],"pulapka":"Ład IT w przedsiębiorstwie (GEIT) daje pewność, że informacja i technologia wspierają strategię i cele organizacji; nie dotyczy tylko działu IT ani samej technologii."},"bk_h_informacje":{"kw":["informacj","zasób"],"pulapka":"Informacje to zasób niezbędny jak inne ważne aktywa i mogą mieć wiele postaci: papierową, elektroniczną, film, rozmowę; nie są to tylko dane w systemach IT."},"bk_h_interesariusz":{"kw":["interesariusz","potrzeby interesariuszy"],"pulapka":"Interesariuszem jest każdy, kto ma odpowiedzialność, oczekiwania lub udział w organizacji: udziałowcy, użytkownicy, rząd, dostawcy, klienci, opinia publiczna; nie tylko właściciele."},"bk_h_jakosc":{"kw":["jakoś","jakość wewnętrzna"],"pulapka":"Jakość to przydatność do celu (uzyskanie zamierzonej wartości), a nie najwyższe parametry; cele aktywatorów dzielą się m.in. na jakość wewnętrzną i kontekstową."},"bk_h_kodeks":{"kw":["kodeks etyki","etyk"],"pulapka":"Kodeks etyki definiuje wartości organizacyjne i reguły, pomagając odróżnić właściwe postępowanie od niewłaściwego; karta etyki to w słowniczku przykład aktywatora Zasada."},"bk_h_kompetencja":{"kw":["kompetencj","umiejętnoś"],"pulapka":"Kompetencja to zdolność skutecznego wykonania zadania, czynności lub funkcji, a umiejętność – wyuczona zdolność osiągania określonych rezultatów; egzamin lubi je zamieniać."},"bk_h_kontekst":{"kw":["kontekst","jakość kontekstowa"],"pulapka":"Kontekst obejmuje 5 rodzajów: technologiczny, danych, umiejętności i wiedzy, organizacyjny i kulturowy oraz strategiczny; na tej liście nie ma np. kontekstu prawnego ani finansowego."},"bk_h_kontrola":{"kw":["mechanizmy kontrolne","kontrol"],"pulapka":"Kontrola (mechanizm kontrolny) to metody zarządzania ryzykiem: polityki, procedury, wytyczne, praktyki lub struktury, także administracyjne i prawne; nie tylko zabezpieczenia techniczne."},"bk_h_kultura":{"kw":["kultur","kultura, etyka"],"pulapka":"Kultura to wzorzec zachowań, poglądów, założeń, postaw i sposobów działania; w COBIT 5 należy do aktywatora Kultura, etyka i zachowanie, a nie do Zasad i polityk."},"bk_h_lad_korp":{"kw":["ładu korporacyjnego","ład korporacyjny"],"pulapka":"Ład korporacyjny to obowiązki i praktyki zarządu i kadry: kierunek strategiczny, osiąganie celów, ryzyko i odpowiedzialne użycie zasobów; Ład IT jest jego częścią, nie odwrotnie."},"bk_h_mech_proc_bizn":{"kw":["mechanizmy kontrolne","kontroli wewnętrznej"],"pulapka":"Mechanizmy kontrolne procesów biznesowych racjonalnie zapewniają realizację celów danego procesu biznesowego; system kontroli wewnętrznej dotyczy celów całej organizacji."},"bk_h_metodyka_nadz":{"kw":["struktura ramowa","coso"],"pulapka":"Struktura ramowa Ładu (podręcznik: metodyka nadzoru) to struktura koncepcyjna: pojęcia, założenia, praktyki, role, relacje i granice; przykłady to COBIT i COSO, nie ISO/IEC 15504."},"bk_h_miernik":{"kw":["miernik","smart"],"pulapka":"Pełne wytyczne miernika określają jednostkę, częstotliwość pomiaru, wartość docelową, procedurę pomiaru i interpretacji wyniku; miernik mierzy cel, sam nim nie jest."},"bk_h_opt_ryz":{"kw":["optymalizacja ryzyka","optymalizacji ryzyka","apetyt"],"pulapka":"Optymalizacja ryzyka to nie jego eliminacja: obejmuje rozpoznanie, ocenę wpływu i prawdopodobieństwa oraz unikanie, ograniczanie lub transfer ryzyka w granicach apetytu na ryzyko."},"bk_h_opt_zas":{"kw":["optymalizacja zasobów","optymalizacji zasobów"],"pulapka":"Optymalizacja zasobów dotyczy wszystkich zasobów: ludzi, finansów, sprzętu i infrastruktury, a nie tylko kosztów IT; to jeden z trzech celów Ładu."},"bk_h_pmo":{"kw":["pmo","vmo"],"pulapka":"PMO wspiera kierowników programów i projektów oraz zbiera, ocenia i raportuje informacje o ich realizacji; sekretariatem portfela inwestycji i usług jest VMO."},"bk_h_polityka":{"kw":["polityka","polityk"],"pulapka":"Polityka to ogólne zamierzenia i wytyczne formalnie wyrażone przez kierownictwo; zasada wyraża wartości i podstawowe założenia, np. karta etyki."},"bk_h_portfel":{"kw":["portfel","apo05"],"pulapka":"Portfel inwestycyjny to zbiór inwestycji rozważanych i/lub realizowanych; obejmuje więc też te dopiero planowane, nie tylko trwające."},"bk_h_potencjal":{"kw":["zdolność procesu","zdolności procesu","15504"],"pulapka":"Zdolność procesu (podręcznik: potencjał) to według ISO/IEC 15504 zdolność do osiągania bieżących lub planowanych celów biznesowych; nie myl jej z dojrzałością z COBIT 4.1."},"bk_h_praktyka_gm":{"kw":["praktyki ładu","praktyki zarządzania","praktyka ładu"],"pulapka":"Praktyka Ładu/Zarządzania to ogólne wymogi wobec procesu, deklaracje działań organów Ładu i Zarządzania; kroki „jak to zrobić” opisują dopiero działania."},"bk_h_proces":{"kw":["właściciel procesu","proces"],"pulapka":"W słowniczku proces ma też jasne przesłanki biznesowe, rozliczanych właścicieli, jasne role i środki pomiaru wydajności; to coś więcej niż lista czynności."},"bk_h_raci_a":{"kw":["odpowiedzialny decyzyjnie","rozliczan","raci"],"pulapka":"A (Accountable) to na egzaminie PL „odpowiedzialny decyzyjnie” (podręcznik: strona rozliczana), a R to „odpowiedzialny wykonawczo”; obie nazwy mają słowo „odpowiedzialny”."},"bk_h_raci_c":{"kw":["konsultant","dwukierunkow","raci"],"pulapka":"C (Konsultant) dostarcza dane wejściowe w komunikacji dwukierunkowej; I (Informowany) tylko otrzymuje informacje, jednokierunkowo."},"bk_h_raci_i":{"kw":["informowan","jednokierunkow","raci"],"pulapka":"I (Informowany) otrzymuje informacje o postępach i wynikach w komunikacji jednokierunkowej; rola A zawsze powinna dostawać odpowiednie informacje, by nadzorować zadanie."},"bk_h_raci_r":{"kw":["odpowiedzialny wykonawczo","raci"],"pulapka":"R (Responsible, odpowiedzialny wykonawczo) to rola najbardziej zaangażowana operacyjnie; odpowiada na pytanie „kto realizuje zadanie?”, a nie „kto odpowiada za powodzenie?” (to A)."},"bk_h_rada_arch":{"kw":["rada ds. architektury","architektur"],"pulapka":"Rada ds. Architektury daje wytyczne i decyzje w sprawie architektury korporacyjnej oraz opracowuje jej polityki i standardy; to grupa, a nie pojedyncza rola dyrektora ds. architektury."},"bk_h_realiz_korz":{"kw":["realizacja korzyści","realizacji korzyści"],"pulapka":"Realizacja korzyści obejmuje nowe korzyści, utrzymanie i rozszerzenie istniejących oraz eliminację inicjatyw i zasobów bez wystarczającej wartości; nie dotyczy wyłącznie nowych korzyści."},"bk_h_rozl_nadzor":{"kw":["zarząd","rozliczaln","ład"],"pulapka":"W większości organizacji rozliczalność za Ład spoczywa na organie nadzorującym (board), pod kierownictwem jego przewodniczącego. Podręcznik PL używa słów „zarząd” i „prezes”; dobór rzeczywistego organu zależy od struktury organizacji. Delegowanie zadań nie usuwa tej rozliczalności."},"bk_h_ryzyko":{"kw":["ryzyk","prawdopodobieństw"],"pulapka":"Ryzyko to połączenie prawdopodobieństwa zdarzenia i jego konsekwencji, a nie samo prawdopodobieństwo ani samo zagrożenie."},"bk_h_skw":{"kw":["kontroli wewnętrznej","mea02"],"pulapka":"System kontroli wewnętrznej służy realizacji celów oraz zapobieganiu niepożądanym zdarzeniom albo ich wykrywaniu i korygowaniu; jego monitorowanie to proces MEA02."},"bk_h_struktura_org":{"kw":["struktury organizacyjne","komitet sterujący"],"pulapka":"Struktura organizacyjna jako aktywator obejmuje organizację, jej struktury, hierarchie i zależności, np. komitet sterujący; to nie to samo co diagram RACI."},"bk_h_tabela_raci":{"kw":["diagram raci","raci"],"pulapka":"Diagram RACI (podręcznik: tabela RACI) przypisuje role R, A, C, I do praktyk procesów i łączy aktywator Procesy ze Strukturami organizacyjnymi."},"bk_h_tworz_wart":{"kw":["tworzenie wartości","tworzenia wartości"],"pulapka":"Tworzenie wartości to główny cel Ładu, osiągany przez równowagę realizacji korzyści, optymalizacji ryzyka i optymalizacji zasobów; to nie maksymalizacja samych korzyści."},"bk_h_umiejetnosc":{"kw":["umiejętność","kompetencj"],"pulapka":"Umiejętność to wyuczona zdolność osiągania wcześniej określonych rezultatów; kompetencja oznacza zdolność skutecznego wykonania zadania, czynności lub funkcji. Pojęcia są powiązane, ale nie są identycznymi definicjami."},"bk_h_uslugi_it":{"kw":["usługi it","service desk"],"pulapka":"Usługi IT to codzienne dostarczanie infrastruktury i aplikacji oraz wsparcie przy korzystaniu z nich, np. Service Desk; zasoby, którymi się je świadczy, to zdolności usługowe."},"bk_h_we_wy":{"kw":["wejścia i wyjścia","produkty pracy"],"pulapka":"Wejścia i wyjścia to produkty pracy procesu, definiowane na poziomie praktyk; lista przykładów COBIT 5 nie jest wyczerpująca, a wyjście jednego procesu bywa wejściem innego."},"bk_h_wlasciciel":{"kw":["właściciel procesu","właściciel"],"pulapka":"Właściciel to osoba lub grupa z prawami i obowiązkami wobec zasobu, np. właściciel procesu lub systemu; właściciel procesu biznesowego odpowiada za sprawność procesu i zatwierdza zmiany."},"bk_h_wyznacznik":{"kw":["wyznaczni","kaskad"],"pulapka":"Wyznacznik (driver) to czynnik zewnętrzny lub wewnętrzny, który inicjuje działanie lub zmianę i na nie wpływa; wyznaczniki interesariuszy to pierwszy krok kaskady celów."},"bk_h_zasada":{"kw":["zasad","zasady, polityki"],"pulapka":"Zasada obejmuje wartości, założenia i poglądy kształtujące decyzje oraz dozór, czyli troskę o cudze zasoby; przykłady to karta etyki i karta odpowiedzialności społecznej, nie regulamin haseł."},"bk_h_zasob":{"kw":["zasob","optymalizacja zasobów"],"pulapka":"Zasób to każdy zasób organizacji pomagający jej osiągnąć cele; optymalizacja zasobów dotyczy ludzi, finansów, sprzętu i infrastruktury, nie tylko IT."},"bk_i38_1":{"kw":["raci","edm05","komitet ds. strategii"],"pulapka":"W porównaniu z ISO/IEC 38500:2008 zasadę Odpowiedzialność wspierają m.in. Procesy, Struktury organizacyjne, RACI oraz EDM05. Opisany komitet strategiczny IT działa w imieniu organu nadzorującego i pod przewodnictwem jego członka; nie jest obowiązkowym organem w każdej organizacji."},"bk_i38_2":{"kw":["edm02","apo","kaskad"],"pulapka":"Porównanie w Załączniku E podaje dla zasady Strategia EDM02, domenę APO i kaskadę celów. BAI omówiono szczególnie przy zasadzie Nabycie; nie wynika z tego, że działania BAI nie mogą wspierać realizacji strategii."},"bk_i38_3":{"kw":["apo05","bai","nabywani"],"pulapka":"Według zasady Nabycie projekty IT są częścią szerszej zmiany biznesowej, a nie czysto technicznym przedsięwzięciem; wspierają ją EDM, APO05, APO, BAI oraz MEA i EDM05."},"bk_i38_4":{"kw":["apo09","mea01","apo02"],"pulapka":"Przy zasadzie Sprawność Załącznik E wymienia m.in. APO02, APO09, MEA01 i ocenę zdolności procesu. MEA02 i MEA03 omówiono przy Zgodności. To przykładowe powiązania, a nie rozłączne zbiory wszystkich oddziaływań procesów."},"bk_i38_5":{"kw":["mea03","mea02","zgodnoś"],"pulapka":"Zgodność trzeba wbudować w planowanie strategiczne, bo zapewnianie jej po szkodzie jest kosztowne; wspierają ją APO02, MEA02, MEA03 oraz przewodnik COBIT 5 – Audyt."},"bk_i38_6":{"kw":["apo07","bai05","bai08"],"pulapka":"Przy zasadzie Zachowanie pracowników Załącznik E wymienia aktywatory Ludzie, umiejętności i kompetencje oraz Kultura, etyka i zachowanie, a także APO07, BAI02, BAI05 i BAI08. Lista nie oznacza, że zachowania ludzi nie mają znaczenia w procesach DSS."},"bk_i38_edm":{"kw":["oszacuj, kieruj i monitoruj","edm","38500"],"pulapka":"Ocena, kierowanie i monitorowanie z ISO/IEC 38500 odpowiada domenie EDM (Oszacuj, Kieruj i Monitoruj) z 5 procesami Ładu; nie APO, która należy do Zarządzania."},"bk_il15_feedback":{"kw":["informacje zwrotne","zwrotn","informacj"],"pulapka":"Na Rysunku 15 informacje zwrotne dotyczące zarządzania płyną od obszaru Zarządzania do Oceny (Evaluate) w obszarze Ładu. Nie pomyl tej konkretnej strzałki z funkcją Monitorowania (Monitor) Ładu."},"bk_il15_kier":{"kw":["kierowani","direct","rysunek 15"],"pulapka":"Kierowanie to strzałka od Ładu do Zarządzania; Zarządzanie nie kieruje Ładem, tylko przekazuje mu informacje zwrotne."},"bk_il15_mon":{"kw":["monitorowani","mea","edm"],"pulapka":"Monitorowanie występuje w Ładzie (EDM) i w Zarządzaniu (MEA); w Ładzie oznacza sprawdzanie, czy wyznaczony kierunek wcielono w życie."},"bk_il15_ocena":{"kw":["ocena","evaluate","edm"],"pulapka":"Evaluate jest funkcją Ładu w EDM. Assessment i evaluation występują też w obszarze Zarządzania, m.in. MEA; samo polskie słowo „ocena” bez kontekstu nie rozstrzyga, czy chodzi o Ład czy Zarządzanie."},"bk_il15_potrzeby":{"kw":["potrzeby biznesow","rysunek 15","ocena"],"pulapka":"Na Rysunku 15 potrzeby biznesowe są wejściem do Ładu i zasilają Ocenę; nie są elementem żadnej domeny Zarządzania."},"bk_il33_uwagi":{"kw":["rysunek 33","ilustracyjn","role"],"pulapka":"Role i struktury z Rysunku 33 są ilustracyjne: nie muszą odpowiadać faktycznym funkcjom w organizacji i nie tworzą uniwersalnej struktury dla każdego przedsiębiorstwa."},"bk_info_atr_warstwy":{"kw":["warstwa semantyczna","warstwa pragmatyczna","warstwa empiryczna"],"pulapka":"Łatwo pomylić warstwy: aktualność i poziom szczegółowości to atrybuty semantyczne, okres przechowywania i status – pragmatyczne, kanał dostępu – empiryczny, a nośnik – fizyczny."},"bk_info_tgf":{"kw":["rysunek 9","delegowanie","rozliczalność"],"pulapka":"Interakcje ról z Rysunku 9 wymagają przepływu informacji: rozliczalność, delegowanie, wyznaczanie kierunku, monitorowanie, instruowanie i dopasowanie, raportowanie; to wykorzystanie informacji jako aktywatora Ładu."},"bk_info_wartosc":{"kw":["wartoś","uzasadnienie biznesowe","informacj"],"pulapka":"Informacja nie ma wartości sama w sobie, tylko przez wykorzystanie (wewnętrzne lub sprzedaż); uzasadnienie biznesowe uwzględnia też korzyści niewymierne, np. zadowolenie klienta."},"bk_info_zasob":{"kw":["informacj","zasób","kluczowy zasób"],"pulapka":"Kluczowym zasobem w streszczeniu jest informacja, a nie technologia; technologia tylko towarzyszy informacji przez cały jej cykl, od utworzenia do zniszczenia."},"bk_info_zasob_przyk":{"kw":["raport","analiz","informacj"],"pulapka":"Raporty dla zarządu i informacje z analizy biznesowej to przykłady informacji, które same są ważnymi aktywatorami nadzoru i zarządzania."},"bk_inne_obszary":{"kw":["marketing","finans","cele przedsiębiorstwa"],"pulapka":"Na cele przedsiębiorstwa wpływają też np. finanse i marketing, ale COBIT 5 uwzględnia tylko działania i cele związane z IT."},"bk_integr_41":{"kw":["integralność","kompletność","dokładność"],"pulapka":"Integralność z COBIT 4.1 odpowiada w COBIT 5 kompletności i dokładności; wiarygodność z 4.1 to wiarygodność, reputacja i obiektywność."},"bk_inter_cykl":{"kw":["interesariusz","cykl życia informacji","faz"],"pulapka":"Wymiar interesariuszy informacji nie jest niezależny: w różnych fazach cyklu życia występują różni interesariusze, więc role definiuje się, odwołując się do faz cyklu życia."},"bk_iso15504":{"kw":["15504","iso"],"pulapka":"PCM oparto na normie ISO/IEC 15504 (ocena procesów), a nie na ISO/IEC 38500 czy ISO/IEC 27001."},"bk_iso38500":{"kw":["38500","oszacuj, kieruj i monitoruj","edm"],"pulapka":"ISO/IEC 38500 ma 6 zasad (Odpowiedzialność, Strategia, Nabycie, Sprawność, Zgodność, Zachowanie ludzi), a COBIT 5 ma 5 zasad; nie myl tych list."},"bk_it_bsc":{"kw":["it bsc","bsc","wymiar"],"pulapka":"IT BSC ma te same cztery wymiary co BSC (Finanse, Klient, Obszar wewnętrzny, Szkolenie i rozwój), ale porządkuje cele związane z IT."},"bk_jak_kont_def":{"kw":["jakość kontekstow","kontekstow","istotn"],"pulapka":"Jakość kontekstowa to dopasowanie wyników do celu w kontekście (istotne, kompletne, aktualne, spójne, zrozumiałe); dokładność i obiektywność to jakość rzeczywista."},"bk_jak_rzecz_def":{"kw":["jakość rzeczywist","dokładn","obiektywn"],"pulapka":"Jakość rzeczywista to dokładność, obiektywność i uznane wyniki; istotność, kompletność czy aktualność należą do jakości kontekstowej."},"bk_jb_info":{"kw":["ograniczony dostęp","dostęp i bezpieczeństwo","dostępność"],"pulapka":"Jakość dostępu i bezpieczeństwa to dostępność/terminowość i ograniczony dostęp; poufność z COBIT 4.1 odpowiada ograniczonemu dostępowi, a nie dokładności."},"bk_jk_info":{"kw":["jakość kontekstowa","istotność","kompletność"],"pulapka":"Jakość kontekstowa i reprezentacji obejmuje m.in. istotność, kompletność, aktualność, odpowiednią ilość, zwięzłe i spójne przedstawienie; wiarygodność należy do jakości wewnętrznej."},"bk_jr_info":{"kw":["jakość wewnętrzna","obiektywność","reputacja"],"pulapka":"Jakość wewnętrzna informacji (podręcznik: rzeczywista) to dokładność, obiektywność, wiarygodność i reputacja; aktualność i kompletność należą do jakości kontekstowej."},"bk_kask_k1":{"kw":["wymiern","kaskad","poziom"],"pulapka":"Kaskada definiuje istotne i wymierne cele i zadania na różnych poziomach odpowiedzialności, a nie jeden cel dla całej firmy."},"bk_kask_k2":{"kw":["baza wiedzy","filtr","kaskad"],"pulapka":"Kaskada filtruje bazę wiedzy COBIT 5 według celów przedsiębiorstwa, by wybrać wytyczne do wdrożenia, doskonalenia i audytu; nie tworzy nowych wytycznych."},"bk_kask_k3":{"kw":["kaskad","aktywator","komunik"],"pulapka":"Kaskada identyfikuje i komunikuje, jak aktywatory pomagają osiągnąć cele przedsiębiorstwa; to trzecia z trzech wymienionych korzyści."},"bk_kask_korz":{"kw":["kaskad","priorytet"],"pulapka":"Kaskada pozwala ustalić priorytety wdrożenia, doskonalenia i audytu na podstawie celów przedsiębiorstwa i związanego z nimi ryzyka; nie wyznacza poziomów potencjału procesów."},"bk_kask_o1":{"kw":["priorytet","kaskad","zmienia"],"pulapka":"Każde przedsiębiorstwo inaczej ustala priorytety celów i mogą się one zmieniać w czasie; to pierwszy powód, by nie stosować kaskady mechanicznie."},"bk_kask_o2":{"kw":["branż","wielkoś","mapowani"],"pulapka":"Tabele mapowania nie uwzględniają wielkości przedsiębiorstwa ani branży; są „wspólnym mianownikiem”, a nie wynikiem dopasowanym do firmy."},"bk_kask_o3":{"kw":["continuum","kontinuum","dwa poziomy"],"pulapka":"Mapowanie ma tylko dwa poziomy istotności (P i S), choć w rzeczywistości powiązania tworzą kontinuum; to ograniczenie, a nie zaleta tabel."},"bk_kask_ostr":{"kw":["mechaniczn","uniwersaln","wytyczn"],"pulapka":"Kaskada nie zawiera uniwersalnej prawdy i nie należy stosować jej mechanicznie; pułapką są odpowiedzi „obowiązkowa”, „normatywna”, „stosować dokładnie”."},"bk_kask_p1":{"kw":["wagi","istotnoś","priorytet"],"pulapka":"Nadanie wag to przełożenie priorytetów strategicznych na istotność każdego celu przedsiębiorstwa, a nie celów IT czy procesów."},"bk_kask_p2":{"kw":["weryfik","mapowani","branż"],"pulapka":"Weryfikacja mapowania uwzględnia specyfikę środowiska i branży; to drugi podany przykład dostosowania kaskady, obok nadania wag."},"bk_kask_prakt":{"kw":["dostosow","kaskad","mapowani"],"pulapka":"Pierwszą czynnością przy korzystaniu z kaskady jest zawsze dostosowanie mapowania do własnej sytuacji, a nie przyjęcie tabel COBIT bez zmian."},"bk_kask_zrodlo":{"kw":["kaskad","badani"],"pulapka":"Kaskada celów opiera się na badaniach Antwerp Management School, IT Alignment and Governance Institute w Belgii, a nie na normie ISO."},"bk_kaskada":{"kw":["kaskad","cele przedsiębiorstwa","cele aktywator"],"pulapka":"Kaskada biegnie od potrzeb interesariuszy przez cele przedsiębiorstwa i cele związane z IT do celów aktywatorów; odwrócona kolejność lub pominięty poziom to typowa pułapka."},"bk_kcs":{"kw":["czynniki sukcesu","czynnik sukcesu","kluczowe czynniki"],"pulapka":"Kluczowych czynników sukcesu jest pięć: wsparcie kierownictwa, zrozumienie celów, komunikacja, dostosowanie, szybkie korzyści; nie myl ich z punktami zapalnymi."},"bk_kcs1":{"kw":["najwyższego kierownictwa","wsparci","kierownictw"],"pulapka":"Czynnik sukcesu to wytyczne, uprawnienia i stałe, widoczne wsparcie najwyższego kierownictwa, a nie jednorazowa zgoda na start projektu."},"bk_kcs2":{"kw":["cele biznesowe","rozumie","zrozumie"],"pulapka":"Cele biznesowe i cele IT muszą rozumieć wszystkie strony wspierające procesy nadzoru i zarządzania, a nie tylko dział IT lub tylko zarząd."},"bk_kcs3":{"kw":["komunikacj","zmian"],"pulapka":"Efektywna komunikacja i umożliwienie koniecznych zmian to jeden czynnik sukcesu; samo ogłoszenie zmiany, bez wsparcia, nie wystarczy."},"bk_kcs4":{"kw":["dostosow","kontekst"],"pulapka":"Dostosować trzeba zarówno COBIT, jak i inne dobre praktyki i normy do unikalnego kontekstu przedsiębiorstwa; COBIT nie jest wdrażany „z pudełka”."},"bk_kcs5":{"kw":["szybkie korzyści","szybkich korzyści","quick win"],"pulapka":"Priorytet mają szybkie korzyści oraz usprawnienia najkorzystniejsze i najłatwiejsze; nie te najtrudniejsze ani najbardziej kosztowne."},"bk_kcs_nadzor":{"kw":["kluczowe czynniki sukcesu","rozliczalnoś"],"pulapka":"Dwa kluczowe czynniki sukcesu Ładu z zasady Sprawność: zatwierdzenie celów przez interesariuszy i akceptacja rozliczalności przez dyrektorów i kierowników; nie myl ich z czynnikami sukcesu wdrożenia."},"bk_kont1":{"kw":["kontekst","kultur","etyk"],"pulapka":"Etyka i kultura to czynnik kontekstu do planu wdrożenia, a zarazem treść aktywatora „Kultura, etyka i zachowanie”; nie mieszaj tych dwóch list."},"bk_kont10":{"kw":["branż","praktyk","kontekst"],"pulapka":"Praktyki stosowane w branży to dziesiąty czynnik kontekstu wdrożenia; COBIT często opiera się na innych standardach, które też trzeba dostosować."},"bk_kont2":{"kw":["przepis","regulacj","kontekst"],"pulapka":"Obowiązujące przepisy, regulacje i polityki to czynnik kontekstu do planu wdrożenia; nie myl go z punktem zapalnym „niespełnianie wymogów regulacyjnych”."},"bk_kont3":{"kw":["misj","wizj","kontekst"],"pulapka":"Misja, wizja i wartości to czynnik kontekstu do planu wdrożenia, a nie element listy 17 celów przedsiębiorstwa (Rysunek 5)."},"bk_kont4":{"kw":["polityk","nadzor","kontekst"],"pulapka":"Istniejące polityki i praktyki nadzoru to czynnik kontekstu; COBIT zaleca wykorzystać i rozwinąć istniejące aktywatory ładu, a nie zaczynać od zera."},"bk_kont5":{"kw":["strategi","kontekst"],"pulapka":"Plan biznesowy i strategiczne kierunki to jeden z dziesięciu czynników kontekstu do planu wdrożenia; nie myl go z uzasadnieniem biznesowym (business case)."},"bk_kont6":{"kw":["dojrzałoś","model operacyjn","kontekst"],"pulapka":"Model operacyjny i poziom dojrzałości to czynnik kontekstu; „dojrzałość” nie oznacza tu poziomu potencjału procesu z rozdziału 8."},"bk_kont7":{"kw":["styl zarządzania","kontekst","zarządzani"],"pulapka":"Styl zarządzania to czynnik kontekstu do planu wdrożenia; nie jest kategorią aktywatora ani wymiarem aktywatora."},"bk_kont8":{"kw":["apetyt na ryzyko","ryzyk","kontekst"],"pulapka":"Apetyt na ryzyko wymieniono jako wewnętrzny czynnik kontekstu kaskady i kontekstu wdrożenia. Zmiana apetytu może też w praktyce pobudzić doskonalenie; listy w podręczniku nie są rozłączną klasyfikacją wszystkich sytuacji."},"bk_kont9":{"kw":["zasob","potencjał","kontekst"],"pulapka":"Potencjał i dostępne zasoby to czynnik kontekstu wdrożenia; „potencjał” nie oznacza tu poziomu potencjału procesu (PCM)."},"bk_kont_aktyw":{"kw":["istniejąc","aktywator","ładu korporacyjnego"],"pulapka":"Należy wykorzystać i rozwinąć istniejące aktywatory ładu korporacyjnego; podejście „zacznij od zera i zastąp wszystko COBIT-em” jest błędne."},"bk_kontekst_wew":{"kw":["apetyt na ryzyko","wewnętrzn","kultur"],"pulapka":"Apetyt na ryzyko jest w COBIT 5 czynnikiem wewnętrznym kontekstu (obok kultury i organizacji), a nie zewnętrznym."},"bk_kontekst_zew":{"kw":["zewnętrzn","geopolityczn","rynek"],"pulapka":"Rynek, branża i sytuacja geopolityczna to czynniki zewnętrzne; kultura, organizacja i apetyt na ryzyko to wewnętrzne; egzamin lubi je mieszać."},"bk_korzysci_formy":{"kw":["usługi publiczn","finansow","korzyś"],"pulapka":"Korzyści nie muszą być finansowe: w podmiotach rządowych są nimi usługi publiczne; tworzenie wartości dotyczy także firm niekomercyjnych."},"bk_kr_sr":{"kw":["krąg środkowy","umożliwienie zmian","rysunek 17"],"pulapka":"Krąg środkowy to umożliwienie zmian (zachowanie i kultura); nie myl go z kręgiem zewnętrznym, czyli zarządzaniem programem."},"bk_kr_wew":{"kw":["krąg wewnętrzny","ciągłego doskonalenia","rysunek 17"],"pulapka":"Krąg wewnętrzny Rysunku 17 to cykl życia ciągłego doskonalenia; zarządzanie programem to krąg zewnętrzny."},"bk_kr_zew":{"kw":["krąg zewnętrzny","zarządzanie programem","rysunek 17"],"pulapka":"Krąg zewnętrzny to zarządzanie programem; umożliwienie zmian to krąg środkowy, a ciągłe doskonalenie to krąg wewnętrzny."},"bk_krok2":{"kw":["cele przedsiębiorstwa","bsc","17 cel"],"pulapka":"Celów przedsiębiorstwa jest 17, opartych na wymiarach BSC; lista jest typowa i niewyczerpująca, a tabela potrzeb i celów jest w Załączniku D."},"bk_krok3":{"kw":["cele związane z it","załącznik b","it bsc"],"pulapka":"Celów związanych z IT jest 17, uporządkowanych wg IT BSC; mapowanie celów przedsiębiorstwa na cele IT to Załącznik B, nie C."},"bk_krok4":{"kw":["załącznik c","cele aktywator","krok 4"],"pulapka":"Cele aktywatorów to ostatni krok kaskady; mapowanie celów IT na procesy jest w Załączniku C, ale cele dotyczą wszystkich aktywatorów, nie tylko procesów."},"bk_lv1_wazny":{"kw":["poziom 1","pa 1.1","ważnym osiągnięciem"],"pulapka":"Poziom 1 istotnie różni się od wyższych: sprawdza, czy proces osiąga cel (PA 1.1 co najmniej W); już sam poziom 1 podręcznik nazywa ważnym osiągnięciem."},"bk_lv_def0":{"kw":["proces niekompletny","poziom 0"],"pulapka":"Poziom 0 to „proces niekompletny”, a nie „nieistniejący” (nazwa z COBIT 4.1): proces może działać, ale nie osiągać celu, np. PA 1.1 ocenione na C daje poziom 0."},"bk_lv_def1":{"kw":["proces wykonywany","pa 1.1","poziom 1"],"pulapka":"Poziom 1 ma jeden atrybut, PA 1.1 Wykonanie procesu, ocenione co najmniej na W; planowanie i monitorowanie realizacji to dopiero poziom 2 (PA 2.1)."},"bk_lv_def2":{"kw":["proces zarządzany","pa 2.1","pa 2.2"],"pulapka":"Poziom 2 ma dwa atrybuty: PA 2.1 Zarządzanie wydajnością i PA 2.2 Zarządzanie produktami pracy; zdefiniowany standardowy proces pojawia się dopiero na poziomie 3."},"bk_lv_def3":{"kw":["proces ustanowiony","pa 3.1","pa 3.2"],"pulapka":"Poziom 3 to „proces ustanowiony”: PA 3.1 Definicja i PA 3.2 Wdrożenie procesu; „zdefiniowany proces” to nazwa poziomu 3 w COBIT 4.1, nie w COBIT 5."},"bk_lv_def4":{"kw":["proces przewidywalny","pa 4.1","pa 4.2"],"pulapka":"Poziom 4 to „proces przewidywalny” (PA 4.1 Miara, PA 4.2 Kontrola procesu), a nie „zarządzany i mierzalny” – tak nazywał się poziom 4 w COBIT 4.1."},"bk_lv_def5":{"kw":["proces zoptymalizowany","pa 5.1","pa 5.2","optymalizujący"],"pulapka":"Poziom 5 (egzamin: proces zoptymalizowany, podręcznik: optymalizujący) ma PA 5.1 Innowacja i PA 5.2 Optymalizacja; poziom docelowy bardzo rzadko jest najwyższy."},"bk_lv_docel":{"kw":["poziom docelowy","docelowy poziom","korzyści"],"pulapka":"Poziom docelowy wybiera organizacja na podstawie kosztów, korzyści i wykonalności; bardzo rzadko jest to najwyższy poziom, więc odpowiedź „zawsze poziom 5” jest błędna."},"bk_lv_regula":{"kw":["co najmniej w","w pełni","poziom 3"],"pulapka":"Wyższy poziom wymaga oceny P (pełny) atrybutów niższych poziomów i co najmniej W atrybutów danego poziomu; ocena W na poziomie 2 nie pozwala uzyskać poziomu 3."},"bk_map_b":{"kw":["rysunek 22","cele związane z it","cele organizacji"],"pulapka":"Rysunek 22 mapuje 17 celów organizacji (wymiary BSC) na 17 celów związanych z IT (IT BSC); mapowanie celów IT na 37 procesów to Rysunek 23 z Załącznika C."},"bk_map_c":{"kw":["rysunek 23","37 procesów","cele związane z it"],"pulapka":"Rysunek 23 mapuje 17 celów związanych z IT na 37 procesów COBIT 5 według domen, skalą P/S; powiązanie celów organizacji z celami IT jest w Rysunku 22."},"bk_map_c_ps":{"kw":["podstawow","drugorzędn","mapowani"],"pulapka":"W Załączniku C P/S mówi, czy proces ma podstawowe czy drugorzędne znaczenie dla celu IT; to ta sama skala co w Załączniku B, a w Załączniku D jej nie ma."},"bk_map_d":{"kw":["potrzeby interesariuszy","rysunek 7","cele organizacji"],"pulapka":"Rysunek 24 łączy pytania wewnętrznych interesariuszy (z Rysunku 7) z 17 celami organizacji; to nie mapowanie celów IT na procesy ani celów organizacji na cele IT."},"bk_map_d_uzycie":{"kw":["priorytet","potrzeby interesariuszy","kaskad"],"pulapka":"Tabelę z Załącznika D używa się do wyznaczania i priorytetyzacji celów organizacji lub celów IT na podstawie potrzeb interesariuszy, ale nie mechanicznie – to sugerowany typowy zbiór."},"bk_map_d_zasada":{"kw":["potrzeby interesariuszy","zaznacz","cele organizacji"],"pulapka":"W Rysunku 24 komórka jest po prostu wypełniona, gdy potrzeba dotyczy danego celu; nie ma tu skali P/S znanej z Załączników B i C."},"bk_map_ostroznie":{"kw":["mechaniczn","kaskad","dostosow"],"pulapka":"Tabele mapowań to typowy zbiór relacji, a nie mechaniczna reguła: sytuacja każdej organizacji jest inna, więc kaskadę celów trzeba do niej dostosować."},"bk_map_ps":{"kw":["podstawow","drugorzędn","wspierając"],"pulapka":"W mapowaniach P oznacza relację podstawową (Primary), a S wspierającą (Secondary), wciąż silną; to nie skala ocen N, C, W, P, gdzie P znaczy „pełny”."},"bk_map_zrodla":{"kw":["badań","mapowani"],"pulapka":"Mapowania oparto na badaniach Antwerp Management School (IT Alignment and Governance Research Institute) i opiniach ekspertów; nie wynikają z normy ISO/IEC 15504 ani z COBIT 4.1."},"bk_metodyki_cechy":{"kw":["struktury ramowe","kompleksow","elastyczn"],"pulapka":"Struktury ramowe (podręcznik: metodyki) mają być kompleksowe, otwarte i elastyczne, aktualne i dostępne dla interesariuszy; to nie cechy polityk ani kryteria zasad."},"bk_miernik_def":{"kw":["smart","miernik"],"pulapka":"Miernik to wymierna jednostka pomiaru celu procesu spełniająca SMART: specyficzny, wymierny, oparty na działaniach, istotny, terminowy; „S” nie znaczy „strategiczny”."},"bk_mm41_kroki":{"kw":["model dojrzałości","cobit 4.1","cele kontrolne"],"pulapka":"Cele kontrolne, modele dojrzałości i mechanizmy kontrolne procesów (PC) to elementy COBIT 4.1; w COBIT 5 zastąpił je model zdolności procesu oparty na ISO/IEC 15504."},"bk_mm41_pc":{"kw":["mechanizmy kontrolne procesów","cobit 4.1","atrybut"],"pulapka":"Mechanizmy kontrolne procesów (PC) to typowe cele kontrolne COBIT 4.1, częściowo pokrywające się z atrybutami modelu dojrzałości; w COBIT 5 ich treść przeniesiono na poziomy 2–5."},"bk_mm_cel":{"kw":["dojrzałoś","tak jest","luk"],"pulapka":"Modele dojrzałości COBIT 4.1, Risk IT i Val IT mierzą stan „tak jest”, „tak ma być” i lukę; PCM COBIT 5 ma te same cele, ale inny projekt i sposób użycia."},"bk_mon_2poz":{"kw":["edm05","mea","monitorowani"],"pulapka":"COBIT 5 ma dwa poziomy monitorowania: Ładu (EDM05, rola dyrektora) i Zarządzania (MEA); MEA to domena Zarządzania, a nie Ładu."},"bk_mon_nadzor_def":{"kw":["monitorowani","organ nadzorując","wcielon"],"pulapka":"W Ładzie monitorowanie to sprawdzanie przez organ nadzorujący, w jakim stopniu kierunek wcielono w życie; nie myl go z operacyjnym monitorowaniem w MEA."},"bk_nadzor_def":{"kw":["edm","kierowani","ocena, kierowanie"],"pulapka":"Ład to Ocena, Kierowanie, Monitorowanie (EDM); planowanie, budowanie i uruchamianie należą do Zarządzania, więc „planowanie” w definicji Ładu to pułapka."},"bk_nadzor_kto":{"kw":["prezes","zarząd","organ nadzorując"],"pulapka":"Za Ład zwykle odpowiada organ nadzorujący (board), kierowany przez przewodniczącego; zadania można delegować. Za Zarządzanie odpowiada kierownictwo wykonawcze pod przywództwem CEO. Polski podręcznik tłumaczy board/chairman jako „zarząd/prezes”; nie utożsamiaj przez to przewodniczącego z CEO w każdym ustroju organizacji."},"bk_nadzor_negocjacja":{"kw":["negocj","interesariusz","wartoś"],"pulapka":"Ład negocjuje i decyduje o wartości dla różnych interesariuszy, uwzględniając wszystkich; nie chodzi o spełnienie oczekiwań jednej grupy, np. akcjonariuszy."},"bk_oc1":{"kw":["porówna","ocena zdolności"],"pulapka":"Porównywanie zdolności procesów to cel oceny dla organu Ładu i kierownictwa; nie myl go z porównywaniem wyników COBIT 4.1 i COBIT 5, które podręcznik uznaje za trudne."},"bk_oc2":{"kw":["jak jest","jak ma być","inwestyc"],"pulapka":"Określenie „jak jest” i „jak ma być” jest wysokopoziomowe i przybliżone; ma ułatwić organowi Ładu i kierownictwu decyzje inwestycyjne o usprawnieniu procesów, nie zastępuje szczegółowego audytu."},"bk_oc3":{"kw":["analiza luk","analizy luk","doskonal"],"pulapka":"Analiza luk daje informacje do planowania udoskonaleń i możliwych do uzasadnienia projektów doskonalenia; w cyklu wdrożenia to faza 3 („Do czego dążymy?”), a nie faza 2."},"bk_oc4":{"kw":["klasyfikac","monitorowan","ocena zdolności"],"pulapka":"Klasyfikacja ocen służy organowi Ładu i kierownictwu do pomiaru i monitorowania aktualnej zdolności procesów; nie jest rankingiem pracowników ani oceną ich kompetencji."},"bk_oc_ambicja":{"kw":["poziom 1","wszystkich procesów"],"pulapka":"Ambicją wielu organizacji jest poziom 1 dla wszystkich procesów, bo inaczej po co je realizować; nie znaczy to, że COBIT wymaga dla każdego procesu poziomu 3 lub wyżej."},"bk_oc_cele":{"kw":["jak jest","analiza luk","ocena zdolności"],"pulapka":"Cztery cele oceny: porównanie zdolności, „jak jest” i „jak ma być”, analiza luk z planowaniem doskonalenia, klasyfikacja ocen do monitorowania; nie myl ich z pytaniami zarządzania wydajnością aktywatora."},"bk_oc_cele_typ":{"kw":["certyfikac","samoocen","wewnętrzn"],"pulapka":"Ocena zdolności może mieć cel wewnętrzny (porównania, doskonalenie) albo zewnętrzny (formalna ocena, raportowanie, certyfikacja) z różnym rygorem; nie służy wyłącznie certyfikacji."},"bk_oc_lv1_kroki":{"kw":["rezultat","praktyki bazowe","produkty pracy"],"pulapka":"Opis ogólnej oceny na s. 45 zaczyna się od wyników procesu i ratingu, potem uwzględnia praktyki bazowe i produkty pracy. Dokumenty mogą stanowić dowody wyników; nie wynika stąd zakaz korzystania z nich na początku oceny."},"bk_oc_plan":{"kw":["praktyki bazowe","poziom 1","doskonal"],"pulapka":"Gdy brak poziomu 1, przyczynę wskazuje ocena praktyk bazowych (których brakuje lub które nie działają); nie zaczyna się od atrybutów poziomu 2, bo dotyczą zarządzania procesem."},"bk_oc_wyzsze":{"kw":["praktyki ogólne","typowe praktyki","15504"],"pulapka":"Wyższe poziomy ocenia się typowymi (ogólnymi) praktykami z ISO/IEC 15504-2, wspólnymi dla wszystkich procesów; praktyki bazowe danego procesu służą poziomowi 1."},"bk_p5_cele":{"kw":["apo08","relacj","zadowoleni"],"pulapka":"Przykładowe cele i mierniki dotyczą APO08 Zarządzanie relacjami; miernikiem dobrych relacji są ankiety zadowolenia użytkowników i personelu IT."},"bk_p5_cykl":{"kw":["potencjał","15504","cykl życia"],"pulapka":"Solidność procesu zwiększa się przez podniesienie poziomu potencjału procesu (model oparty na ISO/IEC 15504), a nie poziomu dojrzałości COBIT 4.1."},"bk_p5_inne":{"kw":["polityk","raci","umiejętnoś"],"pulapka":"Zasady i polityki formalizują proces: dlaczego istnieje, kogo dotyczy i jak go używać; umiejętności definiuje się dla ról, a struktury widać w tabeli RACI."},"bk_p5_praktyki":{"kw":["procesy umożliwiające","dobre praktyki","przewodnik"],"pulapka":"Dobre praktyki dla procesów szczegółowo opisuje przewodnik COBIT 5: Procesy umożliwiające (inspiracja i przykładowe procesy), a nie sama metodyka."},"bk_p5_raci":{"kw":["raci","interesariusz"],"pulapka":"Interesariuszami procesu są wszystkie strony RACI, nie tylko wykonawcy; tabelę RACI opisuje przewodnik COBIT 5: Procesy umożliwiające."},"bk_pam":{"kw":["pam","model oceny procesu","oszacowani"],"pulapka":"Szczegóły oszacowania potencjału zawiera publikacja ISACA COBIT Process Assessment Model (PAM), a nie sama metodyka COBIT 5."},"bk_pbrm_41":{"kw":["cobit 4.1","dopasowanie, planowanie","apo"],"pulapka":"Domeny PBRM rozwijają domeny COBIT 4.1, a ich nazwy mają dodatkowe określenia, np. „Dopasowanie, planowanie i organizacja” (APO), nie samo „Planowanie”."},"bk_pcm":{"kw":["model potencjału","potencjał","15504"],"pulapka":"PCM opiera się na ISO/IEC 15504 i mierzy procesy EDM i PBRM; nie jest kontynuacją skali dojrzałości COBIT 4.1."},"bk_pcm_korz":{"kw":["korzyści","model zdolności","zdolności procesu"],"pulapka":"Korzyści modelu zdolności to skupienie na celu procesu, uproszczenie, wiarygodność i powtarzalność ocen, użyteczność i zgodność ze standardem; nigdzie nie obiecuje wyższych wyników niż COBIT 4.1."},"bk_pcm_ograniczenie":{"kw":["siedmiu","aktywator","pełnego obrazu"],"pulapka":"Procesy to tylko jeden z siedmiu aktywatorów, więc ocena procesów nie daje pełnego obrazu nadzoru; trzeba ocenić też pozostałe aktywatory."},"bk_pk1":{"kw":["osiąga swój cel","rezultat","cel procesu"],"pulapka":"Pierwsza korzyść to skupienie na tym, czy proces faktycznie osiąga swój cel i wymagane rezultaty, a nie na dokumentacji czy ogólnej dojrzałości organizacji."},"bk_pk2":{"kw":["uproszczenie","powiel","cele kontrolne"],"pulapka":"Uproszczenie to usunięcie powielania treści: ocena w COBIT 4.1 wymagała typowego modelu dojrzałości, modeli dojrzałości procesów, celów kontrolnych i mechanizmów kontrolnych procesów."},"bk_pk3":{"kw":["powtarzalność","niezawodność","spor"],"pulapka":"Korzyścią jest większa wiarygodność i powtarzalność ocen, która ogranicza spory interesariuszy o wyniki; podręcznik nie mówi o szybszej ani tańszej ocenie."},"bk_pk4":{"kw":["formaln","samoocen","zewnętrzn"],"pulapka":"Model daje podstawę do bardziej formalnej, rygorystycznej oceny zarówno do celów wewnętrznych, jak i zewnętrznych; nie służy wyłącznie nieformalnej samoocenie."},"bk_pk5":{"kw":["15504","standard","norm"],"pulapka":"Model zdolności COBIT 5 opiera się na uznanej normie ISO/IEC 15504, a nie na ISO/IEC 38500 (Ład IT) ani ISO/IEC 27000 (bezpieczeństwo informacji)."},"bk_podejscie_nadzor":{"kw":["role, działania i relacje","cel nadzoru","rysunek 8"],"pulapka":"Podejście do nadzoru (Rysunek 8) ma cztery elementy: cel nadzoru, aktywatory nadzoru, zakres nadzoru oraz role, działania i relacje; nie ma tam „procesów EDM”."},"bk_pol_dobre":{"kw":["nieinwazyjn","skuteczn","wydajn"],"pulapka":"Dobre polityki są skuteczne, wydajne i nieinwazyjne (podręcznik: nieingerencyjne); „kompleksowe, otwarte i elastyczne” to cechy struktur ramowych, nie polityk."},"bk_pol_dostep":{"kw":["dostęp do polityk","polityk"],"pulapka":"Dostęp do polityk to pytanie, czy interesariusze wiedzą, gdzie je znaleźć; to cel z kategorii dostępu i bezpieczeństwa, a nie jakości kontekstowej."},"bk_polityki_def":{"kw":["polityka","wytyczn"],"pulapka":"Polityka daje szczegółowe wytyczne, jak stosować zasady w praktyce i w decyzjach, a zasada wyraża podstawowe wartości; nie odwracaj tej hierarchii."},"bk_poziomy_usl":{"kw":["poziomy usług","sla","apo09"],"pulapka":"Poziomy usług muszą zdefiniować i osiągnąć dostawcy usług; to dobra praktyka zdolności usługowej, a definiowanie usług w umowach SLA w procesach to APO09."},"bk_prak1":{"kw":["rysunek 20","cobit 4.1","model dojrzałości"],"pulapka":"Wyników COBIT 4.1 i COBIT 5 nie porównuje się wprost mimo podobnej skali i słów, bo różnią się zakresem, ukierunkowaniem i intencją (Rysunek 20)."},"bk_prak2":{"kw":["niższe","model dojrzałości","poziom 0"],"pulapka":"W COBIT 5 wyniki są zwykle niższe: proces z poziomem 1 lub 2 w COBIT 4.1, który nie osiąga w pełni celów, może dostać 0 lub 1, nie wyższy wynik."},"bk_prak3":{"kw":["model dojrzałości","każdego procesu","15504"],"pulapka":"COBIT 5 zrezygnował z osobnego modelu dojrzałości dla każdego procesu, bo ISO/IEC 15504 tego nie wymaga, a wręcz uniemożliwia; ocenia się wspólnymi atrybutami."},"bk_prak4":{"kw":["profil","n, c, w, p","dziewięciu atrybut"],"pulapka":"W COBIT 5 każdy proces można ocenić dla każdego z 9 atrybutów zdolności, każdy skalą N, C, W, P; „profil dojrzałości” to pojęcie z COBIT 4.1."},"bk_prak5":{"kw":["rysunek 21","przeklasyfik","atrybut"],"pulapka":"Atrybuty dojrzałości COBIT 4.1 i zdolności COBIT 5 częściowo się pokrywają. Rysunek 21 pomaga ponownie wykorzystać i przeklasyfikować wcześniejsze ustalenia; nie jest automatycznym przelicznikiem poziomów ani zwolnieniem z weryfikacji dowodów."},"bk_praktyki_cechy":{"kw":["praktyki ładu","praktyki zarządzania","praktyka ładu"],"pulapka":"Praktyki Ładu/Zarządzania są typowe (trzeba je dostosować), zgodne ze standardami i obejmują role biznesu oraz IT; nie są gotowe do wdrożenia bez zmian."},"bk_praktyki_wybor":{"kw":["praktyk","dostosow","ryzyko"],"pulapka":"Organ Ładu i kierownictwo wybierają praktyki, dodają lub dostosowują je, ustalają sposób wdrożenia i mogą zaakceptować ryzyko niewdrożenia; COBIT nie wymaga wdrożenia wszystkich."},"bk_prm_biznes_it":{"kw":["referencyjny model procesu","całej organizacji"],"pulapka":"PRM obejmuje całość działań biznesu i IT związanych z Ładem i Zarządzaniem informacją i technologią. Jest ogólnofirmowy, ale nie opisuje wszystkich działań przedsiębiorstwa niezależnych od IT."},"bk_prm_daje":{"kw":["audyt","dostawc","sprawnoś"],"pulapka":"Wspólny model procesów daje: pomiar i monitorowanie sprawności IT, audyt IT, komunikację z dostawcami usług i wdrażanie dobrych praktyk."},"bk_prm_info":{"kw":["praktyki bazowe","praktyka bazowa","produkty pracy","wejścia i wyjścia"],"pulapka":"W referencyjnym modelu procesu praktyki bazowe to odpowiednik praktyk Ładu/Zarządzania, a produkty pracy – odpowiednik wejść i wyjść; nie myl ich z działaniami ani miernikami."},"bk_prm_jezyk":{"kw":["wspólny język","wspólny model","język"],"pulapka":"Wprowadzenie modelu operacyjnego i wspólnego języka dla IT i biznesu to jeden z najważniejszych kroków ku właściwemu nadzorowi, a nie szczegół techniczny."},"bk_prm_kryt":{"kw":["referencyjny model procesu","model referencyjny procesu","opis procesu"],"pulapka":"Wymogi ISO/IEC 15504-2 dotyczą opisu procesu w referencyjnym modelu procesu: cel i rezultaty, brak cech powyżej poziomu 1, wspólne atrybuty na poziomach 2–5; to nie kryteria SMART."},"bk_prm_kryt1":{"kw":["przeznaczenie procesu","rezultat","opis procesu"],"pulapka":"Opis procesu musi zawierać przeznaczenie i rezultaty procesu; to na ich podstawie ocenia się PA 1.1, a nie na podstawie mierników z poziomu 4."},"bk_prm_kryt2":{"kw":["procesy umożliwiające","poziom 1","opis procesu"],"pulapka":"PRM opisuje cel i wyniki procesu oraz praktyki potrzebne do ich osiągnięcia. Nie włącza ogólnych atrybutów zdolności poziomów 2–5 do definicji procesu. Konkretna praktyka może jednak wymagać planowania lub pomiaru, jeśli służy to celowi tego procesu; sam pomiar nie dowodzi PA 4.1."},"bk_prm_kryt3":{"kw":["mechanizmy kontrolne procesów","typowe praktyki","praktyki ogólne"],"pulapka":"Dawne mechanizmy kontrolne procesów (PC) z COBIT 4.1 nie zniknęły: wspólne atrybuty trafiły na poziomy 2–5 modelu oceny, co usuwa powielanie celów kontrolnych."},"bk_prm_nastepca":{"kw":["val it","risk it","cobit 4.1"],"pulapka":"PRM COBIT 5 jest następcą modelu procesów COBIT 4.1 i łączy modele procesów Risk IT oraz Val IT; nie wywodzi się z ITIL."},"bk_prm_niejedyny":{"kw":["model referencyjny","prm","jedyn"],"pulapka":"PRM jest kompletny i kompleksowy, ale nie jest jedynym możliwym modelem; każde przedsiębiorstwo definiuje własny zbiór procesów."},"bk_prm_przewodnik":{"kw":["procesy umożliwiające","37","przewodnik"],"pulapka":"Pełne opisy 37 procesów są w przewodniku COBIT 5: Procesy umożliwiające, a nie w samej metodyce COBIT 5."},"bk_prm_wielkosc":{"kw":["wielkoś","mniejsz","37 proces"],"pulapka":"Mniejsze firmy mogą mieć mniej procesów, większe więcej, ale wszystkie służą tym samym celom; 37 procesów to nie obowiązkowa liczba."},"bk_proc_nadz_vs_zarz":{"kw":["procesy ładu","proces ładu","pbrm"],"pulapka":"Procesy Ładu dotyczą tworzenia wartości (korzyści, ryzyko, zasoby) i zawierają praktyki EDM; procesy Zarządzania obejmują obszary PBRM; różnica tkwi w celach procesów, nie w nazwie działu."},"bk_proc_pbrm_wew":{"kw":["pbrm","planowani","procesy ładu"],"pulapka":"Każdy proces, także Ładu, wewnętrznie wymaga planowania, budowania, realizacji i monitorowania; nie znaczy to, że procesy EDM należą do domen PBRM Zarządzania."},"bk_proces_def":{"kw":["zbiór praktyk","proces"],"pulapka":"Proces to zbiór praktyk ukierunkowanych przez polityki i procedury, przetwarzający wejścia w wyjścia (produkty, usługi); sam „zbiór działań” bez wejść, wyjść i polityk to niepełna definicja."},"bk_pryncypia":{"kw":["pryncypia architektury","ponowne wykorzystanie","otwartość"],"pulapka":"Przykładowe pryncypia architektury: ponowne wykorzystanie, nabywanie zamiast tworzenia, prostota, zwinność, otwartość; domyślnie się kupuje, a własny rozwój wymaga zatwierdzonego powodu."},"bk_przyklad1":{"kw":["zadowolenie klient","przykład 1","kaskad"],"pulapka":"W Przykładzie 1 z siedmiu celów IT z relacją P firma wybiera jako priorytet tylko pierwsze cztery (01, 04, 07, 09), a nie wszystkie siedem."},"bk_przyklad10":{"kw":["przykład 10","pa 2.1","pa 2.2"],"pulapka":"W Przykładzie 10 kierownicy procesów podnoszą zdolność na poziom 2: PA 2.1 Zarządzanie wydajnością (planowanie, monitorowanie) i PA 2.2 Zarządzanie produktami pracy; to nie poziom 3."},"bk_przyklad11":{"kw":["przykład 11","jakości","zachęt"],"pulapka":"W Przykładzie 11 przyczyną słabej jakości aplikacji były zachęty za termin i budżet, a nie zła metodyka rozwoju; rozwiązaniem są lepsze zachęty sprzyjające jakości."},"bk_przyklad12":{"kw":["obwiniania","apetyt na ryzyko"],"pulapka":"Przykład 12 podaje symptomy złej kultury ryzyka IT: rozbieżność rzeczywistego apetytu na ryzyko i polityk oraz kulturę obwiniania, najważniejszą przeszkodę w skutecznej komunikacji."},"bk_przyklad13":{"kw":["przykład 13","specyfikac","warstw"],"pulapka":"W Przykładzie 13 model informacji wyznacza specyfikację nowej aplikacji pytaniami warstw, a testerzy używają kryteriów jakości informacji do przypadków testowych; ochrona to Przykład 14."},"bk_przyklad14":{"kw":["przykład 14","ochron","warstw"],"pulapka":"W Przykładzie 14 zespoły bezpieczeństwa analizują warstwy i fazy cyklu życia, bo informacja wymaga ochrony już od fazy planowania, a nie dopiero przy przechowywaniu."},"bk_przyklad15":{"kw":["przykład 15","łatwości korzystania","jakości"],"pulapka":"Przykład 15 używa kryteriów jakości informacji do przeglądu procesu biznesowego i oceny łatwości korzystania z danych; to nie ocena zdolności procesu skalą N, C, W, P."},"bk_przyklad1_wn":{"kw":["same procesy","aktywator","kultur"],"pulapka":"Same procesy nie wystarczą: kultura, struktury organizacyjne i umiejętności też wymagają celów; wynik to spójne cele wszystkich aktywatorów i mierniki."},"bk_przyklad2":{"kw":["zrównoważon","kultura innowacji","wykwalifikowany"],"pulapka":"Zrównoważony rozwój w Przykładzie 2 to nie tylko ekologia, lecz wszystko, co składa się na długoterminowy sukces; wybrane cele to 1, 4, 8, 16, 17."},"bk_przyklad3":{"kw":["usług it","umiejętnoś","przykład"],"pulapka":"Przykład 3 pokazuje, że usługi IT wymagają naraz infrastruktury i aplikacji, ludzi z umiejętnościami (także behawioralnymi), procesów i struktur organizacyjnych."},"bk_przyklad4":{"kw":["bezpieczeństw","kultur","etyk"],"pulapka":"W Przykładzie 4 polityki i praktyki bezpieczeństwa informacji nie zadziałają bez odpowiedniej kultury i etyki; to argument za Zasadą 4."},"bk_przyklad5":{"kw":["kierowni","przykład 5","właściciel procesu"],"pulapka":"W Przykładzie 5 kierownicy ds. procesów najpierw analizują aktywator Proces wg czterech wymiarów, a potem sięgają do innych aktywatorów (umiejętności, struktury, polityki)."},"bk_przyklad6":{"kw":["20%","statysty","badani"],"pulapka":"Historyczny Przykład 6 na s. 39 przytacza badanie 250 firm (rentowność wyższa o co najmniej 20%) i ITGI/PwC (38% respondentów wskazało niższe koszty IT). To wyniki przytoczonych badań, nie prognoza ani gwarancja efektów dowolnego wdrożenia."},"bk_przyklad7":{"kw":["ciągłość i dostępność","zwinność it","przykład 7"],"pulapka":"W Przykładzie 7 cel organizacji 7 (ciągłość i dostępność usług) zależy głównie od celów IT 04, 10 i 14, a cel IT 09 Zwinność IT wspiera głównie cele 2, 8, 11 i 17."},"bk_przyklad8":{"kw":["apo13","przykład 8"],"pulapka":"W Przykładzie 8 APO13 Zarządzanie bezpieczeństwem ma P dla celów IT 02, 04, 06, 10 i 14, a S tylko dla 07 i 08; nie tylko dla celu 10 Bezpieczeństwo."},"bk_przyklad9":{"kw":["mediów społecznościowych","przykład 9"],"pulapka":"W Przykładzie 9 nowa polityka mediów społecznościowych jest mniej restrykcyjna i wpływa na inne aktywatory: zachowania, umiejętności i procesy bezpieczeństwa, nie tylko na same polityki."},"bk_ps_corg":{"kw":["podstawow","wspierając","p/s"],"pulapka":"P oznacza relację podstawową, a S wspierającą, czyli słabszą, z celami Ładu (korzyści, ryzyko, zasoby); S nie znaczy „strategiczna” ani „szczegółowa”."},"bk_pub_wdrozenie":{"kw":["wdrożeni","ciągłego doskonalenia","normatywn"],"pulapka":"COBIT 5 – Wdrożenie opiera się na cyklu ciągłego doskonalenia, nie jest normatywny ani kompletnym rozwiązaniem; to zbiór wskazówek."},"bk_pyt12_wynik":{"kw":["wskaźniki opóźnione","opóźnion","następując"],"pulapka":"Pytania o potrzeby interesariuszy i osiągnięcie celów mierzą wynik, czyli wskaźniki opóźnione (podręcznik: „następujące”); nie myl ich z wiodącymi."},"bk_pyt34_dzial":{"kw":["wiodąc","wyprzedzając","wskaźnik"],"pulapka":"Pytania o cykl życia i dobre praktyki mierzą działanie samego aktywatora, czyli wskaźniki wiodące (podręcznik: „wyprzedzające”), a nie wynik."},"bk_pytania_kask":{"kw":["załącznik d","pytania interesariuszy","rysunek 7"],"pulapka":"Pytania interesariuszy z Rysunku 7 są wejściem do kaskady i wiążą się z celami przedsiębiorstwa; ich mapowanie jest w Załączniku D, nie B."},"bk_pz1":{"kw":["frustracj","punkty zapalne","punkt zapal"],"pulapka":"Frustracja biznesu z powodu nieudanych inicjatyw, rosnących kosztów IT i niskiej wartości to punkt zapalny (bieżący problem), a nie zdarzenie wyzwalające."},"bk_pz10":{"kw":["budżet","opóźnieni","punkt zapal"],"pulapka":"Zmiany IT, które nie spełniają potrzeb biznesu, są spóźnione lub przekraczają budżet, to punkt zapalny, a nie czynnik sukcesu ani zdarzenie wyzwalające."},"bk_pz11":{"kw":["sponsor","niechęć","punkt zapal"],"pulapka":"Niechęć zarządu i kierownictwa do współpracy z IT oraz brak zaangażowanych, zadowolonych sponsorów biznesowych to punkt zapalny; nowy CEO to zdarzenie wyzwalające."},"bk_pz12":{"kw":["złożon","model operacyjn","punkt zapal"],"pulapka":"Złożone modele operacyjne IT to punkt zapalny; nie myl go z czynnikiem kontekstu „model operacyjny i poziom dojrzałości”."},"bk_pz2":{"kw":["utrata danych","incydent","punkt zapal"],"pulapka":"Istotne incydenty ryzyka IT, np. utrata danych lub niepowodzenie projektu, to punkt zapalny; audyt zewnętrzny to już zdarzenie wyzwalające."},"bk_pz3":{"kw":["outsourc","poziom usług","punkt zapal"],"pulapka":"Problemy z outsourcingiem, np. ciągłe niedotrzymywanie uzgodnionego poziomu usług, to punkt zapalny; zmiana uzgodnień zaopatrzenia to zdarzenie wyzwalające."},"bk_pz4":{"kw":["regulacyjn","wymog","punkt zapal"],"pulapka":"Niespełnianie obecnych wymogów regulacyjnych lub umownych to punkt zapalny; nowe wymagania regulacyjne to zdarzenie wyzwalające; egzamin rozróżnia oba."},"bk_pz5":{"kw":["innowac","zwinnoś","punkt zapal"],"pulapka":"IT ograniczające innowacyjność i zwinność biznesu to punkt zapalny; nie myl go z istotną zmianą technologii, która jest zdarzeniem wyzwalającym."},"bk_pz6":{"kw":["audyt","jakoś","punkt zapal"],"pulapka":"Audyty regularnie wskazujące słabą sprawność IT lub jakość usług to punkt zapalny; jednorazowy audyt zewnętrzny lub ocena konsultantów to zdarzenie wyzwalające."},"bk_pz7":{"kw":["ukryte","wydatk","punkt zapal"],"pulapka":"Ukryte i nieuczciwe wydatki na IT to punkt zapalny; nie jest to czynnik kontekstu ani zdarzenie wyzwalające."},"bk_pz8":{"kw":["powiel","marnotraw","punkt zapal"],"pulapka":"Powielanie lub nakładanie się inicjatyw i marnotrawstwo zasobów (np. przedwczesne zakończenie projektu) to punkt zapalny; nie myl go z ogólnofirmową inicjatywą, która jest zdarzeniem wyzwalającym."},"bk_pz9":{"kw":["wypaleni","umiejętnoś","punkt zapal"],"pulapka":"Brak zasobów i umiejętności IT oraz wypalenie lub niezadowolenie zespołu to punkt zapalny; nie myl go z czynnikiem kontekstu „potencjał i dostępne zasoby”."},"bk_pz_po_co":{"kw":["punkty zapalne","zdarzenia wyzwalając","pilnoś"],"pulapka":"Punkty zapalne i zdarzenia wyzwalające wiążą uzasadnienie biznesowe z codziennymi problemami, dają poczucie pilności, szybkie korzyści i platformę dalszych zmian."},"bk_raci":{"kw":["raci","rozliczan","konsultowan"],"pulapka":"R to ten, kto wykonuje (odpowiedzialny), a A to ten, kto jest rozliczany za wynik; polskie „odpowiedzialny” i „rozliczany” łatwo zamienić."},"bk_rodzina":{"kw":["rodzina produktów","przewodnik","procesy umożliwiające"],"pulapka":"Procesy umożliwiające i Informacje umożliwiające to przewodniki aktywatorów, a Wdrożenie, Bezpieczeństwo informacji, Audyt i Ryzyko to przewodniki specjalistyczne; łatwo je zamienić miejscami."},"bk_role_dzial":{"kw":["delegowani","rysunek 9","rozliczan"],"pulapka":"Na Rysunku 9 właściciele delegują do organu nadzorującego, ten wyznacza kierunek Zarządzaniu, a ono instruuje Eksploatację; w górę idą raportowanie, monitorowanie i rozliczanie."},"bk_role_info":{"kw":["wytwórca","opiekun","konsument"],"pulapka":"Wytwórca tworzy informację, opiekun (custodian) odpowiada za jej przechowywanie i utrzymanie, a konsument z niej korzysta. Opiekun i właściciel to odmienne role; jedna osoba może pełnić więcej niż jedną rolę."},"bk_role_info_szcz":{"kw":["właściciel","role","faz"],"pulapka":"Szczegółowe role informacyjne (architekt, właściciel, zarządca, powiernik, dostawca, beneficjent itd.) zależą od fazy cyklu życia informacji, więc wymiar interesariuszy nie jest od niego niezależny."},"bk_roz1":{"kw":["model dojrzałości","ad hoc","15504"],"pulapka":"Mimo podobnej skali 0–5 poziomy ISO/IEC 15504 mają inne nazwy i znaczenie niż poziomy dojrzałości COBIT 4.1; proces z poziomem 1 (Ad hoc) może w COBIT 5 dostać 0."},"bk_roz2":{"kw":["dziewięciu atrybut","dziewięć atrybut","9 atrybut"],"pulapka":"COBIT 5 ma 9 atrybutów procesu (PA 1.1–5.2), a COBIT 4.1 miał 6 atrybutów dojrzałości (np. świadomość i komunikowanie); pokrywają się tylko częściowo i inaczej."},"bk_rozw1":{"kw":["przejrzystoś","interesariusz","sprzeczn"],"pulapka":"Chodzi o większy wpływ większej liczby interesariuszy i żądanie przejrzystości; ich oczekiwania bywają rozbieżne, a nawet sprzeczne."},"bk_rozw10":{"kw":["val it","risk it","bmis","itaf"],"pulapka":"Połączone metodyki ISACA to COBIT, Val IT, Risk IT, BMIS, ITAF, Board Briefing on IT Governance i TGF; ITIL czy TOGAF nie są produktami ISACA."},"bk_rozw2":{"kw":["outsourc","dostawc","zewnętrzn"],"pulapka":"Uzależnienie od stron zewnętrznych dotyczy biznesu i IT: outsourcingu, dostawców, konsultantów, klientów, chmury; nie tylko dostawców IT."},"bk_rozw3":{"kw":["model informacji","informacj"],"pulapka":"Problemem nie jest brak informacji, lecz jej nadmiar i wybór istotnych, wiarygodnych danych; pomaga w tym efektywny model informacji."},"bk_rozw4":{"kw":["cio","integraln","biznes"],"pulapka":"Oddzielenie IT od biznesu, nawet przy dobrym dopasowaniu, nie jest już optymalne; IT ma być integralną częścią biznesu, a rola CIO ewoluuje."},"bk_rozw5":{"kw":["innowac","nowe technologie"],"pulapka":"Innowacyjność obejmuje też usprawnienie rozwoju produktów, produkcji i łańcucha dostaw, a nie tylko wymyślanie nowych produktów."},"bk_rozw6":{"kw":["odpowiedzialnoś","kultur","struktur"],"pulapka":"Pełny zakres odpowiedzialności obejmuje biznes i IT oraz struktury, polityki, kulturę i procesy, a nie samą technikę."},"bk_rozw7":{"kw":["użytkownik","inicjowan","kontrol"],"pulapka":"Chodzi o kontrolę nad rozwiązaniami IT inicjowanymi i kontrolowanymi przez użytkowników spoza działu IT, a nie o kontrolę samych użytkowników."},"bk_rozw8":{"kw":["zadowoleni","wartoś","zgodnoś"],"pulapka":"To jeden wyznacznik z czterema elementami: wartość z IT, zadowolenie użytkowników biznesowych, zgodność oraz lepsze relacje potrzeb biznesu i celów IT."},"bk_rozw9":{"kw":["itil","togaf","prince2","coso"],"pulapka":"ITIL, TOGAF, PMBOK, PRINCE2, COSO i ISO to standardy zewnętrzne, z którymi COBIT 5 się wiąże; Val IT i Risk IT to metodyki ISACA wchłonięte przez COBIT 5."},"bk_sfia":{"kw":["sfia","definicje umiejętności"],"pulapka":"SFIA (Skills Framework for the Information Age) to zewnętrzne źródło definicji umiejętności dla aktywatora Ludzie; nie jest modelem oceny procesów ani częścią rodziny produktów COBIT."},"bk_skala_proc":{"kw":["częściowy","większościowy","nieosiągnięty"],"pulapka":"N/C/W/P: 0–15%, >15–50%, >50–85%, >85–100%. Dokładnie 85% to W, nie P. Pełne osiągnięcie wymaga systematyczności i braku istotnych słabości, nie koniecznie 100%."},"bk_spr_regularnie":{"kw":["sprawnoś","mierni","cztery pytania"],"pulapka":"Zarządzanie sprawnością aktywatora to regularne monitorowanie odpowiedzi na cztery pytania przy użyciu mierników, a nie jednorazowa ocena."},"bk_srod_diagn":{"kw":["diagnoz","kondycj","świadomoś"],"pulapka":"Kontrole kondycji, diagnostyka i oceny służą tu podniesieniu świadomości, uzgodnieniu stanowiska i uzyskaniu zobowiązania do działania, a nie tylko pomiarowi."},"bk_srod_kroki":{"kw":["zaangażowani","rol","struktur"],"pulapka":"Zaangażowanie interesariuszy zdobywa się od samego początku, a cele i korzyści przedstawia w kategoriach biznesowych; dopiero potem zasoby, role i struktury."},"bk_srod_nie_cel":{"kw":["samym w sobie","realn","aktywator"],"pulapka":"Aktywatory oparte na COBIT mają rozwiązywać realne potrzeby i problemy biznesu, a nie być celem samym w sobie; wymagania akceptuje kierownictwo."},"bk_srod_niepowodz":{"kw":["niepowodzeni","wsparci","środowisk"],"pulapka":"Istotne inicjatywy IT, także wdrożenia COBIT, zawodzą z braku ukierunkowania, wsparcia i nadzoru interesariuszy; w niekorzystnym środowisku wsparcie jest jeszcze ważniejsze."},"bk_std_27000":{"kw":["27000","27001","bezpieczeństw"],"pulapka":"ISO/IEC 27000 pokrywa procesy bezpieczeństwa i ryzyka w EDM, APO i DSS, działania bezpieczeństwa w innych domenach oraz monitorowanie MEA; nie ogranicza się do DSS."},"bk_std_31000":{"kw":["ryzyk","27000"],"pulapka":"Porównanie w Załączniku E wskazuje dla ISO/IEC serii 31000 procesy zarządzania ryzykiem w EDM i APO. To zakres tego zestawienia, nie zakaz stosowania podejścia do ryzyka w pozostałych obszarach."},"bk_std_cmmi":{"kw":["bai","apo"],"pulapka":"W Załączniku E CMMI dla rozwoju zestawiono z budowaniem aplikacji i nabywaniem w BAI oraz wybranymi procesami APO dotyczącymi organizacji i jakości. Nie jest to pełna lista wszystkich możliwych powiązań ani opis nowszych wydań CMMI."},"bk_std_itil":{"kw":["itil","dss"],"pulapka":"Historyczne zestawienie dotyczy ITIL V3 2011 oraz ISO/IEC 20000: podzbioru DSS i BAI oraz niektórych procesów APO. Nie przenoś tej tabeli automatycznie na inne wydania ITIL ani nie traktuj jej jako zakazu innych powiązań."},"bk_std_map_proc":{"kw":["powiązane wytyczne","procesy umożliwiające","inne standardy"],"pulapka":"Szczegółowe mapowanie każdego procesu na powiązane standardy jest w przewodniku COBIT 5: Procesy umożliwiające (sekcja „Powiązane wytyczne”), a nie w samej strukturze ramowej."},"bk_std_prince2":{"kw":["prince2","bai01","apo05"],"pulapka":"Załącznik E wiąże PRINCE2 z obszarem portfela w APO oraz programami i projektami w BAI. To uproszczone zestawienie COBIT 5; nie oznacza, że samo PRINCE2 jest pełną metodą zarządzania portfelem lub programami. W COBIT wybór portfela to APO05, a programy i projekty to BAI01."},"bk_std_togaf":{"kw":["togaf","apo03","architektur"],"pulapka":"TOGAF 9 odpowiada zasobom w EDM (Rada ds. Architektury) i architekturze korporacyjnej w APO; fazy ADM A–G odwzorowano w praktykach APO03, a nie w BAI."},"bk_std_togaf_komp":{"kw":["togaf","pryncypia architektury","apo03"],"pulapka":"Osiem komponentów TOGAF 9 (m.in. pryncypia architektury, zarządzanie interesariuszami, zgodność i umowy architektury) odwzorowano w praktyce świadczenia usług architektury korporacyjnej (APO03)."},"bk_struktura_ksiazki":{"kw":["rozdział","załącznik"],"pulapka":"Rozdziały 2–6 odpowiadają zasadom 1–5 (przesunięcie o jeden), rozdział 7 to wdrożenie, a rozdział 8 to model potencjału procesu."},"bk_szcz_dzial":{"kw":["szczegółowe działani","itil","prince2"],"pulapka":"Szczegółowych działań nie ma w COBIT 5: Procesy umożliwiające; bierze się je z ITIL, ISO/IEC 27000, PRINCE2 lub dodatkowych produktów rodziny COBIT 5."},"bk_tgf":{"kw":["taking governance forward","tgf"],"pulapka":"Taking Governance Forward (TGF) włączono do COBIT 5 i wycofano jako osobny zasób; nie jest już odrębnie utrzymywaną metodyką."},"bk_toolkit":{"kw":["narzędzia","samoocen","narzędzi"],"pulapka":"Zestaw narzędzi wdrożeniowych ma trzy elementy: narzędzia samooceny, pomiaru i diagnostyki; prezentacje dla różnych odbiorców; artykuły i wyjaśnienia."},"bk_uz1":{"kw":["beneficjen","korzyści biznesow","uzasadnieni"],"pulapka":"Pierwszy element uzasadnienia obejmuje docelowe korzyści i zgodność ze strategią. FW-PL s. 39 używa słowa „beneficjenci”, lecz oryginał EN s. 38 mówi benefit owners: osoby po stronie biznesu odpowiedzialne za uzyskanie korzyści, nie tylko ich odbiorcy."},"bk_uz2":{"kw":["luk","kondycj","zakres"],"pulapka":"Wymagane zmiany biznesowe i zakres (co się w nim mieści, a co nie) ustala się na podstawie kontroli kondycji i analizy luk potencjału."},"bk_uz3":{"kw":["inwestycj","szacun","uzasadnieni"],"pulapka":"Wymagane inwestycje szacuje się na podstawie wymaganych projektów; to osobny element niż bieżące koszty IT i biznesowe."},"bk_uz4":{"kw":["bieżące koszt","koszt","uzasadnieni"],"pulapka":"Bieżące koszty IT i koszty biznesowe to obowiązkowy element uzasadnienia; nie myl ich z inwestycjami wymaganymi do wprowadzenia zmian."},"bk_uz5":{"kw":["oczekiwane korzyści","korzyści","uzasadnieni"],"pulapka":"Oczekiwane korzyści z funkcjonowania po zmianach to osobny element obok docelowych korzyści biznesowych; liczy się tylko korzyści realistyczne."},"bk_uz6":{"kw":["ograniczeni","zależnoś","ryzyk"],"pulapka":"Uzasadnienie musi uwzględniać ryzyko związane z pozostałymi elementami, w tym ograniczenia i zależności, ustalane na podstawie wyzwań i czynników sukcesu."},"bk_uz7":{"kw":["rozliczalnoś","odpowiedzialnoś","rol"],"pulapka":"Role, zakresy odpowiedzialności i rozliczalności to jeden z ośmiu minimalnych elementów uzasadnienia biznesowego, a nie opcjonalny dodatek."},"bk_uz8":{"kw":["ekonomiczn","monitorowani","mierni"],"pulapka":"Monitorowanie inwestycji i tworzenia wartości obejmuje pełny cykl życia ekonomicznego i mierniki oparte na celach; nie kończy się wraz z projektem."},"bk_uzas":{"kw":["uzasadnienie biznesowe","business case","dynamiczn"],"pulapka":"Uzasadnienie biznesowe nie jest jednorazowym, statycznym dokumentem, lecz dynamicznym narzędziem operacyjnym, które stale się aktualizuje."},"bk_uzas_potrzeba":{"kw":["dzwon","pilnoś","potrzeb"],"pulapka":"Potrzeba działania może przyjąć formę „dzwonka alarmowego” (punkty zapalne) albo szansy udoskonalenia; trzeba też uświadomić ryzyko zaniechania."},"bk_uzas_real":{"kw":["realistyczn","kwantyfik","korzyści"],"pulapka":"Kwantyfikacja korzyści bywa trudna, więc skupia się tylko na korzyściach realistycznych i osiągalnych; pomocne są badania przeprowadzone w innych firmach."},"bk_uzas_sponsor":{"kw":["sponsor","odgórn","kamieni"],"pulapka":"Inicjatywa wymaga sponsora i wszystkich kluczowych interesariuszy; podejście odgórne zaczyna od pożądanych wyników biznesowych, potem zadania, kamienie milowe i role."},"bk_wart_def":{"kw":["tworzenie wartości","realizacja korzyści","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości to realizacja korzyści przy optymalnym koszcie zasobów i optymalizacji ryzyka, a nie samo zwiększanie zysku ani cięcie kosztów."},"bk_wdr_tematy":{"kw":["uzasadnienie biznesowe","punkty zapalne","środowisk"],"pulapka":"Cztery tematy: uzasadnienie biznesowe; punkty zapalne i zdarzenia wyzwalające; właściwe środowisko; COBIT do wskazania luk i rozwoju aktywatorów."},"bk_wdr_wart":{"kw":["dostosow","wdrożeni","kultur"],"pulapka":"Wartość z COBIT wymaga przyjęcia i dostosowania wytycznych do środowiska organizacji. Podręcznik podkreśla szczególnie wyzwania kultury i zachowań; nie oznacza to, że technika nie może być wyzwaniem."},"bk_we_wy":{"kw":["wejścia i wyjścia","produkty pracy","ścieżk"],"pulapka":"Wejścia i wyjścia (produkty pracy) definiuje się na poziomie praktyk, nie działań; dają ścieżkę audytu, a lista przykładowych wejść i wyjść COBIT 5 nie jest kompletna."},"bk_wym1_def":{"kw":["interesariusz","wewnętrzn","zewnętrzn"],"pulapka":"Interesariusze aktywatora to strony, które grają aktywną rolę lub są nim zainteresowane; mogą być wewnętrzni i zewnętrzni, nie tylko wykonawcy."},"bk_wym1_kask":{"kw":["potrzeby interesariuszy","rysunek 7","sprzeczn"],"pulapka":"Potrzeby interesariuszy przekładają się na cele przedsiębiorstwa, a te na cele związane z IT; listę interesariuszy pokazuje Rysunek 7."},"bk_wym2_kryt":{"kw":["cele aktywator","jakość","oczekiwan"],"pulapka":"Cele aktywatora definiuje się wg oczekiwanych wyników i wg zastosowania samego aktywatora; kategorie celów to jakość rzeczywista, kontekstowa oraz dostęp i bezpieczeństwo."},"bk_wym2_ostatni":{"kw":["ostatni","kaskad","cele aktywator"],"pulapka":"Cele aktywatorów to ostatni etap kaskady celów; nie są jej punktem wyjścia ani celami przedsiębiorstwa."},"bk_wym3_def":{"kw":["cykl życia","planowanie","pozbywa"],"pulapka":"Fazy cyklu życia aktywatora to planowanie, projektowanie, budowanie/nabywanie, użytkowanie, ocena/monitorowanie, aktualizacja/pozbywanie się; to nie siedem faz wdrożenia z Rysunku 17."},"bk_wym4_def":{"kw":["dobre praktyki","produkty działań","dobrych praktyk"],"pulapka":"Dobre praktyki obejmują praktyki oraz produkty działań (dane wejściowe i wyniki); to czwarty wymiar aktywatora, obok interesariuszy, celów i cyklu życia."},"bk_wym4_zrodla":{"kw":["dobre praktyki","standard","metodyk"],"pulapka":"COBIT 5 daje przykłady dobrych praktyk tylko dla niektórych aktywatorów (np. procesów); dla innych korzysta się z wytycznych innych standardów i metodyk."},"bk_wym_korz":{"kw":["wymiar","wspólnych wymiar"],"pulapka":"Wspólne wymiary dają typowe, proste i ustrukturyzowane użycie aktywatorów, zarządzanie ich złożonymi interakcjami i skuteczne wykorzystanie."},"bk_wyzn_inter":{"kw":["wyznacznik","potrzeby interesariuszy","krok 1"],"pulapka":"Krok 1 to wyznaczniki (zmiany strategii, otoczenia biznesowego i regulacyjnego, nowe technologie), które wpływają na potrzeby; potrzeby nie są jeszcze celami przedsiębiorstwa."},"bk_z2_a":{"kw":["wszystkich aspektów","funkcji it","wszystkie funkcje"],"pulapka":"Zasada 2 nie ogranicza się do funkcji IT; informacja i technologia to aktywa, o które dbają wszyscy pracownicy, jak o każdy inny zasób."},"bk_z2_b":{"kw":["kompleksow","ogólnofirmow","wewnątrz"],"pulapka":"Aktywatory są ogólnofirmowe i kompleksowe: obejmują wszystkich i wszystko, także strony spoza przedsiębiorstwa; ograniczenie ich do wnętrza firmy to błąd."},"bk_z2_info":{"kw":["cykl życia","informacj","wymog"],"pulapka":"Model aktywatora pozwala zdefiniować wymogi informacyjne i cykl życia informacji; Informacja to aktywator, który łączy potrzeby biznesu z IT."},"bk_z2_lad_korp":{"kw":["ładu korporacyjnego","ład korporacyjn"],"pulapka":"Ład IT jest częścią ładu korporacyjnego i da się go płynnie zintegrować z każdym systemem nadzoru; nie zastępuje ładu korporacyjnego."},"bk_z2_wszedzie":{"kw":["wszystkie funkcje","zewnętrzn","usług it"],"pulapka":"Rozszerzone przedsiębiorstwo obejmuje wewnętrzne i zewnętrzne usługi IT oraz procesy biznesowe, wszędzie tam, gdzie przetwarzana jest informacja."},"bk_z3_jak":{"kw":["cobit 4.1","załącznik","materiał"],"pulapka":"Źródła COBIT 5 to wytyczne ISACA (COBIT 4.1, Val IT 2.0, Risk IT, BMIS) oraz dopasowanie do ITIL, TOGAF i norm ISO; pełna lista jest w Załączniku A."},"bk_z3_nadrz":{"kw":["nadrzędn","itil","zintegrowan"],"pulapka":"COBIT 5 nie zastępuje ITIL, TOGAF ani norm ISO; jest z nimi spójny na wysokim poziomie, więc może być strukturą nadrzędną, która je integruje."},"bk_z3_p1":{"kw":["nadrzędn","spójn","standard"],"pulapka":"Spójność z innymi standardami pozwala integrować je pod COBIT 5 jako strukturą nadrzędną; COBIT ich nie zastępuje ani nie unieważnia."},"bk_z3_p2":{"kw":["techniczn","język","całe przedsiębiorstwo"],"pulapka":"COBIT 5 obejmuje całe przedsiębiorstwo i jest pisany językiem przystępnym dla osób bez wiedzy technicznej; nie jest przeznaczony tylko dla specjalistów IT."},"bk_z3_p3":{"kw":["architektur","produkt"],"pulapka":"Prosta architektura strukturyzuje materiały pomocnicze i tworzy spójny zbiór produktów; to cecha Zasady 3, a nie Zasady 4."},"bk_z3_p4":{"kw":["val it","risk it","bmis"],"pulapka":"COBIT 5 łączy wiedzę ISACA: COBIT, Val IT, Risk IT, BMIS, Board Briefing on IT Governance i ITAF; ITIL i TOGAF to standardy zewnętrzne."},"bk_z3_powody":{"kw":["zintegrowan","jednej zintegrowanej","zasada 3"],"pulapka":"Cztery powody to: spójność z innymi standardami, objęcie całego przedsiębiorstwa, prosta architektura i połączenie wiedzy ISACA; „zastępuje ITIL” nie jest powodem."},"bk_z5_3roznice":{"kw":["oddzielenie","struktur","zasada 5"],"pulapka":"Ład i Zarządzanie różnią się rodzajem działań, strukturami organizacyjnymi i celami, a nie tym, że jedno dotyczy biznesu, a drugie IT."},"bk_zach1":{"kw":["wobec ryzyka","zachowanie","ryzyk"],"pulapka":"Zachowanie wobec podejmowania ryzyka pyta, ile ryzyka organizacja może przyjąć i jakie chce podjąć; nie myl go z zachowaniem wobec negatywnych wyników."},"bk_zach2":{"kw":["przestrzegania polityk","zachowanie"],"pulapka":"Zachowanie wobec przestrzegania polityki dotyczy tego, w jakim stopniu pracownicy przyjmują politykę i jej przestrzegają; samo istnienie polityki nie oznacza właściwego zachowania."},"bk_zach3":{"kw":["negatywnych wynik","obwinia"],"pulapka":"Zachowanie wobec negatywnych wyników: czy organizacja traktuje szkodę jako okazję do nauki i usuwa przyczynę, czy tylko przypisuje winę; kultura obwiniania to symptom złej kultury."},"bk_zach_ind":{"kw":["zachowania indywidualne","kultur"],"pulapka":"Zachowania indywidualne łącznie określają kulturę organizacji; wpływają na nie czynniki zewnętrzne, relacje interpersonalne oraz osobiste cele i ambicje."},"bk_zakres_cobit":{"kw":["zakres","przedsiębiorstw"],"pulapka":"Zakresem COBIT 5 jest przedsiębiorstwo, ale metodyka może działać przy każdym sposobie postrzegania zakresu; nie ogranicza się do działu IT."},"bk_zakres_nadzoru":{"kw":["zakres","jednostk"],"pulapka":"Nadzór może dotyczyć całego przedsiębiorstwa, jednostki, środków trwałych czy wartości niematerialnych; zakres systemu nadzoru trzeba zdefiniować."},"bk_zal_a":{"kw":["inne standardy","itil","togaf","prince2"],"pulapka":"Załącznik A to lista 17 materiałów referencyjnych użytych przy tworzeniu COBIT 5; nie myl go z mapowaniem procesów na standardy z Załącznika E i Procesów umożliwiających."},"bk_zal_a_arch":{"kw":["togaf","architektur"],"pulapka":"TOGAF 9, FEA i CEAF to źródła o architekturze korporacyjnej; nie o zarządzaniu usługami IT jak ITIL ani o projektach jak PRINCE2."},"bk_zal_a_lad":{"kw":["38500","ład korporacyjny","king"],"pulapka":"Ze źródeł o ładzie ISO/IEC 38500 dotyczy Ładu IT i jest powiązana z domeną EDM; nie myl jej z ISO/IEC 15504 (ocena procesów) ani ISO/IEC 20000 (usługi IT)."},"bk_zal_a_proj":{"kw":["prince2","pmbok","zarządzania zmianą"],"pulapka":"PRINCE2 i PMBOK to źródła zarządzania projektami, MSP i APM – programami, a Kotter „Leading Change” – zmianą; Kotter nie jest metodyką prowadzenia projektów."},"bk_zal_a_usl":{"kw":["itil","iso 9001","27001"],"pulapka":"ITIL i ISO/IEC 20000 to usługi IT, ISO 9001 – jakość, BS25999 – ciągłość działania, ISO/IEC 27005 – ryzyko bezpieczeństwa informacji; łatwo je pomylić w pytaniach dopasowujących."},"bk_zarz_def":{"kw":["pbrm","uruchamian","planowanie, budowanie"],"pulapka":"Zarządzanie to Planowanie, Budowanie, Uruchamianie, Monitorowanie (PBRM) zgodnie z kierunkiem od Ładu; słowo „monitorowanie” jest w obu definicjach, więc niczego nie rozstrzyga."},"bk_zarz_kto":{"kw":["ceo","kadra zarządzając","kadra kierownicza"],"pulapka":"Za Zarządzanie odpowiada zwykle kierownictwo wykonawcze pod przywództwem CEO. Odróżnij tę rolę od organu nadzorującego (board) i jego przewodniczącego; polskie nazwy stanowisk zależą od ustroju organizacji."},"bk_zasady_kryt":{"kw":["ograniczona liczba","prosty język"],"pulapka":"Kryteria dotyczą zasad: ograniczona liczba oraz prosty i precyzyjny język; nie myl ich z cechami dobrych polityk (skuteczne, wydajne, nieinwazyjne) ani struktur ramowych."},"bk_zasady_razem":{"kw":["pięć zasad","5 zasad","zasad"],"pulapka":"Zasad jest pięć i dopiero razem dają skuteczny system Ładu i Zarządzania; nie myl ich z siedmioma aktywatorami ani z sześcioma dążeniami zarządów."},"bk_zdolnosc_usl":{"kw":["zdolności usługow","zdolność usługow","infrastruktur"],"pulapka":"Zdolność do świadczenia usług odnosi się do zasobów, takich jak aplikacje i infrastruktura, wykorzystywanych do świadczenia usług związanych z IT. Odróżnij zdolność od codziennego dostarczania i wsparcia usługi; cała kategoria Usługi, infrastruktura i aplikacje jest wyróżniona jako zasób."},"bk_zewn_dp":{"kw":["dobre praktyki","inne standardy","zewnętrzn"],"pulapka":"Zewnętrzne dobre praktyki (inne normy i struktury ramowe) mogą mieć dowolną formę i szczegółowość; COBIT jest z nimi dopasowany i podaje zestawienia, ale ich nie przepisuje."},"bk_zi1":{"kw":["fuzj","przejęci","zdarzenia wyzwalając"],"pulapka":"Fuzje, przejęcia i zbycia to zdarzenie wyzwalające (zmiana w otoczeniu firmy), a nie punkt zapalny."},"bk_zi2":{"kw":["pozycj","konkurencyj","zdarzenia wyzwalając"],"pulapka":"Zmiana pozycji rynkowej, ekonomicznej lub konkurencyjnej to zdarzenie wyzwalające, a nie czynnik kontekstu „praktyki stosowane w branży”."},"bk_zi3":{"kw":["sourcing","zdarzenia wyzwalając","zdarzenie wyzwalając"],"pulapka":"Zmiana modelu biznesowego lub uzgodnień zaopatrzenia to zdarzenie wyzwalające; problemy z istniejącym outsourcingiem to punkt zapalny."},"bk_zi4":{"kw":["nowe wymagania","regulacyjn","zdarzenia wyzwalając"],"pulapka":"Nowe wymagania regulacyjne lub zgodności to zdarzenie wyzwalające, a niespełnianie obecnych wymogów regulacyjnych to punkt zapalny."},"bk_zi5":{"kw":["paradygmat","technologi","zdarzenia wyzwalając"],"pulapka":"Istotna zmiana technologii lub przesunięcie paradygmatu to zdarzenie wyzwalające; IT blokujące innowacje to punkt zapalny."},"bk_zi6":{"kw":["ogólnofirmow","inicjatyw","zdarzenia wyzwalając"],"pulapka":"Ogólnofirmowa inicjatywa lub projekt nadzoru to zdarzenie wyzwalające; nie myl go z „powielaniem inicjatyw”, które jest punktem zapalnym."},"bk_zi7":{"kw":["nowy ceo","nowy dyrektor","zdarzenia wyzwalając"],"pulapka":"Nowy CEO, CFO czy CIO to zdarzenie wyzwalające; brak zadowolonych sponsorów biznesowych IT to punkt zapalny."},"bk_zi8":{"kw":["audyt zewnętrzn","konsultant","zdarzenia wyzwalając"],"pulapka":"Audyt zewnętrzny lub ocena konsultantów to zdarzenie wyzwalające; audyty regularnie wskazujące słabą sprawność IT to punkt zapalny."},"bk_zi9":{"kw":["nowa strategia","strategi","zdarzenia wyzwalając"],"pulapka":"Nowa strategia biznesowa lub nowy priorytet to zdarzenie wyzwalające; w kaskadzie zmiany strategii są też wyznacznikiem interesariuszy (krok 1)."},"bk_zm_opor":{"kw":["opór","oporu","ustrukturyzowan"],"pulapka":"Nie należy zakładać, że interesariusze chętnie przyjmą zmianę; brak świadomości i opór uwzględnia się w podejściu ustrukturyzowanym i proaktywnym."},"bk_zm_plan_kom":{"kw":["plan komunikacji","komunikacj"],"pulapka":"Plan komunikacji określa treść, sposób i odpowiedzialność za przekaz w kolejnych fazach programu (Framework EN s. 37: by whom). FW-PL s. 37 mówi o adresatach; praktyczny plan powinien określać zarówno nadawcę, jak i odbiorcę."},"bk_zm_trwala":{"kw":["trwał","egzekw","zaangażowani"],"pulapka":"Trwałą poprawę daje zaangażowanie interesariuszy (zaufanie, liderzy, komunikacja) lub, gdy trzeba, egzekwowanie zgodności (administrowanie, monitorowanie, egzekwowanie)."},"bk_zm_wlasciwa":{"kw":["umożliwienie zmian","zachowani","zmian"],"pulapka":"Wdrożenie wymaga właściwej zmiany wprowadzonej we właściwy sposób; najczęściej zaniedbuje się aspekt ludzki, zachowanie i kulturę, a nie technikę."},"bk_zwiazane_it":{"kw":["związane z it","powiązan","technologi"],"pulapka":"„Związane z IT” oznacza informację i powiązaną technologię, a nie wyłącznie dział IT czy jego cele."},"cakt":{"kw":["cele aktywator","krok 4"],"pulapka":"Cele aktywatorów (krok 4 kaskady) dotyczą wszystkich siedmiu aktywatorów, nie tylko procesów: podręcznik mówi, że same procesy nie wystarczą."},"ce1":{"kw":["wartość inwestycji","cel organizacji","rysunek 5"],"pulapka":"Cel 1 (Finanse) ma P tylko przy realizacji korzyści i S przy zasobach; nie myl go z celem IT 05 „Uzyskanie korzyści z inwestycji i portfela usług związanych z IT”."},"ce10":{"kw":["optymalizacja kosztów świadczenia usług","cel 10"],"pulapka":"Cel 10 leży w wymiarze Klient, nie Obszar wewnętrzny; ma P przy korzyściach i zasobach, a nie przy ryzyku; koszty procesów biznesowych to osobny cel 12."},"ce11":{"kw":["funkcjonalno","procesów biznesowych","cel organizacji"],"pulapka":"Cel 11 (Obszar wewnętrzny) dotyczy funkcjonalności procesów biznesowych (P przy korzyściach i zasobach); nie myl z celem 12 (ich koszty) ani z celem IT 12 (integracja aplikacji z procesami)."},"ce12":{"kw":["procesów biznesowych","optymalizacja kosztów"],"pulapka":"Cel 12 to koszty procesów biznesowych (Obszar wewnętrzny), a cel 10 to koszty świadczenia usług (Klient); oba mają P przy korzyściach i zasobach."},"ce13":{"kw":["programami biznesowymi","zmiany biznesowe"],"pulapka":"Cel 13 (Obszar wewnętrzny) to programy zmian biznesowych (P przy korzyściach i ryzyku, S przy zasobach); cel IT 13 dotyczy realizacji programów w terminie i budżecie."},"ce14":{"kw":["obszar wewnętrzny","cel organizacji","wymiar bsc"],"pulapka":"Cel 14 leży w Obszarze wewnętrznym, nie w Szkoleniu i rozwoju, choć mówi o pracownikach; ma P przy korzyściach i zasobach, a wykwalifikowany personel to cel 16."},"ce15":{"kw":["zgodność z politykami wewnętrznymi","cel 15"],"pulapka":"Cel 15 to zgodność z politykami wewnętrznymi (Obszar wewnętrzny, P tylko przy ryzyku); zgodność z prawem to cel 4 (Finanse), a cel IT 15 to zgodność IT z politykami."},"ce16":{"kw":["wykwalifikowany i zmotywowany personel","zmotywowany personel"],"pulapka":"Cel 16 (Szkolenie i rozwój) ma S przy korzyściach i P przy ryzyku i zasobach; nie myl z celem IT 16 „Kompetentny i zmotywowany personel działu biznesowego i działu IT”."},"ce17":{"kw":["kultura innowacji","innowacji produktów"],"pulapka":"Cel 17 (Szkolenie i rozwój) ma P tylko przy realizacji korzyści; nie myl z celem IT 17 „Wiedza, kompetencje oraz inicjatywy w zakresie innowacji biznesowych”."},"ce2":{"kw":["portfel konkurencyjnych","cel organizacji"],"pulapka":"Cel 2 leży w wymiarze Finanse, nie Klient, choć mówi o produktach; ma P przy korzyściach i ryzyku oraz S przy zasobach."},"ce3":{"kw":["zarządzane ryzyko","ochrona zasobów"],"pulapka":"Cel 3 (Finanse) ma P przy optymalizacji ryzyka i S przy zasobach; nie myl go z celem IT 04 „Zarządzanie ryzykiem biznesowym związanym z IT”."},"ce4":{"kw":["zgodność z przepisami prawa","cel organizacji"],"pulapka":"Cel 4 to zgodność z przepisami zewnętrznymi (Finanse, P tylko przy ryzyku); zgodność z politykami wewnętrznymi to cel 15 (Obszar wewnętrzny), a IT 02 to cel związany z IT."},"ce5":{"kw":["przejrzystość finansowa","cel organizacji"],"pulapka":"Cel 5 (Finanse) ma P przy korzyściach i S przy ryzyku i zasobach; nie myl go z celem IT 06 (przejrzystość kosztów, korzyści i ryzyka IT) ani z procesem EDM05."},"ce6":{"kw":["zorientowanych na klienta","cel organizacji"],"pulapka":"Cel 6 (Klient) ma P przy korzyściach i S przy zasobach; to cel organizacji, a „dostarczanie usług IT zgodnie z wymogami biznesowymi” to cel IT 07."},"ce7":{"kw":["ciągłość i dostępność usług biznesowych","cel 7"],"pulapka":"Cel 7 (Klient) ma P tylko przy optymalizacji ryzyka, nie przy korzyściach; podstawowo wspierają go cele IT 04, 10 i 14 (Rysunek 22)."},"ce8":{"kw":["zwinność","otoczenia biznesowego","cel organizacji"],"pulapka":"Cel 8 to cel organizacji w wymiarze Klient (P przy korzyściach, S przy zasobach); „Zwinność IT” to osobny cel IT 09."},"ce9":{"kw":["świadome podejmowanie decyzji","decyzji strategicznych","p p p"],"pulapka":"Cel 9 to jedyny cel z układem P P P (korzyści, ryzyko, zasoby); leży w wymiarze Klient, nie Finanse, a cel IT 14 to dostępność wiarygodnych informacji."},"ci1":{"kw":["zgodność it z biznesowymi","przykładzie 1","it bsc"],"pulapka":"Cel IT 01 leży w wymiarze Finanse IT BSC; w Przykładzie 1 (zadowolenie klientów) to jeden z czterech celów wybranych jako priorytet: 01, 04, 07, 09."},"ci10":{"kw":["bezpieczeństwo informacji","infrastruktury"],"pulapka":"Cel 10 (bezpieczeństwo informacji, infrastruktury i aplikacji) leży w Obszarze wewnętrznym; nie myl go z kategorią celów aktywatora Dostęp i Bezpieczeństwo."},"ci11":{"kw":["aktywów","optymalizacja zasobów"],"pulapka":"Cel 11 (optymalizacja aktywów, zasobów i potencjału IT) leży w Obszarze wewnętrznym; nie myl go z Optymalizacją zasobów, składnikiem Celu Ładu z Rysunku 8."},"ci12":{"kw":["integracj","procesów biznesowych"],"pulapka":"Cel 12 to integracja aplikacji i technologii z procesami biznesowymi (Obszar wewnętrzny); nie myl go z celem organizacji 11 „Optymalizacja funkcjonalności procesów biznesowych”."},"ci13":{"kw":["programów","budżet"],"pulapka":"Cel 13 łączy terminowość, budżet i jakość programów (Obszar wewnętrzny); nie myl go z celem organizacji 13 „Zarządzanie programami biznesowymi — zmiany biznesowe”."},"ci14":{"kw":["przydatnych informacji","proces decyzyjny","decyzj"],"pulapka":"Cel 14 (wiarygodne i przydatne informacje do decyzji) leży w Obszarze wewnętrznym, nie w wymiarze Klient; nie myl go z celem organizacji 9 o decyzjach strategicznych."},"ci15":{"kw":["politykami wewnętrznymi","zgodność it z politykami"],"pulapka":"Cel IT 15 (polityki wewnętrzne) leży w Obszarze wewnętrznym, a cel 02 (przepisy zewnętrzne) w Finansach; cel organizacji 15 ma prawie tę samą nazwę."},"ci16":{"kw":["zmotywowany personel","szkolenie i rozwój"],"pulapka":"Cel 16 obejmuje personel działu biznesowego i działu IT, nie tylko IT; leży w wymiarze Szkolenie i rozwój, obok celu organizacji 16."},"ci17":{"kw":["innowacj","szkolenie i rozwój"],"pulapka":"Cel 17 (wiedza i inicjatywy w zakresie innowacji biznesowych) leży w Szkoleniu i rozwoju; nie myl go z celem organizacji 17 „Kultura innowacji produktów i biznesu”."},"ci2":{"kw":["przepisami prawa","zgodność z przepisami"],"pulapka":"Cel 02 (przepisy zewnętrzne) jest w wymiarze Finanse, a cel 15 (polityki wewnętrzne) w Obszarze wewnętrznym; nie myl go też z celem organizacji 4."},"ci3":{"kw":["kadry zarządzającej","it bsc"],"pulapka":"Cel 03 (zaangażowanie kadry zarządzającej w decyzje o IT) leży w wymiarze Finanse IT BSC; kompetentny i zmotywowany personel to osobny cel 16 w Szkoleniu i rozwoju."},"ci4":{"kw":["zarządzanie ryzykiem biznesowym"],"pulapka":"Numer celu IT nie wskazuje procesu o tym samym numerze: cel 04 to nie APO04; ryzykiem zajmują się m.in. EDM03 i APO12."},"ci5":{"kw":["korzyści z inwestycji","portfel"],"pulapka":"Cel IT 05 (korzyści z inwestycji i portfela usług IT) leży w Finansach; nie myl go z celem organizacji 1 „Wartość inwestycji biznesowych dla interesariuszy”."},"ci6":{"kw":["przejrzystość kosztów","przejrzystość"],"pulapka":"Cel 06 łączy przejrzystość kosztów, korzyści i ryzyka IT (Finanse); nie myl go z celem organizacji 5 „Przejrzystość finansowa”."},"ci7":{"kw":["dostarczanie usług it","wymogami biznesowymi","przykładzie 1"],"pulapka":"Cel 07 to jeden z dwóch celów IT w wymiarze Klient (obok 08); w Przykładzie 1 (zadowolenie klientów) jest wśród czterech celów priorytetowych."},"ci8":{"kw":["adekwatne wykorzystanie","it bsc"],"pulapka":"Cel 08 (adekwatne wykorzystanie aplikacji, informacji i technologii) leży w wymiarze Klient, nie w Obszarze wewnętrznym; nie myl go z celem 14 o informacjach do decyzji."},"ci9":{"kw":["zwinność it","zwinność"],"pulapka":"Cel IT 09 „Zwinność IT” leży w Obszarze wewnętrznym; nie myl go z celem organizacji 8 (zwinność wobec otoczenia) ani z pryncypium architektury „zwinność”."},"cit":{"kw":["cele związane z it","cele związane z informatyką","celu związanego z informatyką"],"pulapka":"Numer celu związanego z IT nie wskazuje procesu o tym samym numerze (cel IT 04 to nie APO04); cele IT wynikają z celów organizacji w kroku 3 kaskady."},"corg":{"kw":["cele organizacji","zrównoważon","17 celów"],"pulapka":"17 typowych celów organizacji ułożono według wymiarów zrównoważonej karty wyników (BSC); „cele organizacji” (egzamin) i „cele przedsiębiorstwa” (podręcznik) to ten sam poziom kaskady."},"dapo":{"kw":["apo","dostosuj, planuj i organizuj","apo12"],"pulapka":"Egzamin: „Dostosuj, Planuj i Organizuj” (podręcznik: Dopasowanie, planowanie i organizacja); APO ma 13 procesów, m.in. APO12 Ryzyko i APO13 Bezpieczeństwo, i należy do Zarządzania."},"dbai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI ma 10 procesów, w tym zmiany BAI06, wiedzę BAI08, aktywa BAI09 oraz zarządzanie dostępnością i pojemnością BAI04. Codzienne działanie i wsparcie usług należą także do DSS; samo słowo dostępność nie przesądza o domenie."},"ddss":{"kw":["dss","dostarczaj, obsługuj i wspieraj","dss02"],"pulapka":"DSS ma 6 procesów dostarczania i wsparcia, np. DSS02 zgłoszenia i incydenty, DSS03 problemy, DSS05 usługi bezpieczeństwa. To Wykonuj w PBRM. MEA odpowiada za monitorowanie i ocenę wydajności, kontroli i zgodności; bieżące monitorowanie może być także działaniem innych procesów."},"decyz":{"kw":["uzasadnienie biznesowe","celem samym w sobie","kluczowy czynnik sukcesu"],"pulapka":"Właściwe środowisko to widoczne wsparcie kierownictwa, uzasadnienie biznesowe, zasoby i przydzielone role; aktywatory mają rozwiązywać realne problemy biznesu, nie być celem samym w sobie."},"dmea":{"kw":["mea","monitoruj, oszacuj i oceń","mea01"],"pulapka":"MEA ma 3 procesy i należy do Zarządzania („Monitoruj” w PBRM), nie do Ładu; EDM monitoruje kierunek, a MEA mierzy sprawność, kontrolę wewnętrzną i zgodność."},"docel":{"kw":["docelow","faza 3","dokąd chcemy"],"pulapka":"Poziom docelowy organizacja wybiera z rachunku kosztów i korzyści i bardzo rzadko jest on najwyższy; zdefiniowanie stanu docelowego to faza 3 („Do czego dążymy?”), nie faza 2."},"drv":{"kw":["wyznacznik","kaskad","potrzeby interesariuszy"],"pulapka":"Wyznaczniki (drivers) w kaskadzie celów to krok 1: wpływają na potrzeby interesariuszy; nie myl ich z wyznacznikami fazy 1 cyklu wdrożenia ani z celami organizacji."},"edm1":{"kw":["edm01"],"pulapka":"EDM01 ustala zasady decydowania o IT (ramy Ładu) i nie jest składnikiem celu Ładu; organizowanie ról, polityk i procesów działu IT to APO01 (Zarządzanie)."},"edm2":{"kw":["edm02","realizacja korzyści"],"pulapka":"EDM02 to realizacja korzyści na poziomie Ładu: rozlicza wartość inwestycji; zarządzanie portfelem to APO05, a prowadzenie projektu to BAI01."},"edm3":{"kw":["edm03","apetyt na ryzyko"],"pulapka":"EDM03 ustala apetyt na ryzyko i pilnuje granic (Ład); rejestr, analiza i codzienne zarządzanie ryzykiem to APO12 (Zarządzanie)."},"edm4":{"kw":["edm04","zasob"],"pulapka":"EDM04 to decyzja Ładu o wszystkich zasobach (ludzie, pieniądze, aktywa); ewidencja laptopów to BAI09, a braki w zespole kierownika to codzienne zarządzanie."},"edm5":{"kw":["edm05","przejrzystości","transparentności"],"pulapka":"EDM05 to przejrzystość wobec interesariuszy na poziomie Ładu, a nie składnik celu Ładu; bieżące monitorowanie i raporty sprawności to MEA01."},"il10_baza_wiedzy":{"kw":["baza wiedzy","bazy wiedzy"],"pulapka":"Rysunek 10 przedstawia w bazie wiedzy aktualne wytyczne i strukturę dla przyszłych treści. Nie ogranicza jej do opisów 37 procesów; rodzina produktów powstaje na podstawie tej bazy."},"il10_bw_aktualne":{"kw":["aktualne wytyczne","baza wiedzy"],"pulapka":"Aktualne wytyczne i treści to jeden z dwóch punktów bazy wiedzy (drugi: struktura dla przyszłych treści); nie myl bazy wiedzy z rodziną produktów, która z niej powstaje."},"il10_bw_struktura":{"kw":["przyszłych treści","baza wiedzy"],"pulapka":"Struktura dla przyszłych treści oznacza, że baza wiedzy jest otwarta na rozbudowę; to drugi punkt bazy wiedzy, a nie osobny produkt ani filtr."},"il10_czynniki_c5":{"kw":["filtr","aktywatory cobit 5"],"pulapka":"Na Rysunku 10 aktywatory (czynniki umożliwiające) pełnią rolę filtra zawartości bazy wiedzy; filtrem nie są pięć zasad, BSC ani wejścia (ISACA, inne standardy)."},"il10_filtr":{"kw":["filtr","filtra zawartości"],"pulapka":"Filtrem zawartości na Rysunku 10 są aktywatory COBIT 5, nie pięć zasad; z przefiltrowanej bazy wiedzy powstaje rodzina produktów."},"il10_inne_standardy":{"kw":["itil","togaf","nadrzędn"],"pulapka":"COBIT 5 jest spójny z ITIL, TOGAF i normami ISO i może być nadrzędną strukturą ramową, ale ich nie zastępuje i nie musi być z nimi stosowany."},"il10_nowe_isaca":{"kw":["nowe materiały","wejści"],"pulapka":"Nowe materiały ISACA uzupełniają obszary wymagające opracowania i aktualizacji; to drugie z trzech wejść do bazy wiedzy, a nie produkt rodziny COBIT 5."},"il10_obecne_isaca":{"kw":["val it","risk it","bmis"],"pulapka":"COBIT 5 łączy wcześniejsze wytyczne ISACA: COBIT 4.1, Val IT, Risk IT, BMIS (oraz m.in. ITAF); ITIL, TOGAF i normy ISO nie są wytycznymi ISACA."},"il10_r_cobit5":{"kw":["framework","rodzina produktów"],"pulapka":"Sam COBIT 5 (framework) należy do rodziny produktów, ale nie jest ani przewodnikiem o aktywatorach, ani specjalistycznym; to metodyka główna."},"il10_r_przew_czynniki":{"kw":["procesy umożliwiające","informacje umożliwiające","aktywatorach"],"pulapka":"Przewodniki o aktywatorach to np. „Procesy umożliwiające” i „Informacje umożliwiające”; „Bezpieczeństwo informacji” mimo słowa „informacja” jest przewodnikiem specjalistycznym."},"il10_r_przew_spec":{"kw":["specjalistyczn","cobit 5 – ryzyko"],"pulapka":"Przewodniki specjalistyczne to Wdrożenie, Bezpieczeństwo informacji, Audyt i Ryzyko; „Procesy umożliwiające” do nich nie należą (to przewodnik o aktywatorach)."},"il10_r_srodowisko":{"kw":["środowisko sieciowe","współpracy"],"pulapka":"Środowisko sieciowe oparte na współpracy jest elementem rodziny produktów (wyjście), a nie filtrem ani wejściem do bazy wiedzy."},"il10_rodzina":{"kw":["rodzina produktów","rodziny produktów"],"pulapka":"Rodzina produktów to wyjście z bazy wiedzy: COBIT 5, przewodniki o aktywatorach, przewodniki specjalistyczne i środowisko współpracy; ITIL do niej nie należy."},"il10_zrodla":{"kw":["wejści","baza wiedzy","rysunek 10"],"pulapka":"Na Rysunku 10 trzy źródła (obecne wytyczne ISACA, nowe materiały ISACA, inne standardy) to wejścia do bazy wiedzy, a nie filtr ani rodzina produktów."},"il14_informacje":{"kw":["wejścia i wyjścia","dane wejściowe","rysunek 14"],"pulapka":"Informacje łączą Ład i Zarządzanie jako wejścia i wyniki praktyk procesów; dostarczanie organowi Ładu informacji przez systemy to interakcja przez Usługi, infrastrukturę i aplikacje."},"il14_kultura":{"kw":["odgórnie","przykład","kultura, etyka"],"pulapka":"Zachowanie ustala się odgórnie, przez przykład przywództwa; odpowiedzi o kształtowaniu kultury oddolnie albo głosowaniem pracowników są błędne."},"il14_ludzie":{"kw":["ludzie, umiejętności","umiejętności","rysunek 14"],"pulapka":"Kluczowa umiejętność członków organu Ładu i osób zarządzających to znajomość charakteru obu ról i dzielących je różnic, a nie identyczne kompetencje."},"il14_procesy":{"kw":["raci","rysunek 14","edm"],"pulapka":"Interakcja przez Procesy to rozdział procesów Ładu i Zarządzania plus tabele RACI; decyzje o portfelu i apetycie na ryzyko to interakcja przez Struktury."},"il14_struktury":{"kw":["apetyt na ryzyko","portfel","struktury organizacyjne"],"pulapka":"Struktury Ładu decydują np. o portfelu inwestycji i apetycie na ryzyko, co wpływa na decyzje wdrożeniowe; instytucjonalizacja decyzji Ładu to rola Zasad i polityk."},"il14_uslugi":{"kw":["usługi, infrastruktura","infrastruktur","rysunek 14"],"pulapka":"Usługi, infrastruktura i aplikacje dostarczają organowi Ładu informacji do oceny, kierowania i monitorowania; wymiana wejść i wyników między procesami to aktywator Informacje."},"il14_zasady":{"kw":["instytucjonaliz","polityk"],"pulapka":"Zasady, polityki i struktury ramowe instytucjonalizują decyzje Ładu; kusi odpowiedź „Struktury organizacyjne”, bo słowo „struktury” występuje w obu nazwach."},"il1_audyt":{"kw":["audyt","przewodnik specjalistyczny"],"pulapka":"COBIT 5 — Audyt (EN: Assurance) to przewodnik specjalistyczny; audytor szuka go wśród przewodników specjalistycznych, nie wśród przewodników o aktywatorach."},"il1_bezp_inf":{"kw":["bezpieczeństwo informacji","przewodnik specjalistyczny"],"pulapka":"COBIT 5 — Bezpieczeństwo informacji to przewodnik specjalistyczny; nie myl go z przewodnikiem o aktywatorze Informacje umożliwiające."},"il1_cobit5":{"kw":["rodzina produktów","rodziny produktów","struktura ramowa"],"pulapka":"COBIT 5 (struktura ramowa) to centrum rodziny produktów: pięć zasad i aktywatory; szczegóły 37 procesów są w przewodniku Procesy umożliwiające, nie w samej strukturze ramowej."},"il1_informacje_umozl":{"kw":["informacje umożliwiające","rodziny produktów"],"pulapka":"„Informacje umożliwiające” to przewodnik o aktywatorze Informacja, a nie specjalistyczny przewodnik Bezpieczeństwo informacji."},"il1_inne_przew_czynniki":{"kw":["przewodników o aktywatorach","rodziny produktów"],"pulapka":"Pozostałe przewodniki o aktywatorach należą do grupy przewodników o aktywatorach, nie do specjalistycznych; podręcznik odsyła po nie na www.isaca.org/cobit."},"il1_inne_spec":{"kw":["przewodników specjalistycznych","rodziny produktów"],"pulapka":"Lista przewodników specjalistycznych jest otwarta: obok czterech wymienionych są inne, wskazane na www.isaca.org/cobit."},"il1_procesy_umozl":{"kw":["procesy umożliwiające","37 procesów"],"pulapka":"„Procesy umożliwiające” to przewodnik o aktywatorze, nie specjalistyczny; zawiera szczegóły wszystkich 37 procesów, m.in. RACI, wejścia i wyjścia praktyk."},"il1_przew_czynniki":{"kw":["przewodników o aktywatorach","procesy umożliwiające","rodziny produktów"],"pulapka":"Przewodniki o aktywatorach to np. Procesy umożliwiające i Informacje umożliwiające; Wdrożenie, Audyt, Ryzyko i Bezpieczeństwo informacji to przewodniki specjalistyczne."},"il1_przew_spec":{"kw":["przewodnik specjalistyczny","przewodników specjalistycznych","przewodniki specjalistyczne"],"pulapka":"Przewodniki specjalistyczne (EN: professional guides) to Wdrożenie, Bezpieczeństwo informacji, Audyt, Ryzyko i inne; Procesy umożliwiające do nich nie należą."},"il1_ryzyko":{"kw":["COBIT 5 Ryzyko","Risk IT"],"pulapka":"COBIT 5 — Ryzyko jest przewodnikiem specjalistycznym. Risk IT to wcześniejsza struktura ramowa ISACA uwzględniona w bazie wiedzy COBIT 5. Taking Governance Forward dotyczy podejścia do Ładu, nie nazwy tego przewodnika."},"il1_srodowisko":{"kw":["środowisko sieciowe","rodziny produktów"],"pulapka":"Środowisko sieciowe oparte na współpracy to osobny element rodziny produktów, ani przewodnik o aktywatorach, ani specjalistyczny; jest wyjściem z bazy wiedzy, nie jej wejściem."},"il1_wdrozenie":{"kw":["cobit 5 – wdrożenie","cobit 5 — wdrożenie","cyklu wdrożenia"],"pulapka":"COBIT 5 — Wdrożenie to przewodnik specjalistyczny, nie normatywny i nie kompletne rozwiązanie, lecz zbiór wskazówek; opisuje cykl wdrożenia w siedmiu fazach."},"il20_k_jedn":{"kw":["dojrzałości","powtarzalne","ad hoc"],"pulapka":"Poziomy 0–2 to wiedza indywidualna: poziom 2 COBIT 4.1 zależy od wiedzy poszczególnych osób, stąd ryzyko błędów; dopiero od poziomu 3 wiedza jest korporacyjna."},"il20_k_przeds":{"kw":["dojrzałości","zdefiniowany proces","ustanowiony"],"pulapka":"W kolumnie „Kontekst” Rysunku 20 poziomy 3–5 to punkt widzenia przedsiębiorstwa (wiedza korporacyjna), a 0–2 – jednostki; granica przebiega między poziomem 2 a 3."},"il20_m0":{"kw":["nieistniejące","niekompletny"],"pulapka":"„Nieistniejące”, czyli całkowity brak rozpoznawalnych procesów, to poziom 0 COBIT 4.1; poziom 0 COBIT 5 („niekompletny”) obejmuje też proces, który istnieje, ale nie osiąga celu."},"il20_m1":{"kw":["ad hoc","dojrzałości"],"pulapka":"Poziom 1 COBIT 4.1 (Wstępne/Ad hoc) może w COBIT 5 dać poziom 0, jeśli proces nie osiąga swoich wyników."},"il20_m2":{"kw":["powtarzalne","dojrzałości","cobit 4.1"],"pulapka":"Poziom 2 COBIT 4.1 („powtarzalne lecz intuicyjne”) opiera się na wiedzy osób; ten sam proces w COBIT 5 dostanie zwykle niższy wynik."},"il20_m3":{"kw":["zdefiniowany proces","dojrzałości"],"pulapka":"W COBIT 4.1 poziom 3 to procedury udokumentowane i przekazane szkoleniem, ale odstępstw raczej się nie wykrywa; 3 w COBIT 4.1 nie równa się poziomowi 3 w COBIT 5."},"il20_m4":{"kw":["model dojrzałości","dojrzałości","pozorne podobieństw"],"pulapka":"„Zarządzane i mierzalne” to poziom 4 COBIT 4.1, a nie poziom 2 COBIT 5 („zarządzany”); wspólne słowo to tylko pozorne podobieństwo skal."},"il20_m5":{"kw":["zoptymalizowane","dojrzałości","cobit 4.1"],"pulapka":"„Zoptymalizowane” to poziom 5 dojrzałości COBIT 4.1; poziom 5 zdolności COBIT 5 to „proces zoptymalizowany” (egzamin) lub „optymalizujący” (podręcznik). Definicje są inne, ocen nie przenosi się wprost."},"il20_p0":{"kw":["niekompletny","poziom 0"],"pulapka":"Poziom 0 COBIT 5 to proces niewdrożony lub nieosiągający celu; „problemu nawet nie dostrzeżono” to opis poziomu 0 COBIT 4.1 (Nieistniejące)."},"il20_p1":{"kw":["wykonywany","pa 1.1"],"pulapka":"Poziom 1 COBIT 5 wymaga, by proces osiągał swój cel; działanie doraźne bez efektu daje poziom 0."},"il20_p1_uwaga":{"kw":["dojrzałości","niższe","poziom 0"],"pulapka":"Wyniki w COBIT 5 są zasadniczo niższe niż w COBIT 4.1: proces z 1 w modelu dojrzałości może dostać 0, a nie odwrotnie."},"il20_p2":{"kw":["zarządzany","pa 2.1"],"pulapka":"Poziom 2 COBIT 5 („zarządzany”) to planowanie, monitorowanie, dostosowanie i kontrola produktów działań; nie myl go z poziomem 2 COBIT 4.1 („powtarzalne lecz intuicyjne”)."},"il20_p3":{"kw":["ustanowiony","pa 3.1"],"pulapka":"Poziom 3 COBIT 5 („ustanowiony”) to proces zarządzany, wdrożony jako zdefiniowany; „zdefiniowany proces” to nazwa poziomu 3 COBIT 4.1."},"il20_p4":{"kw":["przewidywalny","pa 4.1"],"pulapka":"Poziom 4 COBIT 5 („przewidywalny”) to proces ustanowiony, działający w zdefiniowanych granicach; „Zarządzane i mierzalne” z COBIT 4.1 to inna skala."},"il20_p5":{"kw":["optymalizujący","pa 5.1","zoptymalizowany"],"pulapka":"Poziom 5 COBIT 5 to proces przewidywalny, stale doskonalony pod obecne i przyszłe cele biznesowe; jego atrybuty to PA 5.1 Innowacja i PA 5.2 Optymalizacja."},"il21_a_cele":{"kw":["ustalanie celu","atrybutów dojrzałości","pa 4.1"],"pulapka":"Ustalanie celów i pomiar to atrybut dojrzałości COBIT 4.1; nie myl go z PA 4.1 Miara procesu ani z wymiarem Cele aktywatora."},"il21_a_narzedzia":{"kw":["narzędzia i automatyzacja","atrybutów dojrzałości"],"pulapka":"Narzędzia i automatyzacja to atrybut dojrzałości COBIT 4.1 (jeden z sześciu); w COBIT 5 nie ma atrybutu procesu o tej nazwie."},"il21_a_odpowiedzialnosc":{"kw":["atrybutów dojrzałości","model dojrzałości"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie macierz RACI z opisu procesu COBIT 5; ocena w COBIT 5 nie korzysta z atrybutów dojrzałości."},"il21_a_polityki":{"kw":["pewnym stopniu","atrybutów dojrzałości"],"pulapka":"Atrybuty COBIT 4.1 tylko „w pewnym stopniu pokrywają się” z atrybutami COBIT 5: starą ocenę można wykorzystać, ale nie przepisuje się jej jeden do jednego."},"il21_a_swiadomosc":{"kw":["świadomość i komunikowanie","atrybutów dojrzałości"],"pulapka":"To jeden z sześciu atrybutów dojrzałości COBIT 4.1, nie atrybut procesu COBIT 5; COBIT 5 ma dziewięć atrybutów procesu."},"il21_a_umiejetnosci":{"kw":["atrybutów dojrzałości","cobit 4.1"],"pulapka":"Umiejętności i szczegółowa wiedza to atrybut dojrzałości COBIT 4.1; nie myl go z aktywatorem COBIT 5 Ludzie, Umiejętności i Kompetencje."},"il21_pa11":{"kw":["pa 1.1","wykonanie procesu","poziom 1"],"pulapka":"Egzamin: PA 1.1 „Wykonanie procesu” (podręcznik: sprawność procesu); jedyny atrybut poziomu 1, oceniany przez praktyki bazowe i produkty pracy z modelu referencyjnego."},"il21_pa21":{"kw":["pa 2.1","zarządzanie wydajnością"],"pulapka":"Egzamin: PA 2.1 „Zarządzanie wydajnością” (podręcznik: zarządzanie sprawnością); dotyczy planowania i monitorowania wykonania, a nie produktów pracy (PA 2.2)."},"il21_pa22":{"kw":["pa 2.2","produktami pracy"],"pulapka":"Egzamin: PA 2.2 „Zarządzanie produktami pracy” (podręcznik: produktami działań); dotyczy wyników procesu, a nie standardowej definicji procesu (PA 3.1)."},"il21_pa31":{"kw":["pa 3.1","definicja procesu"],"pulapka":"Egzamin: PA 3.1 „Definicja procesu”: udokumentowany standardowy wzorzec; faktyczne stosowanie tego wzorca ocenia dopiero PA 3.2."},"il21_pa32":{"kw":["pa 3.2","wdrożenie procesu"],"pulapka":"Egzamin: PA 3.2 „Wdrożenie procesu”: chodzi o stosowanie standardowego procesu z rolami, kompetencjami i zasobami, a nie o 7 faz wdrażania COBIT 5."},"il21_pa41":{"kw":["pa 4.1","miara procesu"],"pulapka":"Egzamin: PA 4.1 „Miara procesu” (podręcznik: pomiar procesu); pomiar to cecha poziomu 4, więc opis procesu w modelu referencyjnym go nie zawiera."},"il21_pa42":{"kw":["pa 4.2","kontrola procesu"],"pulapka":"Egzamin: PA 4.2 „Kontrola procesu”: utrzymanie wykonania w limitach daje przewidywalne wyniki (poziom 4); to nie system kontroli wewnętrznej z domeny MEA."},"il21_pa51":{"kw":["pa 5.1","innowacja procesu"],"pulapka":"Egzamin: PA 5.1 „Innowacja procesu” (il. 19: innowacje procesowe); zmiany wynikają z analizy przyczyn zmienności, a ich wdrożenie ocenia PA 5.2."},"il21_pa52":{"kw":["pa 5.2","optymalizacja procesu","poziom 5"],"pulapka":"PA 5.2 „Optymalizacja procesu” to atrybut poziomu 5. Poziom 5 na egzaminie: „proces zoptymalizowany” (podręcznik: „optymalizujący”). Nie myl go z poziomem 5 dojrzałości COBIT 4.1 („Zoptymalizowany”), który ma inną treść."},"il26_c5_dokladnosc":{"kw":["dokładność","jakość wewnętrzna"],"pulapka":"Dane sprzed tygodnia mogą być dokładne, a mimo to nieaktualne; wtedy zawodzi jakość kontekstowa (aktualność), a nie dokładność z jakości wewnętrznej."},"il26_c5_dostepnosc":{"kw":["dostępność","terminowość"],"pulapka":"Dostępność (s. 82: dostępność/terminowość) należy do kategorii Dostęp i Bezpieczeństwo; aktualność, czyli czy dane są dość świeże do zadania, to jakość kontekstowa."},"il26_c5_interpretacja":{"kw":["możliwość interpretacji","interpretacj","jednostek"],"pulapka":"Kwoty raz w złotych, raz w tysiącach bez opisu jednostek to brak możliwości interpretacji, a nie błąd dokładności, bo same liczby mogą być poprawne."},"il26_c5_istotnosc":{"kw":["istotność","jakość kontekstowa"],"pulapka":"Istotność, czyli przydatność do zadania, to jakość kontekstowa, nie wewnętrzna; w Rysunku 26 odpowiada skuteczności z COBIT 4.1."},"il26_c5_jasnosc":{"kw":["jasność","jakość kontekstowa","zrozumiał"],"pulapka":"Jasność przekazu (informacja łatwa do zrozumienia) to jakość kontekstowa; nie myl jej z możliwością interpretacji, która dotyczy języka, symboli, jednostek i definicji."},"il26_c5_kompletnosc":{"kw":["kompletność","jakość kontekstowa"],"pulapka":"Kompletność to jakość kontekstowa, nie wewnętrzna, bo zależy od zadania; razem z dokładnością odpowiada integralności z COBIT 4.1."},"il26_c5_latwosc":{"kw":["łatwość","jakość kontekstowa"],"pulapka":"Łatwość eksploatacji (s. 82: łatwość posługiwania się) to jakość kontekstowa, choć w Rysunku 26 jest odpowiednikiem wydajności z COBIT 4.1."},"il26_c5_obiektywnosc":{"kw":["obiektywność","jakość wewnętrzna"],"pulapka":"Obiektywność należy do jakości wewnętrznej (podręcznik: rzeczywistej), choć w Rysunku 26 jest odpowiednikiem dwóch kryteriów COBIT 4.1: skuteczności i wiarygodności."},"il26_c5_ograniczony":{"kw":["ograniczony dostęp","poufność"],"pulapka":"Ograniczony dostęp (tylko dla upoważnionych) to kategoria Dostęp i Bezpieczeństwo i odpowiednik poufności z COBIT 4.1; „dostępne, gdy potrzebne” to inny cel: dostępność."},"il26_c5_reputacja":{"kw":["reputacj","jakość wewnętrzna"],"pulapka":"Reputacja brzmi jak opinia otoczenia, ale należy do jakości wewnętrznej (rzeczywistej), razem z dokładnością, obiektywnością i wiarygodnością."},"il26_c5_wiarygodnosc":{"kw":["wiarygodność","jakość wewnętrzna"],"pulapka":"Wiarygodność to cel jakości wewnętrznej; „wewnętrzna” znaczy „sama w sobie”, a nie „powstała w organizacji”. W Rysunku 26 łączy się z wydajnością i wiarygodnością COBIT 4.1."},"il26_c5_wlasciwa_ilosc":{"kw":["odpowiednia ilość","jakość kontekstowa"],"pulapka":"Właściwa ilość informacji to jakość kontekstowa i odpowiednik skuteczności z COBIT 4.1; na s. 82 ten sam cel nazywa się „odpowiednia ilość informacji”."},"il26_kr_dostepnosc":{"kw":["dostępność","dostęp i bezpieczeństwo"],"pulapka":"Dostępność z COBIT 4.1 to jeden cel kategorii Dostęp i Bezpieczeństwo (podręcznik: dostępność/terminowość); aktualność to inny cel, z jakości kontekstowej."},"il26_kr_integralnosc":{"kw":["integralność","kompletność","dokładność"],"pulapka":"Integralność z COBIT 4.1 odpowiada dwóm celom: kompletności (jakość kontekstowa) i dokładności (jakość wewnętrzna); odpowiedź z samą dokładnością to tylko połowa prawdy."},"il26_kr_poufnosc":{"kw":["poufność","ograniczony dostęp"],"pulapka":"Poufność z COBIT 4.1 odpowiada celowi „ograniczony dostęp” (Dostęp i Bezpieczeństwo); nie myl jej z integralnością, czyli kompletnością i dokładnością."},"il26_kr_skutecznosc":{"kw":["skuteczność","kryteri","cobit 4.1"],"pulapka":"Skuteczność dotyczy informacji jako produktu (spełnia potrzeby odbiorcy), a wydajność – sposobu jej uzyskania małym nakładem; obiektywność mapuje się i na skuteczność, i na wiarygodność."},"il26_kr_wiarygodnosc":{"kw":["wiarygodność","reputacj"],"pulapka":"Wiarygodność bywa brana za synonim dokładności, ale jest bardziej subiektywna; w COBIT 5 odpowiadają jej wiarygodność, reputacja i obiektywność, a nie integralność."},"il26_kr_wydajnosc":{"kw":["wydajność","kryteri","wydajna"],"pulapka":"Wydajność to informacja spełniająca potrzeby, uzyskana i użyta małym nakładem; samo spełnienie potrzeb to skuteczność. Odpowiedniki: wiarygodność, dostępność, łatwość eksploatacji, reputacja."},"il26_kr_zgodnosc":{"kw":["zgodność","specyfikacjami"],"pulapka":"Zgodność ze specyfikacjami jest wbudowana w każdy cel jakościowy, a zgodność z regulacjami dotyczy raczej sposobu użycia informacji; osobnej kategorii „jakość zgodności” nie ma."},"il28_c_dostep":{"kw":["dostęp do polityk","gdzie znaleźć"],"pulapka":"Dostęp do polityk (czy interesariusze wiedzą, gdzie je znaleźć) nie jest czwartą cechą dobrej polityki; cechy są trzy: skuteczna, wydajna, nieinwazyjna."},"il28_c_metodyki":{"kw":["struktury ramowe","kompleksowe, otwarte","otwarte i elastyczne"],"pulapka":"Na egzaminie „struktury ramowe” (podręcznik: metodyki): mają być kompleksowe, otwarte i elastyczne, aktualne oraz dostępne; to nie cechy polityk ani kryteria zasad."},"il28_c_nieingerencyjne":{"kw":["nieinwazyjn","nieingerencyjn","oporu"],"pulapka":"Na egzaminie „nieinwazyjne” (podręcznik: „nieingerencyjne”): polityka wydaje się logiczna i nie budzi zbędnego oporu; nie oznacza, że nie wymaga żadnej zmiany nawyków."},"il28_c_skuteczne":{"kw":["skuteczn","nieinwazyjn"],"pulapka":"Skuteczna polityka osiąga wskazany cel; pytanie o najmniejszy nakład dotyczy wydajności, a o brak zbędnego oporu nieinwazyjności."},"il28_c_wydajne":{"kw":["wydajn","najbardziej wydajny"],"pulapka":"Wydajna polityka wdraża zasady w najbardziej wydajny sposób (najmniejszym nakładem); osiąganie celu to skuteczność, a logiczność dla przestrzegających to nieinwazyjność."},"il28_c_zasady":{"kw":["ograniczona liczba","prostym językiem","liczba zasad"],"pulapka":"Zasady: ograniczona liczba, prosty język, precyzyjne wyrażenie podstawowych wartości; szczegółowe wytyczne, wyjątki i konsekwencje to już polityki, nie zasady."},"il28_cele":{"kw":["komunikowan","zasady, polityki","instrukcj"],"pulapka":"Cele tego aktywatora to komunikowanie reguł organizacji; nie myl ich z kryteriami zasad (mała liczba, prosty język) ani z cechami polityk (skuteczne, wydajne, nieinwazyjne)."},"il28_cykl":{"kw":["aktualność","cykl życia","najnowszej wersji"],"pulapka":"Kluczowy aspekt cyklu życia polityk to aktualność: przeglądy, aktualizacje, świadomość zmian i dostęp do obowiązującej wersji. Starsze wersje mogą pozostać w oznaczonym archiwum; problemem są niejednoznaczne lub nieoznaczone wersje obowiązujące."},"il28_dobre":{"kw":["apetyt","hierarch","restrykcyjn"],"pulapka":"Dobra praktyka: polityki są częścią hierarchicznej struktury ramowej, odnoszą się do zasad i są dopasowane do apetytu na ryzyko; organizacja niechętna ryzyku ma polityki bardziej restrykcyjne."},"il28_dp_konsekwencje":{"kw":["konsekwencje nieprzestrzegania","konsekwencj"],"pulapka":"Konsekwencje nieprzestrzegania to element struktury polityk, nie kryterium zasad; mówią, co grozi za złamanie reguły, a nie kiedy wolno od niej odstąpić (to wyjątki)."},"il28_dp_kontrola":{"kw":["kontrola zgodności","kontrolę zgodności","pomiar zgodności"],"pulapka":"Kontrola i pomiar zgodności (np. kwartalny przegląd logowań) to osobny element struktury polityk; nie zastępuje go ani cykl życia, ani obsługa wyjątków."},"il28_dp_metodyka":{"kw":["struktura ramowa","ładu i zarządzania"],"pulapka":"Na egzaminie to „struktura ramowa ładu i zarządzania” (podręcznik: metodyka nadzoru i zarządzania); COBIT 5 sam jest przykładem takiej struktury opisanej w tym aktywatorze."},"il28_dp_metodyka_polityk":{"kw":["struktura polityk","struktury polityk"],"pulapka":"Struktura (podręcznik: metodyka) polityk to rama do tworzenia i utrzymania spójnego zbioru polityk; musi opisać zakres i ważność, konsekwencje, wyjątki oraz kontrolę zgodności."},"il28_dp_waznosc":{"kw":["zakres i ważność","ważność","prawidłowość"],"pulapka":"Ważność wraz z zakresem należy do struktury polityk. Określa się warunki obowiązywania i przeglądu polityki; nie każda musi automatycznie wygasać po roku. To inne zagadnienie niż trzy cechy dobrej polityki."},"il28_dp_wyjatki":{"kw":["wyjątk","obsługa wyjątków"],"pulapka":"Obsługa wyjątków mówi, kiedy i kto może odstąpić od polityki; w scenariuszu „zepsuł się laptop służbowy, a trzeba obsłużyć klienta” to ona, nie konsekwencje."},"il28_dp_zakres":{"kw":["zakres i ważność","zakres"],"pulapka":"Zakres i ważność (podręcznik: zakres i prawidłowość) to element struktury polityk, a nie cecha dobrej polityki; mówi, kogo polityka dotyczy i jak długo obowiązuje."},"il28_dp_zasady":{"kw":["ograniczona liczba","wartości"],"pulapka":"Zasady wyrażają podstawowe wartości i są ogólne; zdanie typu „wyjątki zatwierdza kierownik” to już polityka, a nie zasada."},"il28_interesariusze":{"kw":["interesariusz","dwojaki","regulacyjne"],"pulapka":"Jedni interesariusze definiują polityki, inni mają zapewnić ich przestrzeganie. Interesariuszami są również audytorzy, klienci, dostawcy i regulatorzy; konkretny mandat zależy od roli i kontekstu, nie tylko od nazwy grupy."},"il28_pr_deklaracje":{"kw":["deklaracj","produkty"],"pulapka":"Produktem działań tego aktywatora są deklaracje polityk (dane wejściowe/wyniki); nie myl ich z praktykami procesu, które podręcznik nazywa deklaracjami działań."},"il29_c_dostep_bezp":{"kw":["cele dostępności","poufny"],"pulapka":"Cel „proces dostępny dla potrzebujących i poufny, gdy trzeba” to cele dostępności i bezpieczeństwa; trzy kategorie celów procesu to nie cztery wymiary aktywatora."},"il29_c_kontekst":{"kw":["cele kontekstowe","kontekstow"],"pulapka":"Poprawny proces przejęty z innej organizacji, który nie pasuje do jej realiów albo jest niezrozumiały, narusza cele kontekstowe, a nie wewnętrzne."},"il29_c_wewnetrzne":{"kw":["cele wewnętrzne","intrinsic"],"pulapka":"„Wewnętrzne” (intrinsic) znaczy „jakość sama w sobie”, a nie „wewnątrz organizacji”; zgodność z przepisami zewnętrznymi też jest celem wewnętrznym."},"il29_cele":{"kw":["smart","cele procesu"],"pulapka":"Praktyki procesu są ukierunkowane przez polityki i procedury, a cele procesu ocenia się miernikami SMART. Actionable oznacza, że miara umożliwia podjęcie działania."},"il29_cykl":{"kw":["cykl życia procesu","wycofywany","cykl życia"],"pulapka":"Cykl życia procesu to definiowanie, tworzenie, obsługa, monitorowanie oraz dostosowanie lub wycofanie; „dane–informacje–wiedza” i siedem faz wdrożenia to inne cykle."},"il29_cz_typowe_praktyki":{"kw":["15504","typowe praktyki"],"pulapka":"Typowe praktyki wspierające cykl życia procesu pochodzą z modelu oceny opartego na ISO/IEC 15504, a nie z ISO/IEC 27000, ITIL czy ISO/IEC 38500."},"il29_dobre":{"kw":["dobre praktyki","procesy umożliwiające","praktyki, działania"],"pulapka":"Dobre praktyki procesu opisuje model referencyjny z przewodnika Procesy umożliwiające; kolejność szczegółowości to praktyki, działania, szczegółowe działania, a nie odwrotnie."},"il29_dp_dzialania":{"kw":["działania","normatywn"],"pulapka":"Zbiór działań opisuje konieczne i wystarczające kroki realizacji praktyki. Ogólne działania COBIT nie są normatywną procedurą: organizacja je dostosowuje i rozwija."},"il29_dp_praktyki":{"kw":["praktyki nadzoru","praktyki zarządzania","praktyk bazowych"],"pulapka":"Praktyki to ogólne wymogi do dostosowania przez organizację, a nie do wdrożenia słowo w słowo; w modelu oceny odpowiadają im praktyki bazowe."},"il29_dp_praktyki_dzialania":{"kw":["szczegółowe działania","praktyki, działania"],"pulapka":"Trzy poziomy szczegółowości to praktyki, działania i szczegółowe działania; produkty działań (wejścia i wyniki) nie są czwartym poziomem, tylko osobnym elementem dobrych praktyk."},"il29_dp_produkty":{"kw":["produkty pracy","ścieżk","dane wejściowe"],"pulapka":"Wejścia i wyniki (produkty pracy) wspierają decyzje i dają ścieżkę rewizyjną; nie przypisują ról (to robi RACI) i nie zastępują praktyk."},"il29_dp_szczegolowe":{"kw":["szczegółowe działania","itil","prince2"],"pulapka":"Szczegółowe działania bierze się z innych standardów (ITIL, ISO/IEC 27000, PRINCE2), a nie z tabeli RACI ani z modelu dojrzałości COBIT 4.1."},"il29_interesariusze":{"kw":["interesariusze wewnętrzni","raci","interesariusze zewnętrzni"],"pulapka":"Interesariusze procesu bywają wewnętrzni i zewnętrzni (klienci, partnerzy, regulatorzy); ich odpowiedzialność opisuje tabela RACI, która nie jest osobnym wymiarem aktywatora."},"il29_poziom_potencjalu":{"kw":["poziom zdolności","15504"],"pulapka":"Poziom zdolności nie jest kategorią wskaźników wydajności aktywatora (wiodące i opóźnione); to osobna skala oceny procesu według ISO/IEC 15504."},"il30_apo":{"kw":["apo","dostosuj, planuj i organizuj"],"pulapka":"APO to na egzaminie „Dostosuj, Planuj i Organizuj” (podręcznik: dopasowanie, planowanie i organizacja); obejmuje m.in. strategię, architekturę, budżet, ryzyko i bezpieczeństwo."},"il30_bai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI to na egzaminie „Twórz, Nabywaj i Wdrażaj”; zarządzanie zmianami i konfiguracją jest w BAI, a nie w DSS."},"il30_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"DSS to na egzaminie „Dostarczaj, Obsługuj i Wspieraj”, obszar Wykonuj (Run): eksploatacja, incydenty, problemy, ciągłość i usługi bezpieczeństwa."},"il30_kierowanie":{"kw":["kieruj","kierunek","edm"],"pulapka":"Kierowanie (Direct) to ustalanie priorytetów i podejmowanie decyzji przez Ład; kierunek płynie od Ładu do Zarządzania, nie odwrotnie."},"il30_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"MEA to domena Zarządzania „Monitoruj, Oszacuj i Oceń”, a nie Ładu; to ona daje Ładowi informacje zwrotne."},"il30_monitorowanie":{"kw":["monitoruj","mea","edm"],"pulapka":"Na Rysunku 30 są dwa „Monitorowania”: w Ładzie (EDM, czy kierunek wcielono w życie) i domena MEA w Zarządzaniu; zarząd porównujący raport z decyzją monitoruje w Ładzie."},"il30_nadzor":{"kw":["edm","oszacuj, kieruj i monitoruj","rysunek 15"],"pulapka":"Podręcznik: „Nadzór”, egzamin: „Ład”; jego domena to EDM z pięcioma procesami, a Rysunek 30 to ten sam schemat co Rysunek 15."},"il30_ocena":{"kw":["oszacuj","edm"],"pulapka":"Egzamin: „Oszacuj” (Evaluate), pierwsza czynność EDM; to ocena potrzeb i opcji przez Ład, nie domena MEA „Monitoruj, Oszacuj i Oceń”."},"il30_s_informacje_zwrotne":{"kw":["informację zwrotną","informacje zwrotne","informacji zwrotnej"],"pulapka":"Informacje zwrotne płyną od Zarządzania do Ładu, a kierunek odwrotnie; oddzielenie Ładu od Zarządzania nie oznacza odcięcia komunikacji."},"il30_s_potrzeby":{"kw":["potrzeb biznesowych","potrzeby biznesowe"],"pulapka":"Przepływ na Rysunku 30 (i 15) zaczyna się od potrzeb biznesowych trafiających do Ładu, a nie od planowania w APO ani od MEA."},"il30_zarzadzanie":{"kw":["pbrm","planuj, twórz, wykonuj i monitoruj"],"pulapka":"Zarządzanie ma cztery domeny PBRM: APO, BAI, DSS i MEA; MEA należy do Zarządzania, choć nazywa się „Monitoruj”."},"il32_cele":{"kw":["struktury organizacyjne","jakość kontekstowa","decyzj"],"pulapka":"Cele struktury to właściwe umocowanie, dobrze zdefiniowane zasady działania i inne dobre praktyki; wynikiem mają być odpowiednie działania i decyzje."},"il32_cykl":{"kw":["mandat","cykl życia"],"pulapka":"Mandat, czyli powód i cel istnienia, definiuje się przy założeniu struktury; termin rozwiązania nie jest wymagany, choć struktura może zostać rozwiązana."},"il32_cz_mandat":{"kw":["mandat","struktury organizacyjne"],"pulapka":"Mandat i zasady działania struktury określa wdrożona struktura polityk (s. 75); mandat to nie zakres kontroli ani poziom uprawnień."},"il32_dobre":{"kw":["delegowanie uprawnień","zasady operacyjne","zakres kontroli"],"pulapka":"Na ilustracji jest pięć praktyk, a tekst dodaje szóstą: skład; komunikowanie czy zachęty to praktyki Kultury, a nieinwazyjność to cecha dobrej polityki."},"il32_dp_eskalacja":{"kw":["procedury eskalacji","eskalac"],"pulapka":"Eskalacja idzie w górę, gdy struktura ma problem z podjęciem decyzji, a delegowanie w dół; w pytaniach te dwa pojęcia często się zamienia."},"il32_dp_poziom_uprawnien":{"kw":["poziom uprawnień","uprawnienia decyzyjne"],"pulapka":"Poziom uprawnień (podręcznik: poziom decyzyjny/uprawnienia decyzyjne) to decyzje, które struktura może podjąć; granice tych uprawnień to zakres kontroli."},"il32_dp_przekazywanie":{"kw":["delegowanie uprawnień","przekazywanie uprawnień"],"pulapka":"Na egzaminie „delegowanie uprawnień”: przekazanie w dół, strukturom podległym; przekazanie sprawy w górę, gdy brak decyzji, to procedura eskalacji."},"il32_dp_sklad":{"kw":["skład","struktury organizacyjne"],"pulapka":"Skład to członkowie struktury, wewnętrzni lub zewnętrzni; jest w tekście (s. 75), ale nie na Ilustracji 32, i powinien odzwierciedlać właściwe umiejętności."},"il32_dp_zakres_kontroli":{"kw":["zakres kontroli","granice uprawnień"],"pulapka":"Zakres kontroli to granice uprawnień decyzyjnych struktury; „decyzje, do których struktura jest uprawniona” to już poziom uprawnień."},"il32_dp_zasady_dzialania":{"kw":["zasady operacyjne","zasady działania"],"pulapka":"Na egzaminie „zasady operacyjne” (podręcznik: zasady działania): częstotliwość zebrań, dokumentacja, porządek; nie myl ich z poziomem uprawnień ani z regułami i normami."},"il32_interesariusze":{"kw":["struktury organizacyjne","rysunek 32","interesariusz"],"pulapka":"Interesariusze struktury to członkowie, inne struktury, klienci, dostawcy i regulatorzy; ich role to decydowanie, wywieranie wpływu i doradztwo, nie samo członkostwo."},"il32_pr_decyzje":{"kw":["decyzj","dane wejściowe"],"pulapka":"Produktem struktury są decyzje, a wejściem zwykle informacje; o tym, czy decyzje struktur są wdrażane, decyduje też Kultura, etyka i zachowanie (s. 75, 80)."},"il33_audyt":{"kw":["audyt","audyty wewnętrzne"],"pulapka":"W tabeli rola Audyt odpowiada za audyty wewnętrzne, CRO za zarządzanie ryzykiem, a Zgodność za wytyczne dotyczące wymogów. Audyt może oceniać ryzyko i zgodność; nie przejmuje przez to zarządczej odpowiedzialności za te obszary."},"il33_ceo":{"kw":["ceo","dyrektor generalny"],"pulapka":"CEO jest najwyższym rangą dyrektorem odpowiedzialnym za pełne zarządzanie przedsiębiorstwem. Rozliczalność za Ład przypisano organowi nadzorującemu (board). CEO może jednocześnie być jego członkiem, lecz są to odrębne role."},"il33_cfo":{"kw":["cfo","dyrektor ds. finansowych","rachunkowość"],"pulapka":"CFO odpowiada za ryzyko finansowe, a nie za całe ryzyko organizacji (to CRO); słowo „rachunkowość” w opisie roli wskazuje na CFO."},"il33_cio":{"kw":["cio","dyrektor ds. informatyki","dopasowanie strategii"],"pulapka":"Najwyższa rangą rola od dopasowania strategii IT do biznesowej to CIO (Sample Paper); ale komitetowi ds. strategii IT przewodniczy zwykle członek zarządu, nie CIO."},"il33_ciso":{"kw":["ciso","bezpieczeństwo informacji","wszystkich formach"],"pulapka":"CISO odpowiada za bezpieczeństwo informacji we wszystkich formach, także papierowych; nie myl z Kierownikiem ds. bezpieczeństwa informacji, który projektuje, nadzoruje i ocenia zabezpieczenia."},"il33_coo":{"kw":["coo","dyrektor ds. operacyjnych","funkcjonowanie"],"pulapka":"COO odpowiada za funkcjonowanie całej organizacji; środowiska operacyjne i infrastruktura IT to Dyrektor ds. operacji IT: podobna nazwa, inna rola."},"il33_cro":{"kw":["cro","dyrektor ds. ryzyka","ryzykiem w całej"],"pulapka":"CRO odpowiada za wszystkie aspekty zarządzania ryzykiem przedsiębiorstwa; CFO za zarządzanie finansami, w tym ryzyko finansowe, a CISO za bezpieczeństwo informacji. Komitet ryzyka jest grupą uzgadniającą wspólne stanowisko; CRO może uczestniczyć w jej pracach."},"il33_czlonek_kier":{"kw":["naczelnego kierownictwa","jednostki biznesowej","dyrektor działu biznesowego"],"pulapka":"Członek naczelnego kierownictwa odpowiada za jedną jednostkę biznesową lub spółkę zależną (Sample Paper: „Dyrektor Działu Biznesowego”); całą organizacją kieruje CEO."},"il33_dyr_admin_it":{"kw":["administracji it","kwestie administracyjne"],"pulapka":"Zapisy związane z IT i sprawy administracyjne IT to Dyrektor ds. administracji IT; nie myl go z PMO, które zbiera i raportuje informacje o realizacji projektów."},"il33_dyr_arch":{"kw":["dyrektor ds. architektury","szef architektury"],"pulapka":"Dyrektor ds. architektury (Sample Paper: „Szef Architektury”) odpowiada za proces architektury korporacyjnej; wytyczne, polityki i standardy architektury daje Rada ds. Architektury."},"il33_dyr_hr":{"kw":["zasobami ludzkimi","kadrow"],"pulapka":"Planowanie i polityki kadrowe to Dyrektor ds. zarządzania zasobami ludzkimi, nie COO; to rola z Rysunku 33, a nie aktywator Ludzie, umiejętności i kompetencje."},"il33_dyr_operacji_it":{"kw":["operacji it","infrastrukturę it"],"pulapka":"Środowiska operacyjne i infrastruktura IT to Dyrektor ds. operacji IT, nie COO (funkcjonowanie całej organizacji) i nie Kierownik ds. ciągłości (funkcje krytyczne po zakłóceniu)."},"il33_dyr_prywatnosci":{"kw":["ds. prywatności","prywatności","ochrony danych"],"pulapka":"Ryzyko i wpływ przepisów o prywatności to Dyrektor ds. prywatności (inaczej: ds. ochrony danych); funkcja Zgodność obejmuje wymogi prawne ogólnie, nie tylko prywatność."},"il33_dyr_rozwoju":{"kw":["dyrektor ds. rozwoju","rozwoju rozwiązań"],"pulapka":"Dyrektor ds. rozwoju odpowiada za procesy rozwoju rozwiązań IT, czyli budowanie; utrzymanie środowisk i infrastruktury to Dyrektor ds. operacji IT, a usługi dla klientów – Kierownik ds. usług."},"il33_kier_bezp_inf":{"kw":["kierownik ds. bezpieczeństwa informacji","bezpieczeństwa informacji"],"pulapka":"Kierownik ds. bezpieczeństwa informacji projektuje, nadzoruje i ocenia bezpieczeństwo; dyrektor najwyższego szczebla od bezpieczeństwa informacji we wszystkich formach to CISO."},"il33_kier_ciaglosci":{"kw":["ciągłości działalności","ciągłości"],"pulapka":"Opis kierownika ds. ciągłości obejmuje zdolność przedsiębiorstwa do utrzymania funkcji krytycznych po zakłóceniach. Dyrektor operacji IT i CISO również mogą wspierać ciągłość, ale mają inne podstawowe zakresy odpowiedzialności."},"il33_kier_uslug":{"kw":["kierownik ds. usług","grupy klientów"],"pulapka":"Kierownik ds. usług zarządza produktami i usługami dla określonego klienta lub grupy klientów; środowiska i infrastruktura to Dyrektor ds. operacji IT, a rozwój rozwiązań – Dyrektor ds. rozwoju."},"il33_komitet_ryzyka":{"kw":["komitet ds. zarządzania ryzykiem","zarządzania ryzykiem przedsiębiorstwa","komitet ds. ryzyka"],"pulapka":"Grupa uzgadniająca wspólne stanowisko w sprawie ERM to komitet ds. zarządzania ryzykiem w przedsiębiorstwie; CRO to jedna osoba, a rada ds. ryzyka IT może komitetowi tylko doradzać."},"il33_komitet_strategii":{"kw":["komitet ds. strategii","przewodniczy","wykonawczy it"],"pulapka":"Przewodniczy zwykle członek zarządu, nie CIO: klasyczna pułapka. Komitet odpowiada za portfele inwestycji, usług i zasobów IT, a komitety sterujące za pojedyncze programy i projekty."},"il33_komitety_sterujace":{"kw":["komitet sterujący","komitety sterujące","programów i projektów"],"pulapka":"Wytyczne dla programów i projektów, przydział zasobów, korzyści i ryzyko to komitety sterujące; PMO tylko wspiera kierowników i raportuje, a komitet ds. strategii pilnuje całego portfela."},"il33_pmo":{"kw":["pmo","biuro zarządzania projektami"],"pulapka":"PMO wspiera kierowników programów i projektów oraz gromadzi, ocenia i raportuje informacje o realizacji. Kierownik prowadzi projekt, a komitet sterujący zapewnia wytyczne i nadzór. Sekretariat portfela inwestycji i usług to w tej tabeli VMO."},"il33_rada_arch":{"kw":["rada ds. architektury","architektury korporacyjnej"],"pulapka":"Rada ds. Architektury to grupa, która daje wytyczne oraz tworzy polityki i standardy architektury; za proces architektury korporacyjnej odpowiada jedna osoba: Dyrektor ds. architektury."},"il33_vmo":{"kw":["vmo","biuro zarządzania wartością","uzasadnień biznesowych"],"pulapka":"Sekretariat portfela inwestycji i usług, ocena uzasadnień biznesowych i raport o wartości to VMO, nie PMO; litery P i V łatwo zamienić."},"il33_wlasc_proc":{"kw":["właściciel procesu","właściciela procesu","sprawność procesu"],"pulapka":"Sprawność procesu, jego doskonalenie i zatwierdzanie zmian to właściciel procesu biznesowego; CEO odpowiada za całą organizację, a członek naczelnego kierownictwa za całą jednostkę."},"il33_zarzad":{"kw":["zarząd","rysunku 33","członek zarządu"],"pulapka":"Board (organ nadzorujący; w podręczniku PL „zarząd”) jest rozliczany za Ład i ogólną kontrolę nad zasobami. CEO odpowiada za pełne zarządzanie. Nie wyciągaj z tego wniosku, że CEO nie może być członkiem organu nadzorującego."},"il33_zgodnosc":{"kw":["zgodność","wymogami prawnymi","funkcja zgodność"],"pulapka":"Funkcja Zgodność odpowiada w tej tabeli za wytyczne dotyczące wymogów prawnych, regulacyjnych i umownych. Audyt odpowiada za audyty wewnętrzne, a dyrektor ds. prywatności za szczególny obszar ochrony prywatności. Obszary współpracują, nie są od siebie odizolowane."},"il34_c_etyka_ind":{"kw":["etyka indywidualna","etykę indywidualną","osobiste wartości"],"pulapka":"Etykę indywidualną kształtują osobiste wartości, w znacznym stopniu zależne od czynników zewnętrznych i doświadczeń. System wynagradzania sklasyfikowano wśród dobrych praktyk jako zachęty; może on wpływać na zachowania, ale nie jest definicją etyki indywidualnej."},"il34_c_etyka_org":{"kw":["etyka organizac","etykę organizac","wartości"],"pulapka":"Etyka organizacji to wartości, na których ma działać przedsiębiorstwo; osobiste wartości pracownika to etyka indywidualna, a suma zachowań to kultura."},"il34_c_wzorce":{"kw":["wzorce zachowań","wzorców zachowań","kulturę"],"pulapka":"Kulturę organizacji tworzą łącznie indywidualne wzorce zachowań, a nie regulamin ani wartości jednego lidera."},"il34_cele":{"kw":["etyka indywidualna","etyka organizac","etyk"],"pulapka":"Cele tego aktywatora to etyka organizacji, etyka indywidualna i indywidualne wzorce zachowań; komunikowanie, egzekwowanie i zachęty to dobre praktyki, nie cele."},"il34_cykl":{"kw":["cykl życia","kultura, etyka"],"pulapka":"Kultura ma cykl życia jak każdy aktywator i zaczyna się od kultury już istniejącej, nie od zera; nie myl go z siedmioma fazami cyklu życia wdrożenia."},"il34_dobre":{"kw":["dobre praktyki","czempion","komunikowanie"],"pulapka":"Sześć praktyk: komunikowanie, egzekwowanie, zachęty i nagrody, świadomość, reguły i normy, czempioni; zakres kontroli czy delegowanie uprawnień to praktyki Struktur organizacyjnych."},"il34_dp_egzekwowanie":{"kw":["egzekwowanie","egzekwowania","kultura, etyka"],"pulapka":"Egzekwowanie to pilnowanie przestrzegania wymagań, a nie ich ogłaszanie (komunikowanie) ani nagradzanie (zachęty i nagrody)."},"il34_dp_komunikowanie":{"kw":["komunikowanie","komunikowania"],"pulapka":"Komunikowanie to ogłaszanie pożądanych zachowań i wartości w całej organizacji; dawanie przykładu przez kierownictwo to już praktyka „świadomość”."},"il34_dp_osoby_wsp":{"kw":["czempion","osoby wspierające"],"pulapka":"Na egzaminie to „czempioni” (podręcznik: inne osoby wspierające); nie myl ich z właścicielami procesów biznesowych ani z konsultowanymi z RACI."},"il34_dp_reguly":{"kw":["reguły i normy","zasadami i politykami"],"pulapka":"Reguły i normy to dodatkowe wytyczne o zachowaniach, wyraźnie powiązane z zasadami i politykami; nie myl ich z praktyką struktur „zasady operacyjne”."},"il34_dp_swiadomosc":{"kw":["świadomoś","przykład kierownictwa"],"pulapka":"Świadomość buduje przykład kierownictwa wyższego szczebla i czempionów; nie myl jej z atrybutem dojrzałości COBIT 4.1 „świadomość i komunikowanie” (Rysunek 18)."},"il34_dp_zachety":{"kw":["zachęty","wynagradza"],"pulapka":"Zachęty obejmują także środki zniechęcające i wiążą się z wynagradzaniem HR. Przykład 11 pokazuje, że premiowanie wyłącznie terminu i budżetu może osłabić jakość; nie jest to nieuchronny skutek każdej takiej premii."},"il34_interesariusze":{"kw":["kultura, etyka","rysunek 34","interesariusz"],"pulapka":"Interesy są dwojakie: jedni (dział prawny, ryzyko, HR, rada ds. wynagrodzeń) definiują i egzekwują zachowania, inni muszą ich przestrzegać; zewnętrzni to regulatorzy, audytorzy zewnętrzni, organy nadzorcze."},"il34_z_negatywne":{"kw":["negatywnych wynik","winn","obwinia"],"pulapka":"Pytanie: czy firma uczy się na szkodach i utraconych szansach, czy tylko przypisuje winę bez usunięcia przyczyny; „kultura obwiniania” to symptom złej kultury ryzyka (Przykład 12)."},"il34_z_polityka":{"kw":["przestrzeganiem polityki","przestrzegania polityki","polityk"],"pulapka":"Pytanie brzmi: w jakim stopniu pracownicy przyjmują politykę i jej przestrzegają; znajomość polityki bez jej stosowania to właśnie ten rodzaj zachowania."},"il34_z_ryzyko":{"kw":["podejmowaniem ryzyka","apetyt na ryzyko"],"pulapka":"To przykład zachowania (ile ryzyka firma może przyjąć i jakie gotowa jest podjąć), a nie dobra praktyka; formalny apetyt na ryzyko ustala Ład (EDM03)."},"il35_dane":{"kw":["danych","dane"],"pulapka":"Dane to wynik pracy procesów biznesowych; aktywator Informacja obejmuje głównie fazę „informacje”, ale uwzględnia też dane i wiedzę."},"il35_informacje":{"kw":["cykl życia informacji","cykl informacji","informacj"],"pulapka":"Rysunek 35 (cykl informacji) to nie cykl życia aktywatora Informacja (planowanie… pozbywanie się) ani warstwy atrybutów z Rysunku 36."},"il35_procesy_biz":{"kw":["procesy biznesowe","cykl informacji","rysunek 35"],"pulapka":"Dane generują i przetwarzają procesy biznesowe (z procesami IT w środku), nie tylko dział IT; Informacja obejmuje też informacje niezautomatyzowane."},"il35_procesy_it":{"kw":["procesy it","cykl informacji"],"pulapka":"Procesy IT leżą wewnątrz procesów biznesowych na Rysunku 35; nie są początkiem cyklu ani jego wyznacznikiem."},"il35_s_generowanie":{"kw":["generuj","cykl informacji"],"pulapka":"Na Rysunku 35 strzałka Generowanie i przetwarzanie prowadzi od procesów biznesowych do danych. Procesy IT są pokazane wewnątrz procesów biznesowych; także one mogą uczestniczyć w generowaniu i przetwarzaniu danych."},"il35_s_przeksztalcanie_1":{"kw":["przekształc","informacj"],"pulapka":"Na Rysunku 35 są dwie strzałki „przekształcanie”: dane → informacje i informacje → wiedza; „tworzenie” to dopiero wiedza → wartość."},"il35_s_przeksztalcanie_2":{"kw":["przekształc","wiedz"],"pulapka":"Drugie „przekształcanie” zamienia informacje w wiedzę; nie myl go z „tworzeniem”, które z wiedzy daje wartość."},"il35_s_tworzenie":{"kw":["tworzeni","wartoś"],"pulapka":"„Tworzenie” to jedyna strzałka prowadząca do wartości, a jej źródłem jest wiedza."},"il35_s_wyznacznik":{"kw":["wyznacznik","cykl informacji"],"pulapka":"„Wyznacznik” na Rysunku 35 to etykieta strzałki zamykającej cykl między wartością a procesami biznesowymi; nie myl go z wyznacznikami (drivers) na górze Kaskady Celów."},"il35_wartosc":{"kw":["wartość","wartości"],"pulapka":"Na Rysunku 35 wartość jest efektem wykorzystania wiedzy w cyklu: dane → informacje → wiedza → wartość. To model pojęciowy; nie oznacza zakazu uzyskiwania korzyści z danych ani tego, że same zebrane dane automatycznie tworzą wartość."},"il35_wiedza":{"kw":["wiedz","cykl informacji"],"pulapka":"Kolejność to dane → informacje → wiedza → wartość; odpowiedzi z odwróconą kolejnością (np. wiedza tworzy dane) są błędne."},"il36_a_aktualnosc":{"kw":["aktualność","przyszłości","semantyczn"],"pulapka":"Atrybut „aktualność informacji” (przeszłość, teraźniejszość, przyszłość) leży w warstwie semantycznej; „wystarczająco świeża do zadania” to cel jakości kontekstowej."},"il36_a_innowacyjnosc":{"kw":["innowacyjność","pragmatyczn"],"pulapka":"Innowacyjność jest tu atrybutem pragmatycznym: informacja tworzy nową wiedzę lub potwierdza istniejącą. To inne pojęcie niż PA 5.1 Innowacje procesu i cel IT 17; samo wspólne słowo nie oznacza tej samej klasyfikacji."},"il36_a_kanal":{"kw":["kanał dostępu","empirycznej"],"pulapka":"Kanał dostępu (np. interfejs użytkownika) to atrybut warstwy empirycznej, nie fizycznej; nie myl go też z celem „ograniczony dostęp”."},"il36_a_kod":{"kw":["kod/język","syntaktyczn"],"pulapka":"Kod/język (format kodowania, reguły łączenia symboli) to atrybut warstwy syntaktycznej; pytania o strony kodowe i strukturę zapisu też prowadzą do tej warstwy."},"il36_a_kontekst":{"kw":["kontekst","społeczn"],"pulapka":"Kontekst (kulturowy, dziedziny tematycznej) to atrybut warstwy społecznej; „jakość kontekstowa” to zupełnie inna rzecz, kategoria w wymiarze Cele."},"il36_a_nosnik":{"kw":["nośnik","warstwa fizyczna"],"pulapka":"Nośnik/media (papier, sygnały elektryczne, fale dźwiękowe) to atrybut warstwy fizycznej; nie myl go z kanałem dostępu z warstwy empirycznej."},"il36_a_okres":{"kw":["okres przechowywania","pragmatyczn"],"pulapka":"Okres przechowywania to atrybut warstwy pragmatycznej, nie fizycznej; samo niszczenie po terminie to faza cyklu życia Aktualizacja/pozbywanie się."},"il36_a_poziom":{"kw":["poziom informacji","szczegółowości","semantyczn"],"pulapka":"Poziom informacji (sprzedaż roczna, kwartalna, miesięczna) to szczegółowość w warstwie semantycznej; nie myl go z celem „odpowiednia ilość informacji”."},"il36_a_status":{"kw":["status informacji","historyczn","pragmatyczn"],"pulapka":"Status informacji (operacyjne czy historyczne) to warstwa pragmatyczna; nie myl go z atrybutem aktualność (przeszłość/teraźniejszość/przyszłość) z warstwy semantycznej."},"il36_a_typ":{"kw":["typ informacji","semantyczn"],"pulapka":"Typ informacji (finansowe/niefinansowe, zewnętrzne/wewnętrzne, prognozowane/zaobserwowane, planowane/uzyskane) leży w warstwie semantycznej, nie pragmatycznej."},"il36_a_zaleznosc":{"kw":["zależność","pragmatyczn"],"pulapka":"Zależność wskazuje informacje, które muszą poprzedzać daną informację; to atrybut warstwy pragmatycznej, nie relacja między aktywatorami."},"il36_cele":{"kw":["jakość kontekstowa","jakość wewnętrzna","dostęp i bezpieczeństwo"],"pulapka":"Trzy podwymiary jakości to kategorie wymiaru Cele, nie osobne wymiary aktywatora; egzamin: jakość wewnętrzna, jakość kontekstowa (i reprezentacji) oraz Dostęp i Bezpieczeństwo."},"il36_cykl":{"kw":["cykl życia","cyklowi informacji"],"pulapka":"Cykl życia aktywatora Informacja (planowanie…pozbywanie się) to nie cykl informacji z Rysunku 35 (dane → informacje → wiedza → wartość)."},"il36_dobre":{"kw":["atrybutów informacji","warstw","dobre praktyki"],"pulapka":"Dobra praktyka aktywatora Informacja to definiowanie atrybutów na sześciu warstwach; nie ma ogólnie przyjętej definicji informacji, a warstwy to nie podwymiary jakości."},"il36_dp_definiowanie":{"kw":["definiowanie atrybutów","atrybutów informacji"],"pulapka":"„Definiowanie atrybutów informacji” to praktyka aktywatora Informacja; w pytaniach o dobre praktyki innych aktywatorów często jest błędną odpowiedzią."},"il36_interesariusze":{"kw":["interesariusza informacji","opiekun informacji","wytwórca informacji"],"pulapka":"Wymiar Interesariusze informacji nie jest niezależny: role zależą od fazy cyklu życia; szczegółowe role (architekt, właściciel, powiernik) to inna lista niż trzy role ogólne."},"il36_l_aktualizacja":{"kw":["pozbywanie","cykl życia"],"pulapka":"Archiwizacja i niszczenie to faza Aktualizacja/pozbywanie się; maksymalny czas trzymania to osobny atrybut „okres przechowywania” w warstwie pragmatycznej."},"il36_l_budowanie":{"kw":["budowanie/nabywanie","nabywanie","cykl życia"],"pulapka":"Tworzenie zapisów, nabywanie danych i ładowanie plików zewnętrznych to Budowanie/nabywanie; przechowywanie to już faza Użytkowanie/obsługa."},"il36_l_ocena":{"kw":["ocena/monitorowanie","monitorowanie","cykl życia"],"pulapka":"Czyszczenie, scalanie i usuwanie duplikatów to Ocena/monitorowanie, nie Aktualizacja/pozbywanie się; celem jest zachowanie wartości zasobu."},"il36_l_planowanie":{"kw":["planowanie","cykl życia"],"pulapka":"Identyfikacja celów, architektura informacji, standardy i definicje danych to faza Planowanie, nie Projektowanie; Projektowanie nie ma w podręczniku opisu."},"il36_l_projektowanie":{"kw":["projektowanie","cykl życia"],"pulapka":"Projektowanie jest wymienione w ogólnym cyklu aktywatora. Szczegółowy tekst o informacji nie opisuje go osobnym punktem; nie należy na tej podstawie twierdzić, że faza nie istnieje lub nie może dotyczyć jej pytanie."},"il36_l_przechowywanie":{"kw":["przechowywanie","warstwa fizyczna"],"pulapka":"Przechowywanie obejmuje papier, a nawet ludzką pamięć, nie tylko systemy; to część Użytkowania/obsługi, a fizyczne „gdzie” opisuje warstwa fizyczna."},"il36_l_udostepnianie":{"kw":["udostępnianie","przechowywanie"],"pulapka":"Udostępnianie (np. e-mail, dostęp do bazy) może się mocno nakładać na przechowywanie, gdy informacja jest w postaci elektronicznej."},"il36_l_uzytkowanie":{"kw":["użytkowanie","udostępnianie","cykl życia"],"pulapka":"Użytkowanie/obsługa to faza zbiorcza: przechowywanie, udostępnianie i wykorzystanie są jej częściami, nie osobnymi fazami głównego cyklu."},"il36_l_wykorzystanie":{"kw":["wykorzystanie","cykl życia"],"pulapka":"Wykorzystanie obejmuje też pozyskiwanie i konwersję informacji; informacje nie mają wartości same w sobie, daje ją dopiero ich użycie."},"il36_q_aktualnosc":{"kw":["aktualność","jakość kontekstowa"],"pulapka":"Aktualność jako cel jakości (jakość kontekstowa) to co innego niż atrybut „aktualność informacji” w warstwie semantycznej, który mówi tylko, czy informacja dotyczy przeszłości, teraźniejszości czy przyszłości."},"il36_q_bezp":{"kw":["dostęp i bezpieczeństwo","bezpieczeństwa i dostępności"],"pulapka":"Podręcznik: „jakość bezpieczeństwa/dostępności”, egzamin: „Dostęp i Bezpieczeństwo”; to kategoria celów w wymiarze Cele, nie osobny aktywator ani piąty wymiar."},"il36_q_dokladnosc":{"kw":["dokładność","integralność","jakość wewnętrzna"],"pulapka":"Dokładność należy do jakości wewnętrznej; integralność z COBIT 4.1 rozpisano w COBIT 5 na dwa cele: kompletność i dokładność."},"il36_q_dostepnosc":{"kw":["dostępność","dostęp i bezpieczeństwo"],"pulapka":"Dostępność/terminowość należy do Dostępu i Bezpieczeństwa, nie do jakości kontekstowej: „dostępna, gdy potrzebna” to dostęp, a „wystarczająco świeża” to aktualność."},"il36_q_ilosc":{"kw":["odpowiedniej ilości","ilości informacji","jakość kontekstowa"],"pulapka":"Odpowiednia ilość informacji (właściwy wolumen) to jakość kontekstowa; nie myl jej z kompletnością (niczego nie brakuje) ani z poziomem informacji (szczegółowość, warstwa semantyczna)."},"il36_q_interpretacja":{"kw":["interpretacji","jakość kontekstowa"],"pulapka":"Możliwość interpretacji (właściwe języki, symbole, jednostki, jasne definicje) to jakość kontekstowa; nie myl jej z jasnością przekazu, czyli łatwą zrozumiałością."},"il36_q_istotnosc":{"kw":["istotność","jakość kontekstowa"],"pulapka":"Istotność (informacja daje się zastosować w zadaniu) należy do jakości kontekstowej; na Rysunku 36 przy jakości kontekstowej stoi w nawiasie „istotność, skuteczność”."},"il36_q_jasnosc":{"kw":["zrozumiał","jakość kontekstowa"],"pulapka":"Jasność przekazu (informacje łatwo zrozumiałe) to jakość kontekstowa i reprezentacji; słowo „zrozumiały” w pytaniu wskazuje jakość kontekstową, nie wewnętrzną."},"il36_q_kompletnosc":{"kw":["kompletność","integralność","jakość kontekstowa"],"pulapka":"Kompletność to jakość kontekstowa, nie wewnętrzna; razem z dokładnością przejęła kryterium integralności z COBIT 4.1."},"il36_q_kontekstowa":{"kw":["jakość kontekstowa","reprezentacji"],"pulapka":"Jakość kontekstowa zależy od zadania: istotność, kompletność, aktualność, zrozumiałość. Dokładne, ale nieaktualne dane to brak jakości kontekstowej, nie wewnętrznej."},"il36_q_latwosc":{"kw":["łatwość posługiwania","jakość kontekstowa"],"pulapka":"Łatwość posługiwania się (łatwo przekształcić i użyć w różnych zadaniach) to jakość kontekstowa; nie myl jej z dostępnością, która dotyczy uzyskania informacji na czas."},"il36_q_obiektywnosc":{"kw":["obiektywność","jakość wewnętrzna"],"pulapka":"Obiektywność (bezstronność, brak uprzedzeń) to jakość wewnętrzna, nie kontekstowa; nie myl jej z wiarygodnością, czyli tym, czy informację uważa się za prawdziwą."},"il36_q_ograniczony":{"kw":["ograniczony dostęp","dostęp i bezpieczeństwo"],"pulapka":"Ograniczony dostęp (tylko upoważnione strony) to Dostęp i Bezpieczeństwo; nie myl go z atrybutem „kanał dostępu” z warstwy empirycznej."},"il36_q_reputacja":{"kw":["reputacja","reputację"],"pulapka":"Reputacja zależy od źródła lub treści, nie od zadania, więc to jakość wewnętrzna, nie kontekstowa; nie myl jej też z warstwą świata społecznego (kontekst)."},"il36_q_rzeczywista":{"kw":["jakość wewnętrzna","jakość rzeczywista"],"pulapka":"Podręcznik: „jakość rzeczywista”, egzamin: „jakość wewnętrzna”. „Wewnętrzna” znaczy „sama w sobie”, nie „wewnątrz organizacji”; obejmuje dokładność, obiektywność, wiarygodność, reputację."},"il36_q_spojne":{"kw":["spójne przedstawienie","jakość kontekstowa"],"pulapka":"Spójne przedstawienie to ten sam format (jakość kontekstowa); różny zapis dat bywa też pytaniem o warstwę syntaktyczną, więc sprawdź, czy pytają o cel jakości, czy o warstwę."},"il36_q_wiarygodnosc":{"kw":["wiarygodność","jakość wewnętrzna"],"pulapka":"Wiarygodność (informacja uważana za prawdziwą i godną zaufania) to jakość wewnętrzna; nie myl jej z reputacją, która wynika z cenionego źródła lub treści."},"il36_q_zwiezle":{"kw":["zwięzł","jakość kontekstowa"],"pulapka":"Zwięzłe przedstawienie to jakość kontekstowa i reprezentacji; nie myl go ze spójnym przedstawieniem, które oznacza ten sam format prezentacji."},"il36_r_konsument":{"kw":["konsument informacji","korzystanie z informacji"],"pulapka":"Konsument informacji z niej korzysta; gdy pytanie mówi „kto używa raportu do decyzji”, odpowiedzią jest konsument, nie opiekun ani wytwórca."},"il36_r_opiekun":{"kw":["opiekun informacji","przechowywanie i utrzymywanie"],"pulapka":"Opiekun przechowuje i utrzymuje informacje. Dział IT może pełnić tę rolę dla danych biznesu, a dla innych informacji być jednocześnie wytwórcą lub konsumentem; role opisują relację do konkretnych informacji."},"il36_r_wytworca":{"kw":["wytwórca informacji","tworzenie informacji"],"pulapka":"Wytwórca tworzy informacje; nie myl go z opiekunem (przechowuje i utrzymuje) ani z konsumentem (korzysta). To role ogólne z modelu informacji, nie role z Rysunku 33."},"il36_w_empiryczny":{"kw":["warstwa empiryczna","empirycznej"],"pulapka":"Warstwa empiryczna to obserwacja znaków i kanał dostępu (interfejs użytkownika), nie „wiedza z doświadczenia”; pytanie „jak uzyskać dostęp?” wskazuje właśnie ją."},"il36_w_fizyczny":{"kw":["warstwa fizyczna","fizycznej","nośnik"],"pulapka":"Warstwa fizyczna odpowiada na pytanie „gdzie informacje są przechowywane”; „jak uzyskać dostęp” to już warstwa empiryczna."},"il36_w_pragmatyczny":{"kw":["warstwa pragmatyczna","pragmatyczn"],"pulapka":"Warstwa pragmatyczna to sposób wykorzystania: okres przechowywania, status, innowacyjność, zależność; pytanie o wymogi przechowywania wskazuje ją, a nie warstwę fizyczną."},"il36_w_semantyczny":{"kw":["warstwa semantyczna","semantyczn"],"pulapka":"Warstwa semantyczna to znaczenie oraz atrybuty: typ, aktualność i poziom; „aktualność” oznacza tu horyzont czasowy, nie cel jakości kontekstowej."},"il36_w_spoleczny":{"kw":["społeczn","warstwa świata społecznego"],"pulapka":"Warstwa świata społecznego (umowy, prawo, kultura) to warstwa atrybutów, nie kategoria jakości; „kontekst” tej warstwy to nie jakość kontekstowa."},"il36_w_syntaktyczny":{"kw":["syntaktyczn","format"],"pulapka":"Warstwa syntaktyczna dotyczy formy (język, format); gdy znaczenie jest to samo, a różni się zapis, to nie jest warstwa semantyczna."},"il37_c_aplikacje":{"kw":["infrastruktura","aplikacje"],"pulapka":"Na Rysunku 37 aplikacje, infrastruktura, technologia i poziomy usług to przedmiot celów tego aktywatora, wpisany przy jakości kontekstowej, a nie osobne aktywatory."},"il37_cele":{"kw":["zdolność usługowa","poziomy usług"],"pulapka":"Cele to usługi i poziomy usług najbardziej ekonomiczne dla przedsiębiorstwa oraz wkład we wspieranie procesów biznesowych, a nie technika dla niej samej."},"il37_cykl":{"kw":["architektura referencyjna","architektura przejściowa","architektura docelowa"],"pulapka":"Stan bieżący opisuje architektura referencyjna (bazowa), przyszły docelowa, etapy pośrednie przejściowa; „referencyjna” kusi jako „wzorcowa”, ale oznacza stan obecny."},"il37_dobre":{"kw":["togaf","itil","sfia"],"pulapka":"Zewnętrzne dobre praktyki tego aktywatora to TOGAF (techniczny model referencyjny) i ITIL (projektowanie i wykonywanie usług); SFIA należy do aktywatora Ludzie, umiejętności i kompetencje."},"il37_dp_poziomy_uslug":{"kw":["poziomy usług","apo09"],"pulapka":"Tu poziomy usług są dobrą praktyką aktywatora Usługi, infrastruktura i aplikacje; jako proces uzgadnia je APO09, a dostawców pilnuje APO10."},"il37_dp_pryncypia":{"kw":["pryncypium","zasady architektury"],"pulapka":"Pryncypia architektury to ogólne wytyczne wdrażania i wykorzystania zasobów IT; nie myl ich z pięcioma zasadami COBIT 5 ani z aktywatorem Zasady, polityki i struktury ramowe."},"il37_dp_punkty_widzenia":{"kw":["punkty widzenia","punktów widzenia"],"pulapka":"Definiowanie punktów widzenia architektury to dobra praktyka. Modele, katalogi i macierze dobrane do interesariuszy opisują architekturę bazową, docelową lub przejściową; ich konkretne opracowania są wynikami pracy, więc nie wykluczaj ogólnie słowa „produkt”."},"il37_interesariusze":{"kw":["usługi, infrastruktura i aplikacje","zdolność usługowa"],"pulapka":"Interesariuszami są i dostawcy usług (dział IT, operacje, outsourcing), i użytkownicy: wewnętrzni (biznes) oraz zewnętrzni (partnerzy, klienci, dostawcy)."},"il37_pa_nabywanie":{"kw":["nabywanie lub samodzielne tworzenie","kupić czy zbudować"],"pulapka":"Domyślnie się kupuje, a własne tworzenie wymaga zatwierdzonego powodu; podchwytliwa wersja odwraca regułę i każe budować, chyba że zakup jest uzasadniony."},"il37_pa_otwartosc":{"kw":["otwartość","otwartych standardach"],"pulapka":"Otwartość to oparcie architektury na otwartych standardach branżowych; nie chodzi o jawność informacji ani przejrzystość wobec interesariuszy (EDM05)."},"il37_pa_ponowne":{"kw":["ponowne wykorzystanie","pryncypium"],"pulapka":"Ponowne wykorzystanie dotyczy wspólnych komponentów, które organizacja już ma; wybór „kupić czy zbudować” to osobne pryncypium Nabywanie lub samodzielne tworzenie."},"il37_pa_prostota":{"kw":["prostota","pryncypium"],"pulapka":"Prostota to architektura możliwie najprostsza, ale nadal spełniająca wymagania przedsiębiorstwa; nie oznacza obcinania funkcji poniżej potrzeb."},"il37_pa_zwinnosc":{"kw":["zwinność","pryncypium"],"pulapka":"Zwinność to skuteczna i wydajna odpowiedź architektury na zmieniające się potrzeby biznesu; nie myl z otwartością, która dotyczy standardów branżowych."},"il37_pr_architektura":{"kw":["architektura docelowa","architektura referencyjna","architektura przejściowa"],"pulapka":"Architektura docelowa, przejściowa i referencyjna to produkty działań (wyniki) tego aktywatora; referencyjna oznacza stan bieżący, nie wzorzec."},"il37_pr_repozytorium":{"kw":["repozytorium","produkty działań"],"pulapka":"Repozytorium referencyjne (architektury) to produkt działań, czyli miejsce na pryncypia, normy i modele; nie jest planem etapu przejściowego ani repozytorium konfiguracji z BAI10."},"il37_rep_aplikacje":{"kw":["aplikacje","repozytorium"],"pulapka":"Aplikacje zapewniające funkcjonalność biznesową to jeden z trzech elementów usług w repozytorium, obok infrastruktury technicznej i fizycznej, a nie osobny aktywator."},"il37_rep_infra_fiz":{"kw":["infrastruktura fizyczna","fizyczn","infrastruktura"],"pulapka":"Infrastruktura fizyczna (budynki, pomieszczenia) to trzeci, osobny element usług w repozytorium architektury, obok aplikacji i infrastruktury technicznej."},"il37_rep_infra_techn":{"kw":["infrastruktura techniczna","infrastruktura"],"pulapka":"Infrastruktura techniczna obejmuje sprzęt, oprogramowanie systemowe i sieć; repozytorium wymienia osobno infrastrukturę fizyczną, więc tych dwóch nie łącz."},"il38_c_behawioralne":{"kw":["umiejętności behawioralne","kultura, etyka"],"pulapka":"Umiejętności behawioralne (jakość kontekstowa) łączą ten aktywator z aktywatorem Kultura, etyka i zachowanie; to nie są umiejętności techniczne."},"il38_c_dostepnosc":{"kw":["dostępność","jakość kontekstowa"],"pulapka":"Dostępność personelu to cel w jakości kontekstowej; nie myl jej z kategorią celów „dostęp i bezpieczeństwo”, choć brzmi podobnie."},"il38_c_doswiadczenie":{"kw":["doświadczenie","jakość kontekstowa"],"pulapka":"Doświadczenie jest w jakości kontekstowej; do wewnętrznej należą tylko wykształcenie, kwalifikacje i umiejętności techniczne."},"il38_c_rotacja":{"kw":["rotacja","jakość kontekstowa"],"pulapka":"Wskaźnik rotacji to cel aktywatora w jakości kontekstowej; utrata wiedzy po odejściu eksperta to temat BAI08, a braki kadrowe APO07."},"il38_c_techniczne":{"kw":["umiejętności techniczne","jakość wewnętrzna"],"pulapka":"Umiejętności techniczne są w jakości wewnętrznej razem z wykształceniem; umiejętności behawioralne należą już do jakości kontekstowej."},"il38_c_wiedza":{"kw":["wiedza","jakość kontekstowa"],"pulapka":"Wiedza to cel w jakości kontekstowej Rysunku 38; nie myl jej z procesem BAI08 Zarządzanie wiedzą ani z aktywatorem Informacja."},"il38_c_wyksztalcenie":{"kw":["wykształcenie i kwalifikacje","jakość wewnętrzna"],"pulapka":"Na Rysunku 38 wykształcenie i kwalifikacje należą do jakości wewnętrznej (podręcznik: rzeczywistej), a nie do kontekstowej."},"il38_cele":{"kw":["rotacja","dostępność personelu"],"pulapka":"Cele to nie tylko kwalifikacje i umiejętności, ale też dostępność personelu i wskaźnik rotacji; to cele aktywatora, a nie proces APO07."},"il38_cykl":{"kw":["cykl życia","umiejętności"],"pulapka":"Cykl życia umiejętności obejmuje też pozbycie się ich, np. po automatyzacji lub outsourcingu; bazę umiejętności ocenia się okresowo, np. raz w roku."},"il38_dobre":{"kw":["sfia","definicje umiejętności"],"pulapka":"Zewnętrzną dobrą praktyką tego aktywatora jest SFIA (definicje umiejętności); TOGAF i ITIL należą do aktywatora Usługi, infrastruktura i aplikacje."},"il38_dp_kategorie":{"kw":["kategorie umiejętności","analiza biznesowa"],"pulapka":"Kategorie umiejętności odnoszą się do działań IT, a Rysunek 39 przypisuje je do domen, np. analiza biznesowa do BAI, audyt mechanizmów kontrolnych do MEA."},"il38_dp_poziomy":{"kw":["poziomy umiejętności","umiejętności"],"pulapka":"Poziomy umiejętności opisuje się w poszczególnych kategoriach umiejętności; nie myl ich z poziomami zdolności procesu 0–5 z Rysunku 19."},"il38_dp_sfia":{"kw":["sfia","definicji umiejętności"],"pulapka":"SFIA (Skills Framework for the Information Age) to zewnętrzne źródło definicji umiejętności; nie jest modelem referencyjnym procesów ani modelem architektury (TOGAF)."},"il38_dp_wymagane":{"kw":["zestawy umiejętności","umiejętności"],"pulapka":"Dobra praktyka to obiektywne zestawy umiejętności dla każdej roli różnych interesariuszy, a nie jeden wspólny zestaw dla całej organizacji."},"il38_interesariusze":{"kw":["ludzie, umiejętności i kompetencje","umiejętności"],"pulapka":"Wśród interesariuszy są też konkurenci, rekruterzy i szkoleniowcy; każda rola wymaga osobnego zestawu umiejętności, nie ma jednego zestawu dla wszystkich."},"il38_pr_definicje":{"kw":["definicje umiejętności","produkt"],"pulapka":"Definicje umiejętności to produkt działań tego aktywatora; same są też informacjami, więc stosuje się do nich dobre praktyki aktywatora Informacja."},"il39_apo":{"kw":["apo","dostosuj, planuj i organizuj","portfel"],"pulapka":"Egzaminowa nazwa APO to „Dostosuj, Planuj i Organizuj”; jej kategorie to polityka, strategia, architektura, innowacje, finanse i portfele, ale nie pojedyncze projekty (to BAI)."},"il39_apo_architektura_korporacyjna":{"kw":["architektura korporacyjna","apo03"],"pulapka":"Architektura korporacyjna to kategoria APO (proces APO03), nie BAI; BAI w Rysunku 39 ma m.in. analizę biznesową i programowanie."},"il39_apo_innowacje":{"kw":["innowacj","apo04"],"pulapka":"Innowacje należą w Rysunku 39 do APO (proces APO04), nie do BAI; dystraktor wstawia je do zestawu „analiza biznesowa, innowacje, programowanie” jako rzekomo całego BAI."},"il39_apo_opracowanie_polityki_it":{"kw":["opracowanie polityki it","rysunek 39"],"pulapka":"To kategoria umiejętności domeny APO (Rysunek 39), nie EDM; same polityki należą do aktywatora Zasady, Polityki i Struktury ramowe, ale umiejętność ich pisania to APO."},"il39_apo_strategia_it":{"kw":["strategia it","apo02"],"pulapka":"Strategia IT należy w Rysunku 39 do APO, nie do EDM; Ład zatwierdza kierunek, a układanie strategii (stan obecny, docelowy, luka, mapa drogowa) to APO02."},"il39_apo_zarzadzanie_finansowe":{"kw":["zarządzanie finansowe","apo06"],"pulapka":"Zarządzanie finansowe to kategoria APO (budżet i koszty to APO06), nie EDM; EDM04 decyduje o zasobach na poziomie Ładu, ale nie prowadzi budżetu."},"il39_apo_zarzadzanie_portfelami_projektow":{"kw":["portfel","zarządzanie portfelami projektów","apo05"],"pulapka":"Portfele projektów (które projekty w ogóle robimy) to APO, a zarządzanie pojedynczymi projektami (jak dowieźć jeden) to BAI; Rysunek 39 rozdziela te podobne nazwy."},"il39_bai":{"kw":["bai","twórz, nabywaj i wdrażaj","pojemności"],"pulapka":"Egzaminowa nazwa BAI to „Twórz, Nabywaj i Wdrażaj” (podręcznik: Budowanie, nabywanie i wdrażanie); w Rysunku 39 tu jest zarządzanie pojemnością, a dostępnością już w DSS."},"il39_bai_analiza_biznesowa":{"kw":["analiza biznesowa","analizy biznesowej"],"pulapka":"W przykładowym przypisaniu kategorii umiejętności na Rysunku 39 analiza biznesowa jest w BAI. Nie znaczy to, że analizy biznesowej nie można stosować w procesach APO lub innych domen."},"il39_bai_definiowanie_wymagan_i":{"kw":["definiowanie wymagań","bai02"],"pulapka":"Definiowanie wymagań i zarządzanie nimi to kategoria BAI (proces BAI02), nie DSS ani APO; przyporządkowanie „definiowanie wymagań – DSS” to błędny dystraktor."},"il39_bai_ergonomia_systemu":{"kw":["ergonomia systemu","ergonomi"],"pulapka":"Ergonomia systemu należy do BAI; zestaw „analiza biznesowa, programowanie, ergonomia systemu” to w całości BAI, a dystraktory dorzucają innowacje (APO) albo eksploatację IT (DSS)."},"il39_bai_ocena_uzytecznosci":{"kw":["ocena użyteczności","użyteczności"],"pulapka":"Ocena użyteczności należy do BAI; słowa „oceń” w nazwie MEA i „oszacuj” w EDM kuszą, ale Rysunek 39 przypisuje ją do budowania rozwiązań."},"il39_bai_programowanie":{"kw":["programowanie","rysunek 39"],"pulapka":"Programowanie to kategoria domeny BAI (budowa rozwiązań), nie DSS; DSS ma eksploatację IT i administrowanie bazami danych, czyli obsługę działających systemów."},"il39_bai_wycofanie_oprogramowania_z":{"kw":["wycofanie oprogramowania","rysunek 39"],"pulapka":"Wycofanie oprogramowania z użycia należy do BAI, nie do DSS, choć brzmi jak koniec eksploatacji; w pytaniu „która nie należy do DSS” to ono jest odpowiedzią."},"il39_bai_zarzadzanie_pojemnoscia":{"kw":["pojemności","zarządzanie pojemnością","bai04"],"pulapka":"Rysunek 39 przypisuje kategorię umiejętności Zarządzanie pojemnością do BAI, a Zarządzanie dostępnością do DSS. To tabela kategorii umiejętności; proces BAI04 w PRM obejmuje zarządzanie zarówno dostępnością, jak i pojemnością."},"il39_bai_zarzadzanie_projektami":{"kw":["zarządzanie projektami","bai01"],"pulapka":"Zarządzanie projektami to BAI (proces BAI01), a portfelami projektów APO; przyporządkowanie „zarządzanie projektami – APO” to typowy błędny dystraktor."},"il39_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"Egzaminowa nazwa DSS to „Dostarczaj, Obsługuj i Wspieraj”; w Rysunku 39 są tu dostępność, problemy, Service Desk, bezpieczeństwo, eksploatacja i bazy danych, ale nie wycofanie oprogramowania (BAI)."},"il39_dss_administracja_bezpieczenstwa":{"kw":["administracja bezpieczeństwa","dss05"],"pulapka":"Administracja bezpieczeństwa (konta, uprawnienia) to DSS, nie APO ani MEA; MEA ma audyt mechanizmów kontrolnych, czyli sprawdzanie, a nie codzienne nadawanie dostępów."},"il39_dss_administrowanie_bazami_danych":{"kw":["bazami danych","rysunek 39"],"pulapka":"Administrowanie bazami danych to DSS, nie BAI: BAI buduje rozwiązania, a bazami działających systemów administruje się w codziennej obsłudze."},"il39_dss_eksploatacja_it":{"kw":["eksploatacja it","dss01"],"pulapka":"Eksploatacja IT to DSS (codzienna obsługa, proces DSS01), nie BAI; zestaw „programowanie, eksploatacja IT, ocena użyteczności” nie jest więc w całości BAI."},"il39_dss_zarzadzanie_dostepnoscia":{"kw":["dostępności","zarządzanie dostępnością"],"pulapka":"W tabeli kategorii umiejętności (Rysunek 39) dostępność jest przypisana do DSS. W modelu procesów BAI04 obejmuje jednak dostępność i pojemność. Rozróżnij pytanie o kategorię z rysunku od pytania o proces PRM."},"il39_dss_zarzadzanie_jednostka_service":{"kw":["service desk","incydent","dss02"],"pulapka":"To kategoria DSS (proces DSS02): incydent to szybkie przywrócenie usługi; szukanie przyczyny to zarządzanie problemami, też w DSS."},"il39_dss_zarzadzanie_problemami":{"kw":["zarządzanie problemami","dss03"],"pulapka":"Zarządzanie problemami to DSS (proces DSS03): szukanie przyczyny powtarzających się incydentów; szybkie przywrócenie działania to Service Desk i incydenty (DSS02)."},"il39_edm":{"kw":["edm","ład nad it","oszacuj, kieruj i monitoruj"],"pulapka":"Na egzaminie EDM to „Oszacuj, Kieruj i Monitoruj” (podręcznik: Ocena, kierowanie i monitorowanie); to jedyna domena Ładu i w Rysunku 39 ma tylko jedną kategorię umiejętności."},"il39_edm_nadzor_nad_technologiami":{"kw":["ład nad it","nadzór nad technologiami","rysunek 39"],"pulapka":"Na egzaminie to „Ład nad IT w organizacji” (podręcznik: nadzór); to jedyna kategoria EDM, a „monitorowanie sprawności” mimo słowa „monitoruj” należy do MEA."},"il39_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"Egzaminowa nazwa MEA to „Monitoruj, Oszacuj i Oceń” (podręcznik: Monitorowanie, ocena i oszacowanie); to domena Zarządzania, nie Ładu, choć EDM też „monitoruje”."},"il39_mea_audyt_mechanizmow_kontrolnych":{"kw":["audyt mechanizmów","mea02"],"pulapka":"Audyt mechanizmów kontrolnych to MEA (kontrola wewnętrzna, proces MEA02), nie DSS; DSS na co dzień obsługuje zabezpieczenia, a MEA sprawdza, czy działają."},"il39_mea_monitorowanie_sprawnosci":{"kw":["monitorowanie sprawności","mea01"],"pulapka":"Monitorowanie sprawności (wydajności) to MEA, nie EDM; EDM też monitoruje, ale jego jedyna kategoria w Rysunku 39 to Ład nad IT."},"il39_mea_weryfikacja_zgodnosci":{"kw":["weryfikacja zgodności","mea03"],"pulapka":"Weryfikacja zgodności należy w Rysunku 39 do MEA, nie do APO ani EDM; ocena zgodności z wymogami zewnętrznymi to proces MEA03."},"il7_audyt_wew":{"kw":["audyt wewnętrzny","audytorzy zewnętrzni"],"pulapka":"Pułapka nazwy: audyt wewnętrzny jest interesariuszem wewnętrznym, choć kontroluje innych; po stronie zewnętrznej są audytorzy zewnętrzni."},"il7_audytorzy_zew":{"kw":["audytorzy zewnętrzni","audyt zewnętrzny","zdarzenie wyzwalające"],"pulapka":"Audytorzy zewnętrzni są zewnętrzni, audyt wewnętrzny wewnętrzny; audyt zewnętrzny lub ocena konsultantów to też przykład zdarzenia wyzwalającego wdrożenie (s. 37)."},"il7_ceo":{"kw":["ceo","dyrektor generalny"],"pulapka":"CEO kieruje Zarządzaniem (kadrą kierowniczą), a nie Ładem; Ład to zarząd z prezesem na czele (s. 31)."},"il7_cfo":{"kw":["cfo","dyrektor finansowy","koszty it"],"pulapka":"CFO to interesariusz wewnętrzny; jego typowe pytanie „Jak kontrolować koszty IT?” jest wejściem Kaskady Celów, a nie wskaźnikiem KPI ani celem aktywatora."},"il7_cio":{"kw":["cio","komitet ds. strategii","strategii it"],"pulapka":"CIO dopasowuje strategię IT do strategii biznesowej (Ilustracja 33), ale komitetowi ds. strategii IT przewodniczy zwykle członek zarządu, nie CIO."},"il7_cro":{"kw":["cro","dyrektor ds. ryzyka","ryzyk"],"pulapka":"CRO odpowiada za zarządzanie ryzykiem w całym przedsiębiorstwie (Ilustracja 33); za bezpieczeństwo informacji odpowiada CISO, nie zamieniaj tych ról."},"il7_dostawcy":{"kw":["dostawca chmury","dostawc"],"pulapka":"Dostawca, np. chmury, to osobna firma, więc interesariusz zewnętrzny; częsty błąd w pytaniach typu „który wpis zakwalifikowano błędnie”."},"il7_dyr_prywatnosc":{"kw":["prywatno","ochron","danych osobowych"],"pulapka":"Dyrektorzy ds. prywatności to interesariusze wewnętrzni; nie myl ich z organami nadzorczymi ds. ochrony danych, które na Rysunku 7 są zewnętrzne."},"il7_int_wew":{"kw":["interesariusz wewnętrzn","interesariuszem wewnętrznym","rysunek 7"],"pulapka":"Wewnętrzni to też audyt wewnętrzny i użytkownicy IT; udziałowcy, dostawcy i konsultanci są na Rysunku 7 po stronie zewnętrznej."},"il7_int_zew":{"kw":["interesariusz zewnętrzn","interesariuszem zewnętrznym","interesariuszy zewnętrznych"],"pulapka":"Udziałowcy, dostawcy i konsultanci są zewnętrzni, mimo bliskich związków z firmą; własność nie przesądza o grupie na Rysunku 7."},"il7_itd_wew":{"kw":["interesariusz","rysunek 7"],"pulapka":"„Itd.” znaczy, że lista interesariuszy wewnętrznych jest przykładowa, a nie zamknięta; nie ucz się jej jako kompletnego katalogu ról COBIT 5."},"il7_itd_zew":{"kw":["organy regulacyjne","interesariusz"],"pulapka":"Lista zewnętrznych jest przykładowa („itd.”); przy interesariuszach procesu podręcznik wymienia np. klientów, partnerów, udziałowców i organy regulacyjne (s. 69)."},"il7_kier_bezp":{"kw":["ciso","bezpieczeństw"],"pulapka":"Kierownik ds. bezpieczeństwa (np. CISO) to rola wewnętrzna; CRO odpowiada szerzej, za ryzyko całego przedsiębiorstwa, a nie tylko za bezpieczeństwo informacji."},"il7_kier_hr":{"kw":["zasobami ludzkimi","wynagradza","zachęty"],"pulapka":"HR jest na Rysunku 7 interesariuszem wewnętrznym. Przy Kulturze, etyce i zachowaniu system wynagradzania wiąże HR z zachętami i nagrodami; nie oznacza to wykluczenia HR z ustalania reguł lub innych praktyk."},"il7_kier_it":{"kw":["kierownik it","zasada 2","całe przedsiębiorstwo"],"pulapka":"Kierownicy ds. IT to tylko jedna z wielu grup; COBIT 5 obejmuje całe przedsiębiorstwo (Zasada 2), więc pytania o IT zadają też CFO, HR czy audyt."},"il7_kier_obszaru_biz":{"kw":["kierownicy obszaru biznesowego","interesariusz wewnętrzn","partner"],"pulapka":"Kierownicy obszaru biznesowego to interesariusze wewnętrzni; nie myl ich z partnerami biznesowymi, którzy na Rysunku 7 stoją po stronie zewnętrznej."},"il7_kier_ryzyko":{"kw":["kierownicy ds. ryzyka","ryzyk"],"pulapka":"Na Rysunku 7 są po prostu wewnętrzni; na Rysunku 34 kierownicy ds. ryzyka to przykład tych, którzy definiują i egzekwują pożądane zachowania."},"il7_kier_uslugi":{"kw":["apo09","poziom usług","poziomy usług"],"pulapka":"Kierownicy ds. usług są wewnętrzni; umowy o poziomie usług obsługuje APO09, ale samo pytanie o jakość usług to potrzeba interesariusza."},"il7_klienci":{"kw":["klienci","klient"],"pulapka":"Klienci są interesariuszami zewnętrznymi; „Kultura usług zorientowanych na klienta” to już cel organizacji, a nie grupa interesariuszy."},"il7_konsultanci":{"kw":["konsultan","raci"],"pulapka":"Konsultanci z Rysunku 7 to interesariusze zewnętrzni; nie myl ich z rolą C (konsultowany) w tabeli RACI, która opisuje udział w praktyce procesu."},"il7_naczelne_kier":{"kw":["naczelne kierownictwo","kierownictwa wyższego szczebla","kadra kierownicza"],"pulapka":"Członek naczelnego kierownictwa odpowiada za jednostkę biznesową lub spółkę zależną (Ilustracja 33); to interesariusz wewnętrzny, a nie organ Ładu."},"il7_org_normalizacyjne":{"kw":["iso","itil","norm"],"pulapka":"Organizacje normalizacyjne (np. ISO) są zewnętrzne; COBIT 5 dopasowuje się do norm i dobrych praktyk (ISO, ITIL, TOGAF), ale ich nie zastępuje."},"il7_organy_nadzorcze":{"kw":["organy nadzor","organ nadzoru","regulator"],"pulapka":"Organy nadzorcze i rządowe są zewnętrzne; na Rysunku 34 wraz z audytorami zewnętrznymi są przykładem zewnętrznych interesariuszy Kultury, etyki i zachowania."},"il7_partnerzy":{"kw":["partnerzy biznesowi","partner"],"pulapka":"Partnerzy biznesowi są zewnętrzni, a kierownicy obszaru biznesowego wewnętrzni; firma kurierska na umowie to partner, nie udziałowiec."},"il7_pyt_wew":{"kw":["załącznik d","dane wejściowe","kaskad"],"pulapka":"Załącznik D (Ilustracja 24) mapuje potrzeby interesariuszy wewnętrznych na cele organizacji; Załącznik B to cele organizacji → cele IT, a C – cele IT → procesy."},"il7_pyt_zew":{"kw":["pytania interesariuszy","kaskad","załącznik d"],"pulapka":"Pytań zewnętrznych na Rysunku 7 są tylko cztery i też zasilają Kaskadę Celów; Załącznik D (Ilustracja 24) mapuje jednak potrzeby interesariuszy wewnętrznych."},"il7_q_audyt":{"kw":["przewodnik specjalistyczny","audyt","mea02"],"pulapka":"Dla audytora COBIT 5 ma przewodnik specjalistyczny (COBIT 5: Audyt), a nie przewodnik aktywatora; samo pytanie zadaje interesariusz wewnętrzny."},"il7_q_budzet":{"kw":["budżet","punkt zapalny"],"pulapka":"Zmiany „z opóźnieniem lub ponad budżet” podręcznik wymienia też jako punkt zapalny (s. 37); nie myl punktu zapalnego ze zdarzeniem wyzwalającym, np. nowym CFO."},"il7_q_ciaglosc":{"kw":["dss04","ciągłoś"],"pulapka":"„Ciągłość i dostępność usług biznesowych” to cel organizacji (Ilustracja 5), a nie wyznacznik; ciągłością działania zarządza proces DSS04."},"il7_q_decyzje":{"kw":["procedury eskalacji","poziom uprawnień","decyzj"],"pulapka":"Szybkość decyzji wspierają praktyki Struktur organizacyjnych: poziom uprawnień, delegowanie i procedury eskalacji; samo pytanie to wejście kaskady z Rysunku 7."},"il7_q_dostawcy":{"kw":["apo10","dostawc","outsourcing"],"pulapka":"To pytanie zadaje interesariusz wewnętrzny; sami dostawcy (także dostawca chmury) są na Rysunku 7 interesariuszami zewnętrznymi."},"il7_q_kadry":{"kw":["apo07","umiejętności"],"pulapka":"Kadry i umiejętności to APO07 i aktywator Ludzie, umiejętności i kompetencje; „zasoby” w BAI09 to aktywa (sprzęt, licencje), a nie ludzie."},"il7_q_koszty":{"kw":["koszty it","apo06","kaskad"],"pulapka":"„Jak kontrolować koszty IT?” to potrzeba interesariusza, czyli wejście kaskady; nie jest celem aktywatora, wskaźnikiem wiodącym ani praktyką zarządzania."},"il7_q_nowe_techn":{"kw":["wyznacznik","nowa technologia","nowe technologie"],"pulapka":"Pojawienie się nowej technologii to wyznacznik (krok 1 Kaskady Celów), a pytanie, jak ją wykorzystać, to już potrzeba interesariusza (krok 2)."},"il7_q_operacje":{"kw":["dss01","operacj","kaskad"],"pulapka":"Pytania z Rysunku 7 to przykłady wejścia do Kaskady Celów, a nie lista obowiązkowych KPI; nie traktuj ich jak mierników procesów DSS."},"il7_q_procesy_biz":{"kw":["zasada 2","procesy biznesowe","od początku do końca"],"pulapka":"COBIT 5 obejmuje całe przedsiębiorstwo od początku do końca (Zasada 2), więc pytanie dotyczy procesów biznesowych, a nie tylko procesów działu IT."},"il7_q_projekty":{"kw":["bai01","punkt zapalny","punkty zapalne"],"pulapka":"Podobny problem (nieudane inicjatywy, niepowodzenie projektu) podręcznik wymienia też jako punkt zapalny wdrożenia (s. 36); tu to pytanie interesariusza z Rysunku 7."},"il7_q_reaktywnosc":{"kw":["załącznik d","proaktywn","reaktywn"],"pulapka":"Załącznik D wiąże to pytanie z celami przedsiębiorstwa. Dalej kaskada prowadzi do celów IT i aktywatorów; zestawienie nie zabrania rozważania bezpośrednich związków pytania z konkretnymi procesami."},"il7_q_ryzyko":{"kw":["apo12","edm03","apetyt na ryzyko"],"pulapka":"Optymalizacja ryzyka jest częścią tworzenia wartości (s. 17); apetyt na ryzyko ustalają struktury Ładu (Rysunek 14), a ryzykiem zarządza proces APO12."},"il7_q_sprawnosc":{"kw":["sprawnoś","wydajnoś","mea01"],"pulapka":"To pytanie interesariusza z Rysunku 7, a nie jedno z czterech pytań zarządzania wydajnością aktywatora (s. 29), np. „Czy osiągnięto cele aktywatora?”."},"il7_q_struktura_it":{"kw":["struktury organizacyjne","ilustracja 33","struktur"],"pulapka":"Role i struktury z Ilustracji 33 są tylko przykładowe; COBIT 5 nie narzuca uniwersalnej struktury działu IT dla każdego przedsiębiorstwa (s. 76)."},"il7_q_transparent":{"kw":["edm05","przejrzystoś"],"pulapka":"EDM05 zapewnia przejrzystość wobec interesariuszy na poziomie Ładu. Procesy MEA dostarczają pomiaru, oceny i raportowania, które mogą ją wspierać. Odróżnij EDM05 od celu przedsiębiorstwa Przejrzystość finansowa."},"il7_q_wartosc":{"kw":["tworzenie wartości","edm02","korzyści"],"pulapka":"Wartość w COBIT 5 wymaga równowagi korzyści, ryzyka i zasobów. Sama minimalizacja wydatków nie jest pełną definicją wartości; ograniczenie kosztów może być jednak uzasadnioną korzyścią danej inicjatywy."},"il7_q_wymogi_inf":{"kw":["jakość kontekstowa","załącznik f","kryteri"],"pulapka":"Wymogi wobec informacji opisuje aktywator Informacja (cele jakości: rzeczywista, kontekstowa, dostępność i bezpieczeństwo); Załącznik F tylko porównuje go z kryteriami COBIT 4.1."},"il7_q_zabezp":{"kw":["apo13","dss05","bezpieczeństwo informacji"],"pulapka":"APO13 dotyczy zarządzania bezpieczeństwem, a DSS05 usług bezpieczeństwa. Dostęp i Bezpieczeństwo w modelu informacji to kategoria celów w wymiarze Cele, nie odrębny aktywator ani dodatkowy wymiar."},"il7_q_zasoby_strat":{"kw":["edm04","infrastruktur","zasob"],"pulapka":"Infrastruktura należy do aktywatora Usługi, infrastruktura i aplikacje, a nie Ludzie; optymalne wykorzystanie zasobów zapewnia Ład w procesie EDM04."},"il7_q_zgodnosc":{"kw":["mea03","zgodnoś","regulac"],"pulapka":"To wersja wewnętrzna; zewnętrzna brzmi „Skąd wiadomo, że przedsiębiorstwo przestrzega przepisów?”. Zgodność zewnętrzną monitoruje MEA03, kontrolę wewnętrzną MEA02."},"il7_q_zwinnosc":{"kw":["zwinnoś","cele organizacji","cel organizacji"],"pulapka":"Nie myl pytania z celem organizacji „Zwinność w reagowaniu na zmieniające się otoczenie biznesowe” (Ilustracja 24); pytanie to potrzeba, cel jest poziom niżej."},"il7_qz_kontrola":{"kw":["mea02","kontroli wewnętrznej","system kontroli"],"pulapka":"Mimo słów „kontrola wewnętrzna” to pytanie interesariusza zewnętrznego; system kontroli wewnętrznej monitoruje MEA02, a zgodność zewnętrzną MEA03."},"il7_qz_lancuch":{"kw":["łańcuch","partner","informac"],"pulapka":"Dotyczy przepływu informacji między partnerami, a nie wewnątrz firmy; to jedno z zaledwie czterech pytań zewnętrznych na Rysunku 7."},"il7_qz_partner":{"kw":["wiarygodn","partner","chroni"],"pulapka":"To pytanie zadaje zewnętrzny partner o operacje przedsiębiorstwa; wersja wewnętrzna dotyczy własnych danych: „Czy informacje, które przetwarzam, są dobrze zabezpieczone?”."},"il7_qz_przepisy":{"kw":["zgodność z przepisami","mea03","przepis"],"pulapka":"To pytanie zewnętrzne (np. regulatora); wewnętrzne brzmi podobnie, ale pyta, czy IT ułatwia zgodność i jak samemu sprawdzić przestrzeganie regulacji."},"il7_udzialowcy":{"kw":["udziałowc","shareholder"],"pulapka":"Udziałowcy są na Rysunku 7 zewnętrzni, choć są właścicielami; nie myl też udziałowca (shareholder) z interesariuszem (stakeholder)."},"il7_uzytk_it":{"kw":["użytkownicy it","użytkownik"],"pulapka":"Rysunek 7 umieszcza grupę Użytkownicy IT wśród interesariuszy wewnętrznych, a Użytkowników zewnętrznych osobno. To przypisanie na tym rysunku; ogólne pojęcie użytkownika IT nie ogranicza się do pracowników."},"il7_uzytk_zew":{"kw":["użytkownicy zewnętrzni","użytkownik"],"pulapka":"Użytkownicy zewnętrzni są na Rysunku 7 odrębną grupą po stronie zewnętrznej. Oni również mogą korzystać z IT; nie ucz się fałszywej zasady, że każdy użytkownik IT musi być pracownikiem."},"il7_wlasc_proc_biz":{"kw":["właściciel procesu biznesowego","właściciele procesów biznesowych","właściciel procesu"],"pulapka":"Właściciel procesu biznesowego odpowiada za sprawność procesu i zatwierdza jego zmiany (Ilustracja 33); jest wewnętrzny i nie musi pracować w dziale IT."},"il7_zarzad":{"kw":["zarząd","organ ładu","edm"],"pulapka":"Za Ład odpowiada zwykle zarząd pod przywództwem prezesa, a za Zarządzanie kadra kierownicza pod CEO (s. 31); nie przypisuj zarządowi planowania i budowania."},"il8_cel_nadzoru":{"kw":["tworzenie wartości","cel ładu"],"pulapka":"Egzamin: Cel Ładu „Tworzenie Wartości”; to równowaga trzech celów, a nie maksymalizacja korzyści ani eliminacja ryzyka."},"il8_czynniki_nadzor":{"kw":["aktywatory ładu","podejścia do ładu"],"pulapka":"Egzamin: „Aktywatory Ładu” (podręcznik: czynniki umożliwiające nadzór); to komponent Podejścia do Ładu z Rysunku 8, nie wymiar aktywatora."},"il8_optym_ryzyka":{"kw":["optymalizacja ryzyka","apetyt na ryzyko"],"pulapka":"Optymalizacja ryzyka nie oznacza jego całkowitej eliminacji. Reakcje mogą obejmować unikanie, ograniczanie, dzielenie lub transfer oraz akceptację odpowiednio ocenionego ryzyka, w ramach ustalonego apetytu."},"il8_optym_zasobow":{"kw":["optymalizacja zasobów","optymalizacji zasobów"],"pulapka":"Optymalizacja zasobów dotyczy wszystkich zasobów (ludzie, finanse, sprzęt, infrastruktura), nie tylko budżetu; nie myl jej z celem IT 11."},"il8_realizacja_korzysci":{"kw":["realizacja korzyści","realizacji korzyści"],"pulapka":"Realizacja korzyści obejmuje też eliminowanie inicjatyw i zasobów bez wystarczającej wartości, a nie tylko tworzenie nowych korzyści."},"il8_role_dzial_rel":{"kw":["role, działania i relacje","delegowanie","rysunek 9"],"pulapka":"Rysunek 9: właściciele i interesariusze delegują; organ Ładu wyznacza kierunek; Zarządzanie instruuje i dopasowuje eksploatację, a eksploatacja raportuje do Zarządzania. Strzałka monitorowania biegnie od Zarządzania do organu Ładu. Sam Ład również obejmuje monitorowanie (FW-PL s. 31–32)."},"il8_zakres_nadzoru":{"kw":["zakres ładu","podejścia do ładu"],"pulapka":"Egzamin: „Zakres Ładu”: przedsiębiorstwo, jednostka lub aktywa, a zakres COBIT 5 obejmuje przedsiębiorstwo; to komponent podejścia, nie kategoria celów."},"il9_eksploatacja":{"kw":["eksploatacja","raportowan","ról operacyjnych"],"pulapka":"Rysunek 9 pokazuje instrukcje od Zarządzania do Eksploatacji i raportowanie w przeciwnym kierunku. Nie jest to zakaz innych uzasadnionych kanałów raportowania w rzeczywistej organizacji."},"il9_organ_nadzorujacy":{"kw":["organ nadzoruj","organ ładu","prezesa"],"pulapka":"Organ nadzorujący (board), kierowany przez przewodniczącego, wyznacza Zarządzaniu kierunek. W podręczniku PL board/chairman to „zarząd/prezes”. Rysunek 9 pokazuje instrukcje dla Eksploatacji od Zarządzania, a nie bezpośrednią strzałkę od organu Ładu."},"il9_role_dzial_rel":{"kw":["rysunku 9","role, działania i relacje"],"pulapka":"Rysunek 9 rozwija dolną część Rysunku 8; role, działania i relacje to jeden z elementów systemu Ładu, obok celu, aktywatorów i zakresu."},"il9_s_delegowanie":{"kw":["delegowan","rysunku 9"],"pulapka":"Na Rysunku 9 delegowanie płynie od właścicieli i interesariuszy do organu nadzorującego; w dobrych praktykach struktur „delegowanie uprawnień” to przekazanie decyzji w dół."},"il9_s_instruowanie":{"kw":["instruowanie","dopasowanie"],"pulapka":"Instruowanie i dopasowanie to relacja Zarządzania wobec eksploatacji i wykonania, a nie organu Ładu wobec Zarządzania (tam jest wyznaczanie kierunku)."},"il9_s_monitorowanie":{"kw":["monitorowani","rysunku 9","monitoruje"],"pulapka":"Ład monitoruje, na ile kierunek wcielono w życie; ale w pytaniach o role z Rysunku 9 egzamin PL przypisuje odpowiedzialność wykonawczą za monitorowanie kierownictwu. Czytaj, o co pyta treść."},"il9_s_raportowanie":{"kw":["raportowan","rysunku 9"],"pulapka":"Raportowanie na Rysunku 9 płynie od eksploatacji do Zarządzania; organ Ładu z Zarządzaniem łączy para: wyznaczanie kierunku i monitorowanie."},"il9_s_strona_rozliczana":{"kw":["strona rozliczana","odpowiedzialny decyzyjnie","rozliczan"],"pulapka":"Na Rysunku 9 strona rozliczana to organ nadzorujący wobec właścicieli; w RACI „strona rozliczana” to podręcznikowa nazwa roli A, na egzaminie: odpowiedzialny decyzyjnie."},"il9_s_wyznaczanie_kierunku":{"kw":["wyznaczanie kierunku","kierunek"],"pulapka":"Wyznaczanie kierunku łączy organ nadzorujący z Zarządzaniem; z eksploatacją łączy Zarządzanie inna relacja: instruowanie i dopasowanie."},"il9_wlasciciele":{"kw":["właściciele","delegowan","interesariusze"],"pulapka":"Rysunek 9 przedstawia delegowanie od właścicieli i interesariuszy do organu nadzorującego oraz jego rozliczalność wobec nich. Brak bezpośredniej strzałki z Eksploatacji nie oznacza zakazu otrzymywania raportów ani innych praw interesariuszy."},"il9_zarzadzanie":{"kw":["kadra zarządzająca","planowanie, budowanie","zarządzanie"],"pulapka":"Zarządzanie planuje, buduje, uruchamia i monitoruje zgodnie z kierunkiem Ładu; zwykle odpowiada za nie kierownictwo wykonawcze pod przywództwem CEO. Odróżniaj role board/chairman i management/CEO niezależnie od lokalnych nazw stanowisk."},"kask":{"kw":["kaskad","cele organizacji","cele związane z it"],"pulapka":"Kaskada idzie: wyznaczniki → potrzeby interesariuszy → cele organizacji → cele IT → cele aktywatorów; nie odwrotnie i bez pomijania celów IT."},"kont":{"kw":["kontekst","apetyt na ryzyko","styl zarządzania"],"pulapka":"Apetyt na ryzyko, styl zarządzania, etyka i kultura opisują kontekst dopasowania wdrożenia. W konkretnym scenariuszu ich zmiana może też stać się bodźcem do działania; rozróżniaj rolę faktu w pytaniu."},"lad":{"kw":["edm","oszacuj, kieruj","ład"],"pulapka":"W Referencyjnym Modelu Procesu pięć procesów Ładu należy do domeny EDM: Oszacuj, Kieruj i Monitoruj. Ład wykorzystuje jednak wszystkie siedem aktywatorów, nie same procesy. MEA należy do Zarządzania."},"lv0":{"kw":["niekompletny","poziom 0"],"pulapka":"Poziom 0 to proces niewdrożony lub nieosiągający celu, nawet gdy coś się robi; „całkowity brak rozpoznawalnych procesów” to poziom 0 dojrzałości COBIT 4.1."},"lv1":{"kw":["pa 1.1","wykonywany","wykonanie procesu"],"pulapka":"Poziom 1 wymaga PA 1.1 co najmniej W; „wykonywany” nie znaczy „ktoś coś robi”, tylko „proces osiąga cel”. Podręcznik nazywa PA 1.1 „sprawnością procesu”."},"lv2":{"kw":["pa 2.1","pa 2.2","zarządzany"],"pulapka":"Poziom 2 wymaga zarządzania wykonaniem i produktami pracy (PA 2.1 i PA 2.2), przy PA 1.1 w pełni osiągniętym. Samo spisanie wspólnej procedury nie dowodzi poziomu 3: potrzebne są PA 3.1 i PA 3.2 oraz pełne osiągnięcie niższych atrybutów."},"lv3":{"kw":["pa 3.1","pa 3.2","ustanowiony"],"pulapka":"Poziom 3 wymaga zdefiniowania i wdrożenia procesu (PA 3.1 i PA 3.2), z pełnym osiągnięciem niższych atrybutów. Standard można dostosowywać według reguł; nie oznacza to identycznego wykonania każdej czynności."},"lv4":{"kw":["pa 4.1","pa 4.2","przewidywalny"],"pulapka":"Atrybuty poziomu 4 to Miara procesu (PA 4.1) i Kontrola procesu (PA 4.2); Innowacja to poziom 5, a Zarządzanie wydajnością – poziom 2 (pułapka z Sample Paper)."},"lv5":{"kw":["pa 5.1","pa 5.2","zoptymalizowany"],"pulapka":"Egzamin PL mówi „proces zoptymalizowany”, podręcznik „optymalizujący”; „Zoptymalizowane” to też poziom 5 dojrzałości COBIT 4.1, więc nie myl modeli."},"mier1":{"kw":["opóźnion","następując"],"pulapka":"Wskaźniki opóźnione (podręcznik: następujące, mierniki realizacji celów) odpowiadają na pytania o interesariuszy i cele; zamiana pary wiodący–opóźniony to typowy dystraktor."},"mier2":{"kw":["wiodąc","wyprzedzając"],"pulapka":"W modelu aktywatora wskaźniki wiodące oceniają zarządzanie cyklem życia i stosowanie dobrych praktyk. Rodzaj wskaźnika zależy od jego relacji z celem, nie od okresu raportowania. Ta sama miara może być wynikiem jednego działania i zapowiedzią innego."},"obecny":{"kw":["gdzie jesteśmy","stan obecn","faza 2"],"pulapka":"Stan obecny i potencjał procesów ocenia się w fazie 2 („Gdzie jesteśmy teraz?”); punkty zapalne rozpoznaje faza 1, a poziom docelowy (rzadko najwyższy) wybiera faza 3."},"ocena":{"kw":["wymiar procesu","wymiar zdolności","15504"],"pulapka":"Wymiar procesu pomaga ocenić osiąganie przeznaczenia przez rezultaty, praktyki bazowe i produkty pracy. Wymiar zdolności obejmuje PA 1.1–5.2, a więc również poziom 1, nie tylko 2–5. Reguła poziomu uwzględnia wymagania wszystkich niższych atrybutów."},"papo01":{"kw":["apo01","metodyką zarządzania"],"pulapka":"APO01 organizuje system Zarządzania IT (role, procesy, polityki); ustanowienie systemu Ładu to EDM01, a „metodyka” nie oznacza metodyki projektowej (BAI01)."},"papo02":{"kw":["apo02","zarządzanie strategią"],"pulapka":"APO02 opracowuje strategię IT po stronie Zarządzania (stan docelowy, luka, mapa drogowa); ocena i zmiana kierunku przez zarząd to Ład, czyli EDM."},"papo03":{"kw":["apo03","architektur"],"pulapka":"APO03 opisuje i rozwija architekturę (biznes, informacje, aplikacje, technologia); spis konkretnych elementów i ich wersji to BAI10 Zarządzanie konfiguracją."},"papo04":{"kw":["apo04","innowacj"],"pulapka":"APO04 śledzi nowości i prowadzi pilotaże; wybór i finansowanie konkretnych pomysłów z ograniczonej puli pieniędzy to już APO05 Zarządzanie portfelem."},"papo05":{"kw":["apo05","portfel"],"pulapka":"APO05 dobiera i równoważy programy, projekty i usługi; prowadzenie pojedynczego projektu to BAI01, a ustalanie zasad optymalizacji wartości przez Ład to EDM02."},"papo06":{"kw":["apo06","budżet"],"pulapka":"APO06 planuje budżet IT i kontroluje koszty; ewidencja sprzętu i licencji to BAI09, a wybór inwestycji APO05."},"papo07":{"kw":["apo07","zasobami ludzkimi"],"pulapka":"Słowo „zasoby” kusi: APO07 dotyczy tylko ludzi i ich kompetencji; zasady dla wszystkich zasobów ustala Ład w EDM04."},"papo08":{"kw":["apo08","relacj"],"pulapka":"APO08 rozwija relacje i wspólne rozumienie potrzeb między IT a biznesem. APO10 zajmuje się zarządzaniem dostawcami, a APO09 usługami i ich uzgodnionymi poziomami. O rozpoznaniu decyduje cel relacji, nie samo słowo zewnętrzny."},"papo09":{"kw":["apo09","umowami o świadczenie usług","poziom usług"],"pulapka":"APO09 identyfikuje i uzgadnia usługi oraz poziomy usług z odbiorcami, a potem je monitoruje i przegląda. APO10 zarządza relacjami i kontraktami z dostawcami, które mogą wspierać te uzgodnienia. Nie klasyfikuj wyłącznie według wewnętrzny lub zewnętrzny."},"papo10":{"kw":["apo10","dostawc"],"pulapka":"APO10 obejmuje wybór, kontrakty i ocenę dostawców. APO09 uzgadnia oraz przegląda poziomy usług odpowiadające potrzebom odbiorców; kontrakty dostawców mogą wspierać te uzgodnienia."},"papo11":{"kw":["apo11","jakości"],"pulapka":"APO11 ustala standardy jakości i doskonali procesy; raport mierników dla zarządu to MEA01, a obsługa pojedynczego zgłoszenia DSS02."},"papo12":{"kw":["apo12","zarządzanie ryzykiem"],"pulapka":"APO12 identyfikuje, analizuje i obsługuje ryzyko po stronie Zarządzania; ustalenie apetytu na ryzyko i nadzór nad nim przez zarząd to EDM03."},"papo13":{"kw":["apo13"],"pulapka":"APO13 organizuje system zarządzania bezpieczeństwem informacji; codzienną ochronę, np. blokowanie kont, wykonuje DSS05."},"pbai01":{"kw":["bai01","programami i projektami"],"pulapka":"BAI01 zarządza programami i projektami, w tym monitorowaniem wyników oraz realizacji korzyści (BAI01.05–.06). APO05 równoważy portfel, a EDM02 zapewnia perspektywę Ładu nad wartością. Nie ograniczaj BAI01 do zakresu, terminu i budżetu."},"pbai02":{"kw":["bai02","wymagań"],"pulapka":"BAI02 spisuje, co rozwiązanie ma robić; jak je zbudować lub kupić to BAI03, a odbiór z użytkownikami to BAI07."},"pbai03":{"kw":["bai03","budowaniem rozwiązań"],"pulapka":"BAI03 projektuje, buduje lub kupuje rozwiązanie i testuje je w trakcie budowy; testy akceptacyjne z użytkownikami i odbiór to BAI07."},"pbai04":{"kw":["bai04","pojemności"],"pulapka":"BAI04 równoważy bieżące i przyszłe potrzeby dostępności, wydajności i pojemności z kosztami, ocenia możliwości, prognozuje potrzeby i usuwa problemy. DSS01 prowadzi eksploatację, a APO09 uzgadnia poziomy usług; DSS01 nie jest tylko dostawcą danych."},"pbai05":{"kw":["bai05","zmian organizacyjnych"],"pulapka":"Opór ludzi i stare nawyki to BAI05; podręcznikowa nazwa BAI06 „Zarządzanie zmianami” kusi, ale dotyczy zatwierdzania zmian w systemach."},"pbai06":{"kw":["bai06","zarządzanie zmianami"],"pulapka":"BAI06 ocenia, zatwierdza i wprowadza zmiany w działających systemach; nie wybiera inwestycji i nie zajmuje się przekonywaniem ludzi (BAI05)."},"pbai07":{"kw":["bai07","akceptacji"],"pulapka":"BAI07 to testy akceptacyjne z użytkownikami, odbiór i przejście do eksploatacji; zgoda na termin zmiany to BAI06, a testy w trakcie budowy BAI03."},"pbai08":{"kw":["bai08","zarządzanie wiedzą"],"pulapka":"BAI08 wspiera pozyskiwanie, utrzymywanie i dzielenie się wiedzą, także wiedzą ekspertów, której nie zapisano w formalnych źródłach. BAI10 dotyczy elementów konfiguracji i ich relacji; nie ograniczaj całej wiedzy do dokumentacji (Enabling Processes, BAI08.03, s. 160)."},"pbai09":{"kw":["bai09","aktyw"],"pulapka":"Podręcznikowa nazwa „Zarządzanie zasobami” myli: BAI09 dotyczy aktywów (sprzęt, licencje), a nie ludzi; Ład nad wszystkimi zasobami to EDM04."},"pbai10":{"kw":["bai10","konfiguracj"],"pulapka":"BAI10 opisuje elementy systemu, ich wersje i zależności (repozytorium konfiguracji); BAI06 korzysta z tego przy ocenie wpływu zmiany, a BAI09 ewidencjonuje aktywa."},"pdss01":{"kw":["dss01","eksploatacj"],"pulapka":"DSS01 to zaplanowana rutyna; przerwa w usłudze trafia do DSS02, a prognozowanie i planowanie pojemności to BAI04."},"pdss02":{"kw":["dss02","incydent"],"pulapka":"DSS02 przywraca usługę i obsługuje zwykłe prośby (np. założenie konta); szukanie przyczyny powtarzających się awarii to DSS03, a wprowadzenie poprawki BAI06."},"pdss03":{"kw":["dss03","problem"],"pulapka":"DSS03 szuka przyczyny źródłowej powtarzających się incydentów; samo przywrócenie działania to DSS02, a zmianę usuwającą przyczynę wprowadza BAI06."},"pdss04":{"kw":["dss04","ciągłości"],"pulapka":"DSS04 przygotowuje utrzymanie i odtworzenie krytycznych działań po zakłóceniach. Obejmuje ciągłość, odporność, plany, ćwiczenia i kopie zapasowe; nie ogranicza się do katastrofy ani odtworzenia serwera."},"pdss05":{"kw":["dss05"],"pulapka":"DSS05 obejmuje operacyjną ochronę informacji i IT: tożsamości i uprawnienia, ochronę przed złośliwym oprogramowaniem, monitorowanie zdarzeń, a także fizyczny dostęp do zasobów i ochronę dokumentów. System zarządzania bezpieczeństwem organizuje APO13."},"pdss06":{"kw":["dss06"],"pulapka":"DSS06 to kontrole wbudowane w proces biznesowy (np. „dwie pary oczu”); ocena, czy kontrole działają, to MEA02, a techniczne konta to DSS05."},"petla":{"kw":["pierścień","aktywowanie zmiany","zarządzanie programem"],"pulapka":"Pierścienie: zewnętrzny to zarządzanie programem, środkowy aktywowanie zmiany (kultura, zachowania), wewnętrzny ciągłe doskonalenie; ocena stanu obecnego to faza 2 „Gdzie jesteśmy teraz?”."},"pmea01":{"kw":["mea01"],"pulapka":"MEA01 mierzy wyniki i porównuje je z celami; przejrzystość wobec interesariuszy na poziomie Ładu to EDM05, a ocena mechanizmów kontrolnych to MEA02."},"pmea02":{"kw":["mea02","kontroli wewnętrznej"],"pulapka":"MEA02 ocenia, czy mechanizmy kontrolne działają; wbudowanie kontroli w proces biznesowy (np. dwie pary oczu) to DSS06, a rejestr ryzyk to APO12."},"pmea03":{"kw":["mea03","wymogami zewnętrznymi"],"pulapka":"MEA03 to zgodność z wymogami zewnętrznymi (przepisy, umowy); monitorowanie kierunku przez organ Ładu należy do EDM, więc nie każde monitorowanie to MEA."},"pomiar":{"kw":["faza 6","fazie 6","eksploatacja i pomiar"],"pulapka":"Faza 6 obejmuje realizację korzyści oraz obsługę i pomiar. W fazie 5 definiuje się lub doprecyzowuje miary powodzenia, ale cele i miary korzyści mogą być określone już wcześniej w uzasadnieniu biznesowym. Przegląd skuteczności programu należy do fazy 7."},"potrz":{"kw":["potrzeby interesariuszy","wyznacznik","kaskad"],"pulapka":"Zmiany otoczenia (przepisy, technologie, strategia) to wyznaczniki, które wpływają na potrzeby interesariuszy w kroku 1 kaskady; nie myl wyznacznika z samą potrzebą."},"prm":{"kw":["37 proces","referencyjn","32 procesy"],"pulapka":"PRM ma 37 procesów: 5 Ładu (EDM) i 32 Zarządzania (APO 13, BAI 10, DSS 6, MEA 3); model nie jest normatywny, więc nie trzeba wdrażać wszystkich."},"przeg":{"kw":["faza 7","fazie 7","ciągłego doskonalenia"],"pulapka":"Faza 7 ocenia skuteczność programu, utrzymuje zmianę i rozpoznaje dalsze wymagania. Może prowadzić do kolejnego cyklu usprawnień; nie oznacza automatycznie zakończenia całego doskonalenia. Realizacja korzyści i obsługa oraz pomiar należą do fazy 6."},"pz":{"kw":["punkt zapalny","punkty zapalne","punktu zapalnego"],"pulapka":"Punkt zapalny to dostrzegany problem uzasadniający usprawnienie, np. nieudane inwestycje, ustalenia audytu lub nieprzejrzyste koszty. Nie musi trwać określonego czasu. Zdarzenie wyzwalające jest bodźcem, np. fuzją lub zmianą kierownictwa."},"r12_a1":{"kw":["zasady, polityki","struktury ramowe","struktury ramowej"],"pulapka":"Egzamin PL mówi „Zasady, Polityki i Struktury ramowe” (podręcznik: metodyki); struktura ramowa to np. COBIT 5, a komitet to Struktura organizacyjna."},"r12_a2":{"kw":["procesy","uporządkowany zbiór"],"pulapka":"Procesy to uporządkowany zbiór praktyk i działań, który daje określone wyniki; kluczowe jednostki decyzyjne to Struktury organizacyjne, a procesy nie są zasobem."},"r12_a3":{"kw":["struktury organizacyjne","kluczowe jednostki"],"pulapka":"Zespół, który podejmuje decyzje (np. komitet), to Struktury organizacyjne, a nie Ludzie, umiejętności i kompetencje; nie myl go też ze Strukturą ramową."},"r12_a4":{"kw":["kultura, etyka","niedocenian"],"pulapka":"Kultura, etyka i zachowanie to „często niedoceniany” czynnik sukcesu Ładu i Zarządzania, a nie „przeceniany” ani „jedyny obowiązkowy”."},"r12_a5":{"kw":["informacja","zasob"],"pulapka":"Informacja jest aktywatorem i zarazem zasobem; dotyczy całej organizacji, a na poziomie operacyjnym bywa jej kluczowym produktem."},"r12_a6":{"kw":["usługi, infrastruktura","zasob"],"pulapka":"Usługi, infrastruktura i aplikacje to aktywator i zasób, który daje możliwości przetwarzania i usługi IT; awaria techniki dotyczy tego aktywatora, błędne dane – Informacji."},"r12_a7":{"kw":["ludzie, umiejętności","umiejętności behawioralne","zasob"],"pulapka":"Ludzie, umiejętności i kompetencje to zasób (umiejętności, decyzje, działania naprawcze); grupa decyzyjna to już Struktura organizacyjna, a zachowania to Kultura."},"r12_zas":{"kw":["zasobami","zasoby","rysunku 12"],"pulapka":"Zasobami są tylko trzy aktywatory: 5 Informacja, 6 Usługi, infrastruktura i aplikacje, 7 Ludzie, umiejętności i kompetencje; nie wszystkie siedem i nie Procesy."},"r13_c":{"kw":["cele aktywatora","kaskada celów"],"pulapka":"Cele aktywatora to ostatni etap kaskady celów i dzielą się na trzy kategorie: jakość wewnętrzna, kontekstowa oraz dostęp i bezpieczeństwo; kategorie nie są osobnymi wymiarami."},"r13_c1":{"kw":["jakość wewnętrzna","jakość rzeczywista"],"pulapka":"Egzamin: jakość wewnętrzna, podręcznik: jakość rzeczywista (dokładność, obiektywność, wiarygodność); to ta sama kategoria, tylko inna forma nazwy."},"r13_c2":{"kw":["jakość kontekstowa","kompletność"],"pulapka":"Jakość kontekstowa to dopasowanie do celu i sytuacji: istotność, kompletność, aktualność, zrozumiałość; dokładność i obiektywność należą do jakości wewnętrznej."},"r13_c3":{"kw":["dostęp i bezpieczeństwo","ograniczony dostęp"],"pulapka":"Dostęp i bezpieczeństwo to trzecia kategoria celów wewnątrz wymiaru Cele, a nie piąty wymiar aktywatora ani osobny aktywator."},"r13_i":{"kw":["wymiary aktywatora","interesariusze wewnętrzni"],"pulapka":"Interesariusze to jeden z czterech wymiarów aktywatora, obok celów, cyklu życia i dobrych praktyk; aktywatorów jest siedem, wymiarów cztery."},"r13_i1":{"kw":["interesariusze wewnętrzni","interesariusz"],"pulapka":"Interesariusze wewnętrzni (np. zarząd, kierownicy biznesu, dział IT) mają własne, niekiedy wykluczające się potrzeby; ich lista jest na Rysunku 7."},"r13_i2":{"kw":["interesariusze zewnętrzni","regulator"],"pulapka":"Interesariusze zewnętrzni to m.in. klienci, dostawcy, regulatorzy i audytorzy zewnętrzni; jeden aktywator zwykle ma interesariuszy po obu stronach."},"r13_m1":{"kw":["wskaźniki opóźnione","wskaźniki następujące"],"pulapka":"Egzamin: wskaźniki opóźnione (podręcznik: następujące); mierzą osiągnięcie celów i potrzeb interesariuszy, a nie stosowanie praktyk ani zdolność procesu."},"r13_m2":{"kw":["wskaźniki wiodące","wyprzedzające"],"pulapka":"Egzamin: wskaźniki wiodące (podręcznik: wyprzedzające); mierzą cykl życia i dobre praktyki, czyli czy dobrze pracujemy, zanim zobaczymy wynik."},"r13_p":{"kw":["dobre praktyki","produkty działań"],"pulapka":"Dobre praktyki obejmują praktyki oraz produkty działań; COBIT 5 podaje je dla niektórych aktywatorów (np. procesów), dla innych korzysta się z zewnętrznych standardów."},"r13_p1":{"kw":["dobre praktyki","praktyki procesu"],"pulapka":"Praktyki to tylko jedna część dobrych praktyk, drugą są produkty działań; dla procesów przykłady dobrych praktyk daje sam COBIT 5."},"r13_p2":{"kw":["produkty działań","produkty pracy","dane wejściowe"],"pulapka":"Produkty działań to dane wejściowe i wyniki praktyk; w modelu oceny procesu egzamin nazywa je produktami pracy (work products)."},"r13_qc":{"kw":["wskaźniki opóźnione","na podstawie mierników"],"pulapka":"Pytanie o osiągnięcie celów to wskaźnik opóźniony; na wszystkie cztery pytania odpowiada się na podstawie mierników, nie decyzji organu Ładu."},"r13_qi":{"kw":["cztery pytania","wskaźniki opóźnione"],"pulapka":"To pierwsze z czterech pytań; razem z pytaniem o cele mierzy wynik aktywatora wskaźnikami opóźnionymi (podręcznik: następującymi), nie wiodącymi."},"r13_qp":{"kw":["wskaźniki wiodące","dobre praktyki"],"pulapka":"Pytanie o dobre praktyki to wskaźnik wiodący; pytania 1–2 dotyczą wyniku (opóźnione), a 3–4 funkcjonowania aktywatora (wiodące)."},"r13_qz":{"kw":["wskaźniki wiodące","cyklem życia"],"pulapka":"Pytanie o cykl życia to wskaźnik wiodący (podręcznik: wyprzedzający), bo mierzy funkcjonowanie samego aktywatora, a nie jego wynik."},"r13_z":{"kw":["cykl życia","pozbywanie się"],"pulapka":"Cykl życia ma sześć faz, od planowania po aktualizację/pozbywanie się, i dotyczy każdego aktywatora, także informacji, struktur i polityk."},"r13_z1":{"kw":["cykl życia","planowanie"],"pulapka":"Planowanie obejmuje opracowanie i wybór koncepcji; nie myl sześciu faz cyklu życia aktywatora z siedmioma fazami cyklu wdrożenia."},"r13_z2":{"kw":["projektowanie","cykl życia"],"pulapka":"Projektowanie to druga z sześciu faz cyklu życia aktywatora: po planowaniu, przed budowaniem/nabywaniem/tworzeniem/wdrażaniem."},"r13_z3":{"kw":["nabywanie","cykl życia"],"pulapka":"Budowanie/nabywanie/tworzenie/wdrażanie to jedna faza z czterema czasownikami, nie cztery fazy; faz cyklu życia jest sześć."},"r13_z4":{"kw":["eksploatacja","użytkowanie"],"pulapka":"Użytkowanie/eksploatacja to czwarta faza cyklu życia; w tekście podręcznik pisze „użytkowanie/obsługa”, na rysunku „eksploatacja”, a to ta sama faza."},"r13_z5":{"kw":["monitorowanie","cykl życia"],"pulapka":"Ocena/monitorowanie to faza cyklu życia samego aktywatora; nie myl jej z domeną MEA ani z oceną zdolności procesu z Rysunku 19."},"r13_z6":{"kw":["pozbywanie się","aktualizacja"],"pulapka":"Ostatnia faza łączy aktualizację i pozbywanie się; np. umiejętności pozbywa się, gdy działanie zautomatyzowano lub zlecono na zewnątrz (Rysunek 38)."},"r18_a1":{"kw":["świadomoś","komunikow","cobit 4.1"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie dobre praktyki „świadomość” i „komunikowanie” aktywatora Kultura, etyka i zachowanie (Rysunek 34)."},"r18_a2":{"kw":["polityk","procedur","cobit 4.1"],"pulapka":"„Polityki, plany, procedury” to atrybut dojrzałości COBIT 4.1; nie myl go z aktywatorem COBIT 5 „Zasady, polityki i struktury ramowe”."},"r18_a3":{"kw":["narzędzi","automatyz","atrybut"],"pulapka":"„Narzędzia i automatyzacja” to atrybut COBIT 4.1; w COBIT 5 nie ma atrybutu o tej nazwie, a dziewięć atrybutów procesu oznacza się od PA 1.1 do PA 5.2."},"r18_a4":{"kw":["umiejętności","cobit 4.1"],"pulapka":"To atrybut dojrzałości COBIT 4.1, a nie aktywator COBIT 5 „Ludzie, umiejętności i kompetencje”; nazwy się zazębiają, ale to inne modele."},"r18_a5":{"kw":["raci","rozliczaln","odpowiedzialn"],"pulapka":"Atrybut 4.1 „odpowiedzialność i rozliczalność” to nie tabela RACI; RACI w COBIT 5 wiąże działania procesu z rolami i strukturami organizacyjnymi."},"r18_a6":{"kw":["pa 4.1","pomiar","cobit 4.1"],"pulapka":"Atrybut 4.1 „ustalanie celów i ich pomiar” to nie PA 4.1 „Pomiar procesu” z COBIT 5; nazwy i znaczenie poziomów obu modeli są zupełnie inne (s. 43)."},"r18_att":{"kw":["sześć atrybut","dziewięć","atrybut"],"pulapka":"COBIT 4.1 miał 6 atrybutów dojrzałości, COBIT 5 ma 9 atrybutów procesu (PA 1.1–5.2); nie są identyczne, tylko częściowo się pokrywają (Ilustracja 21)."},"r18_ck":{"kw":["cele kontrolne","model dojrzałości","cobit 4.1"],"pulapka":"W COBIT 4.1 najpierw sprawdzano realizację celów kontrolnych, potem stosowano model dojrzałości; COBIT 5 upraszcza ocenę, usuwając powielanie tych komponentów (s. 44)."},"r18_m0":{"kw":["proces niekompletny","dojrzałości","cobit 4.1"],"pulapka":"Poziom 0 COBIT 4.1 „Nie istnieje” to brak rozpoznania problemu; w COBIT 5 poziom 0 to „proces niekompletny”: proces niewdrożony lub cel nieosiągany."},"r18_m1":{"kw":["ad hoc","15504","cobit 4.1"],"pulapka":"Proces z poziomem 1 dojrzałości (Ad hoc) może w ISO/IEC 15504 dostać 0, jeśli nie osiąga wyników (Ilustracja 20); oceny w COBIT 5 są zwykle niższe."},"r18_m2":{"kw":["powtarzaln","proces zarządzany"],"pulapka":"„Powtarzalny” to nazwa poziomu 2 modelu dojrzałości COBIT 4.1; poziom 2 modelu zdolności COBIT 5 to „proces zarządzany”."},"r18_m3":{"kw":["proces ustanowiony","pa 3.1","zdefiniowan"],"pulapka":"„Zdefiniowany proces” (COBIT 4.1, poziom 3) kusi skojarzeniem z PA 3.1 „Definicja procesu”; poziom 3 COBIT 5 nazywa się „proces ustanowiony”."},"r18_m4":{"kw":["proces przewidywalny","zarządzany","cobit 4.1"],"pulapka":"„Zarządzany i wymierny” to poziom 4 COBIT 4.1; nie myl go z poziomem 2 COBIT 5 „proces zarządzany”. Poziom 4 COBIT 5 to „proces przewidywalny”."},"r18_m5":{"kw":["zoptymalizowan","optymalizując","poziom 5"],"pulapka":"Poziom 5 w obu modelach brzmi podobnie (4.1: zoptymalizowany; COBIT 5: proces optymalizujący), ale definicje i atrybuty są inne; wyników nie da się prosto przeliczyć."},"r18_mdl":{"kw":["model dojrzałości","cobit 4.1","15504"],"pulapka":"W COBIT 4.1 był osobny model dojrzałości dla każdego procesu; COBIT 5 ma jeden wspólny model zdolności oparty na ISO/IEC 15504 z 9 atrybutami."},"r18_mk":{"kw":["mechanizm","cobit 4.1","poziom"],"pulapka":"Mechanizmy kontrolne procesów (PC) z COBIT 4.1 częściowo pokrywały się z atrybutami dojrzałości; w COBIT 5 te wspólne wymagania przeniesiono na poziomy 2–5 modelu oceny."},"r19_l0":{"kw":["proces niekompletny","poziom 0","15504"],"pulapka":"Poziom 0 nie znaczy „brak procesu”: proces może istnieć i działać chaotycznie, ale nie osiąga celu; proces z poziomem 1 w COBIT 4.1 może tu dostać 0."},"r19_l1":{"kw":["proces wykonywany","pa 1.1","poziom 1"],"pulapka":"Poziom 1 wymaga osiągnięcia PA 1.1 co najmniej w znacznym stopniu (L), nie w pełni; to jedyny poziom z jednym atrybutem i już ważne osiągnięcie."},"r19_l2":{"kw":["proces zarządzany","pa 2.1","pa 2.2"],"pulapka":"Poziom 2 ma dwa atrybuty: PA 2.1 Zarządzanie wydajnością (planowanie, monitorowanie, dostosowanie) i PA 2.2 Zarządzanie produktami pracy; łatwo pomylić, który opis należy do którego."},"r19_l3":{"kw":["proces ustanowiony","pa 3.1","pa 3.2"],"pulapka":"Poziom 3 to standardowy proces zdefiniowany (PA 3.1) i faktycznie wdrożony (PA 3.2); samo spisanie procedury bez jej stosowania nie wystarcza."},"r19_l4":{"kw":["proces przewidywalny","pa 4.1","pa 4.2"],"pulapka":"Poziom 4 to proces przewidywalny: działa w zdefiniowanych limitach dzięki pomiarowi (PA 4.1) i kontroli (PA 4.2); nie myl z poziomem 4 COBIT 4.1 „zarządzany i mierzalny”."},"r19_l5":{"kw":["proces zoptymalizowany","optymalizujący","pa 5.1"],"pulapka":"Egzamin mówi „proces zoptymalizowany” (podręcznik: optymalizujący); poziom docelowy wybiera się z rachunku kosztów i korzyści i bardzo rzadko jest nim poziom 5."},"r19_pa11":{"kw":["pa 1.1","wykonanie procesu"],"pulapka":"PA 1.1 (egzamin: Wykonanie procesu, podręcznik: Sprawność procesu) ocenia się wskaźnikami wydajności, czyli praktykami bazowymi i produktami pracy, a nie typowymi praktykami."},"r19_pa21":{"kw":["pa 2.1","zarządzanie wydajnością"],"pulapka":"PA 2.1 dotyczy zarządzania samym wykonaniem (planowanie, monitorowanie, dostosowanie, przydział obowiązków); dbanie o produkty pracy to PA 2.2."},"r19_pa22":{"kw":["pa 2.2","produktami pracy"],"pulapka":"PA 2.2 sprawdza, czy produkty pracy są właściwie określone, kontrolowane i utrzymywane; mimo nazwy ocenia się go wskaźnikami potencjału, nie praktykami bazowymi."},"r19_pa31":{"kw":["pa 3.1","definicja procesu"],"pulapka":"PA 3.1 to istnienie i utrzymanie standardowego procesu; jego faktyczne stosowanie przez kompetentnych ludzi z potrzebną infrastrukturą to PA 3.2."},"r19_pa32":{"kw":["pa 3.2","wdrożenie procesu"],"pulapka":"PA 3.2 to wdrożenie standardowego procesu w każdym wykonaniu (ludzie, role, zasoby, infrastruktura); samo zdefiniowanie standardu to PA 3.1."},"r19_pa41":{"kw":["pa 4.1","miara procesu"],"pulapka":"Egzamin: Miara procesu (podręcznik: Pomiar procesu); PA 4.1 to zbieranie i analiza pomiarów, a utrzymywanie procesu w limitach to PA 4.2 Kontrola procesu."},"r19_pa42":{"kw":["pa 4.2","kontrola procesu"],"pulapka":"PA 4.2 utrzymuje proces w ustalonych limitach na podstawie pomiarów; to nie sam pomiar (PA 4.1) ani wprowadzanie zmian doskonalących (PA 5.2)."},"r19_pa51":{"kw":["pa 5.1","innowacja procesu"],"pulapka":"PA 5.1 (egzamin: Innowacja procesu) to wybór zmian na podstawie danych i nowych podejść; ich kontrolowane wprowadzenie i sprawdzenie skutku to PA 5.2."},"r19_pa52":{"kw":["pa 5.2","optymalizacja procesu"],"pulapka":"PA 5.2 to przemyślane wdrażanie wybranych zmian i sprawdzanie ich skutku; nie myl z PA 4.2, które tylko utrzymuje proces w limitach."},"r19_wpod":{"kw":["praktyki bazowe","podstawowe praktyki"],"pulapka":"Praktyki bazowe (podręcznik: podstawowe) to praktyki Ładu lub Zarządzania danego procesu; nie myl z typowymi (ogólnymi) praktykami, wspólnymi dla wszystkich procesów."},"r19_wpot":{"kw":["wymiar zdolności","wskaźniki potencjału"],"pulapka":"Wskaźniki potencjału (egzamin: Wymiar Zdolności) są wspólne dla wszystkich procesów i służą ocenie atrybutów PA 2.1–PA 5.2, czyli poziomów 2–5, nie poziomu 1."},"r19_wprd":{"kw":["produkty pracy","dane wejściowe"],"pulapka":"Produkty pracy (podręcznik: produkty działań) odpowiadają danym wejściowym i wynikom praktyk COBIT 5; razem z praktykami bazowymi należą do Wymiaru Procesu."},"r19_wtp":{"kw":["typowe praktyki","praktyki ogólne","ogólne praktyki"],"pulapka":"„Typowe” to tłumaczenie generic, czyli „ogólne”: te same praktyki dla wszystkich procesów, a nie praktyki najczęściej spotykane w danym procesie."},"r19_wtpd":{"kw":["typowe produkty","produkty pracy","wymiar zdolności"],"pulapka":"Typowe produkty działań są wspólne dla wszystkich procesów (Wymiar Zdolności); nie myl ich z produktami pracy konkretnego procesu z Wymiaru Procesu."},"r19_wtz":{"kw":["typowe zasoby","ogólne praktyki, zasoby"],"pulapka":"Typowe zasoby to ogólne zasoby (ludzie, narzędzia, infrastruktura) oceniane na poziomach 2–5 w każdym procesie; nie są wskaźnikiem wydajności poziomu 1."},"r19_wwyd":{"kw":["wymiar procesu","wskaźniki wydajności","praktyki bazowe"],"pulapka":"Wskaźniki wydajności (egzamin: Wymiar Procesu) są specyficzne dla danego procesu i służą ocenie poziomu 1; poziomy 2–5 ocenia się wskaźnikami potencjału."},"r19_wwyn":{"kw":["wyniki procesu","rezultaty procesu"],"pulapka":"Wyniki procesu (rezultaty) wraz z celem tworzą opis procesu w modelu referencyjnym; są wskaźnikiem wydajności poziomu 1, nie wskaźnikiem potencjału."},"r25_apo":{"kw":["apo","dostosuj, planuj i organizuj"],"pulapka":"APO (egzamin: Dostosuj, Planuj i Organizuj) to Zarządzanie z 13 procesami; na Rysunku 25 obejmują je m.in. TOGAF, PRINCE2/PMBOK i ISO/IEC 31000, nie ISO/IEC 38500."},"r25_bai":{"kw":["bai","twórz, nabywaj i wdrażaj"],"pulapka":"BAI (egzamin: Twórz, Nabywaj i Wdrażaj) ma 10 procesów; na Rysunku 25 odpowiadają mu głównie CMMI, PRINCE2/PMBOK i TOGAF, a ITIL jest najszerzej w DSS."},"r25_dss":{"kw":["dss","dostarczaj, obsługuj i wspieraj"],"pulapka":"DSS (egzamin: Dostarczaj, Obsługuj i Wspieraj) ma 6 procesów codziennej pracy; Rysunek 25 przypisuje mu najszerzej ITIL V3 2011 i ISO/IEC 20000."},"r25_edm":{"kw":["edm","38500","oszacuj, kieruj i monitoruj"],"pulapka":"EDM (egzamin: Oszacuj, Kieruj i Monitoruj) to jedyna domena Ładu; na Rysunku 25 tylko przy niej stoi ISO/IEC 38500, a ISO/IEC 31000 sięga też APO."},"r25_mea":{"kw":["mea","monitoruj, oszacuj i oceń"],"pulapka":"MEA (egzamin: Monitoruj, Oszacuj i Oceń) to Zarządzanie, nie Ład, mimo słowa „monitoruj”; EDM też monitoruje, ale z poziomu organu Ładu."},"r25_s27000":{"kw":["27001","apo13","dss05"],"pulapka":"Seria ISO/IEC 27000 to bezpieczeństwo informacji, na Rysunku 25 od APO do DSS (APO13, DSS05); nie myl z ISO/IEC 31000 o ryzyku."},"r25_s31000":{"kw":["zarządzanie ryzykiem","apo12"],"pulapka":"ISO/IEC 31000 to norma zarządzania ryzykiem, na Rysunku 25 w obszarze EDM i APO (EDM03, APO12); nie myl z ISO/IEC 27000 o bezpieczeństwie informacji."},"r25_s38500":{"kw":["38500","15504"],"pulapka":"ISO/IEC 38500 to podstawa koncepcji procesów Ładu (EDM); podstawą oceny zdolności procesów jest ISO/IEC 15504, nie 38500."},"r25_scmmi":{"kw":["bai03","15504"],"pulapka":"CMMI (rozwój) obejmuje głównie budowanie i nabywanie aplikacji w BAI oraz część procesów organizacyjnych i jakości w APO; normą oceny procesów COBIT 5 jest ISO/IEC 15504."},"r25_sitil":{"kw":["itil","dss"],"pulapka":"ITIL V3 2011 i ISO/IEC 20000 na Rysunku 25 zaczynają się w APO, a najszerzej obejmują DSS; ITIL to usługi, nie zarządzanie projektami (PRINCE2/PMBOK)."},"r25_sprince":{"kw":["prince2","pmbok"],"pulapka":"Załącznik E wiąże PRINCE2/PMBOK z obszarem APO i BAI. Te wytyczne dotyczą zarządzania projektami; samo takie mapowanie nie czyni z nich pełnej metody zarządzania portfelem lub programami. COBIT 5 korzysta z powiązanych wytycznych i ich nie zastępuje."},"r25_stogaf":{"kw":["togaf","apo03"],"pulapka":"TOGAF 9 dotyczy architektury korporacyjnej (APO03) i daje techniczny model referencyjny; projektowanie i wykonywanie usług opisuje ITIL, a nie TOGAF."},"sC":{"kw":["częściowy","partially"],"pulapka":"Na egzaminie PL C = Częściowy (>15–50%); w podręczniku i po angielsku to P (Partially), a P na egzaminie PL oznacza Pełny."},"sN":{"kw":["nieosiągnięty","0–15%"],"pulapka":"N to 0–15%: dokładnie 15% to jeszcze N, a nie C. Ocena N dotyczy atrybutu, a nie tego, czy proces w ogóle istnieje."},"sP":{"kw":["pełny","fully","w pełni"],"pulapka":"P w PL to Pełny, EN F: ponad 85% do 100%, z dowodami kompletnego i systematycznego osiągania oraz bez istotnych słabości. Nie wymaga zawsze 100%. Przykład rozgrzewki ilustruje jeden aspekt; ocena atrybutu wymaga odpowiednich dowodów. Do wyższego poziomu wszystkie niższe atrybuty muszą mieć P."},"sW":{"kw":["większościowy","largely"],"pulapka":"W (>50–85%, EN: L – Largely) wystarcza dla atrybutów bieżącego poziomu, ale atrybuty wszystkich niższych poziomów muszą mieć P."},"wart":{"kw":["tworzenie wartości","realizacja korzyści","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości równoważy realizację korzyści, optymalizację ryzyka i optymalizację zasobów. Sama redukcja kosztów lub minimalizacja ryzyka nie jest pełną definicją tworzenia wartości, choć konkretna decyzja może obejmować takie działania."},"ws1":{"kw":["wskaźniki wykonania","praktyki bazowe","wymiar procesu"],"pulapka":"Wymiar procesu wykorzystuje rezultaty procesu, praktyki bazowe i produkty pracy jako wskaźniki osiągania jego przeznaczenia. Wspierają ocenę PA 1.1; nie są po prostu trzema osobnymi poziomami zdolności."},"ws2":{"kw":["wymiar zdolności","wskaźniki zdolności","wskaźniki potencjału"],"pulapka":"Typowe praktyki, zasoby i produkty pracy pomagają oceniać ogólne atrybuty poziomów 2–5 na Rysunku 19. Cały wymiar zdolności obejmuje także PA 1.1, oceniany z wykorzystaniem wskaźników wykonania procesu."},"wym0":{"kw":["wymiar","wydajnością aktywatora","rysunek 13"],"pulapka":"Wymiary są cztery: interesariusze, cele, cykl życia, dobre praktyki; zarządzanie wydajnością (podręcznik: sprawnością) aktywatora to pomiar, a nie piąty wymiar."},"wym1":{"kw":["interesariusze wewnętrzni","potrzeby interesariuszy","uwzględniono potrzeby"],"pulapka":"Interesariusze aktywatora są wewnętrzni i zewnętrzni; pytanie „Czy uwzględniono potrzeby interesariuszy?” mierzą wskaźniki opóźnione, a nie wiodące."},"wym2":{"kw":["jakość wewnętrzna","jakość kontekstowa","dostęp i bezpieczeństwo"],"pulapka":"Na egzaminie „jakość wewnętrzna” (podręcznik: rzeczywista); „dostęp i bezpieczeństwo” to kategoria celów w wymiarze Cele, a nie piąty wymiar aktywatora."},"wym3":{"kw":["cykl życia","zarządzanie cyklem życia"],"pulapka":"Cykl życia aktywatora obejmuje planowanie, projektowanie, tworzenie lub nabycie, użytkowanie, ocenę i aktualizację lub wycofanie. Proces jest aktywatorem i ma taki cykl życia. Odróżnij go od siedmiu faz wdrożenia COBIT oraz od pojedynczego wykonania procesu."},"wym4":{"kw":["dobre praktyki","stosowane są dobre praktyki","produkty pracy"],"pulapka":"Dobre praktyki to praktyki i produkty pracy (dane wejściowe i wyniki), czyli sugestie, jak wdrożyć aktywator; nie myl ich z celami, które opisują oczekiwane rezultaty."},"wynik":{"kw":["analiza luk","luk","szybkie korzyści"],"pulapka":"Lukę między stanem docelowym i obecnym analizuje faza 3. W fazie 4 rozwija się projekty i ich uzasadnienia biznesowe; wstępne uzasadnienie powstaje już wcześniej i jest aktualizowane przez cały cykl."},"z1":{"kw":["realizacja potrzeb interesariusza","tworzenie wartości","optymalizacja ryzyka"],"pulapka":"Tworzenie wartości to korzyści przy optymalnym ryzyku i optymalnym wykorzystaniu zasobów; podchwytliwe są „maksymalne korzyści” albo „minimalne ryzyko”."},"z23":{"kw":["pokrycie całej organizacji","pojedyncza zintegrowana"],"pulapka":"Zasada 2: Ład IT jest częścią ładu korporacyjnego i obejmuje całą organizację; prosta architektura porządkująca wytyczne i spinanie innych standardów to już zasada 3."},"z4":{"kw":["holistycznego podejścia","aktywator"],"pulapka":"Zasada 4 mówi o siedmiu aktywatorach działających razem; „Zasady, polityki i struktury ramowe” to aktywator, a nie zasada, mimo słowa „zasady”."},"z5":{"kw":["oddzielenie ładu od zarządzania","zasada 5"],"pulapka":"Ład i Nadzór są odpowiednikami tłumaczenia Governance. W Referencyjnym Modelu Procesu EDM obejmuje procesy Ładu, a APO, BAI, DSS i MEA procesy Zarządzania. Prawidłowy synonim nie staje się błędem tylko przez inną wersję tłumaczenia."},"zarz":{"kw":["pbrm","zarządzani","planuj"],"pulapka":"Zarządzanie planuje, tworzy, realizuje i monitoruje działania zgodnie z kierunkiem Ładu. W modelu procesów obejmuje 32 procesy APO, BAI, DSS i MEA. Ład i Zarządzanie wykorzystują również pozostałe aktywatory, nie same procesy."},"zi":{"kw":["zdarzenie wyzwalające","zdarzenia wyzwalające"],"pulapka":"Podręcznik: „zdarzenia inicjujące”, egzamin: „zdarzenia wyzwalające”; to zmiany (fuzja, nowe przepisy, nowy CEO), a stałe warunki, jak apetyt na ryzyko, to czynniki środowiska."},"f1":{"kw":["faza 1"],"pulapka":"To faza 1, nie ocena stanu obecnego."},"f2":{"kw":["faza 2"],"pulapka":"Stan docelowy określisz dopiero w fazie 3."},"f3":{"kw":["faza 3"],"pulapka":"Stan docelowy to pierścień doskonalenia; komunikacja wyniku to pierścień zmiany."},"f4":{"kw":["faza 4"],"pulapka":"Budowanie usprawnień w fazie 4 odróżnij od ich wdrażania w fazie 5."},"f5":{"kw":["faza 5"],"pulapka":"Nie myl fazy 5 z pomiarem i obsługą z fazy 6."},"f6":{"kw":["faza 6"],"pulapka":"Obsługa i pomiar to faza 6, a nie 4."},"f7":{"kw":["faza 7"],"pulapka":"Monitorowanie i ocena w wewnętrznym pierścieniu to faza 7."}};
